pair<rat, rat> solve(Z N, rat A, rat B, rat C) {
  static Combinations<rat> comb(1000000);
  if (A == 0) {
    return {0, 0};
  }
  rat prob = 0, avg = 0, an = A.pow(N);
  for (auto b = 0; b < N; b++) {
    rat p = comb.combination(N + b - 1, b) * B.pow(b) * an;
    prob += p;
    avg += p * (N + b) / rat(1ll - C);
  }
  return {prob, avg / prob};
}


