class C_cls {
  static const int N = 1000000;
  vector<Int> facts;
public:
  C_cls() : facts(vector<Int>(N, 1)){
    FOR(i,1,N) facts[i] = facts[i-1] * Int(i);
  }
  Int choose(int n, int r) { return facts[n] / (facts[r] * facts[n-r]); }
};

C_cls C;



int main() {
  int N, A, B, c;
  while (cin >> N >> A >> B >> c) {
    Int result = 0;
    Int Ap = Int(A) / Int(100 - c);
    Int Bp = Int(B) / Int(100 - c);
    Int Cp = Int(100 - c) / Int(100);

    REP(b,N) {
      result += C.choose(N-1+b, N-1) * power(Ap, N) * power(Bp, b) * Int(N+b);
    }

    REP(a,N) {
      result += C.choose(N-1+a, N-1) * power(Bp, N) * power(Ap, a) * Int(N+a);
    }
    result /= Cp;
    cout << result << endl;
  }
}

