		}
		ConvQuery co(n * 3);
		mint ap = a / (mint(1)-c);
		mint bp = b / (mint(1)-c);

		mint ans = 0;
		REP(i, n) {
			ans += co(n - 1 + i, i) * ap.pow(n) * bp.pow(i) * (n + i);
			ans += co(n - 1 + i, i) * ap.pow(i) * bp.pow(n) * (n + i);
		}

		if(c == 1) {
			cout << ans << endl;
		} else {
			cout << ans / (mint(1)-c) << endl;
		}
	}
	return 0;
}


