        ans %= MOD;
        e >>= 1;
        b *= b;
        b %= MOD;
    }
    return ans;
}

void pp(int i, int a, int b) {
// factorial
    fact[0] = 1;
    for (int k=1;k<2*i;k++) {
        fact[k] = fact[k-1] * k % MOD;
    }
// factorial inverse
    factinv[0] = 1;
    for (int k=1;k<2*i;k++) {
        factinv[k] = exp(fact[k],MOD-2);
    }
// exponential
    expa[0] = 1;
    for (int k=1;k<=i;k++){
        expa[k] = exp(a,k);
    }
    expb[0] = 1;
    for (int k=1;k<=i;k++){
        expb[k] = exp(b,k);
    }
    expabinv[0] = 1;
    for (int k=1;k<=2*i;k++) {
        expabinv[k] = exp(a+b,MOD-k-1);
    }
}

