i64 extgcd(i64 a, i64 b, i64 &x, i64 &y) {
    i64 d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1;
        y = 0;
    }
    return d;
}

i64 mod_inverse(i64 a, i64 m) {
    i64 x, y;
    if (extgcd(a, m, x, y) == 1) return (x + m) % m;
    return 0;
}

vector<i64> fact;
void init_fact(i64 n, i64 m) {
    fact.resize(n + 1);
    fact[0] = fact[1] = 1;
    for (i64 i = 2; i <= n; ++i) fact[i] = (i * fact[i - 1]) % m;
}


i64 mod_comb(i64 n, i64 k, i64 p) {
    if (n < 0 or k < 0 or n < k) return 0;
    i64 num=fact[n]*mod_inverse(fact[n-k],p)%p,den=fact[k];
    return num * mod_inverse(den, p) % p;
}


void solve() {
    const i64 mod = 1'000'000'007;
    init_fact(200010,mod);

    i64 N,A,B,C;
    cin >> N >> A >> B >> C;

    vector<i64> p(N+1),q(N+1);
    p[0]=1;
    rep(i,1,N+1){
        p[i]=p[i-1]*A%mod*mod_inverse(A+B,mod)%mod;
    }

    q[0]=1;
    rep(i,1,N+1){
        q[i]=q[i-1]*B%mod*mod_inverse(A+B,mod)%mod;
    }

    i64 ans=0;
    rep(i,0,N){
        i64 tmp=mod_comb(N+i-1,i,mod)*p[N]%mod*q[i]%mod;
        ans+=tmp*(((N+i)+(N+i)*C%mod*mod_inverse(100-C,mod)%mod)%mod)%mod;
        ans%=mod;
    }
    rep(i,0,N){
        i64 tmp=mod_comb(N+i-1,i,mod)*q[N]%mod*p[i]%mod;
        ans+=tmp*(((N+i)+(N+i)*C%mod*mod_inverse(100-C,mod)%mod)%mod)%mod;
        ans%=mod;
    }

    cout << ans << endl;
}

