namespace mint {
  constexpr int md = 1e9 + 7;
  inline void add (int &a, int b) {
    a += b; if (a >= md) a -= md;
  }
  inline void sub (int &a, int b) {
    a -= b; if (a < 0) a += md;
  }
  inline int sum (int a, int b) {
    add(a, b); return a;
  }
  inline int dif (int a, int b) {
    sub(a, b); return a;
  }
  template<class... A>
  inline int prod (A... args) {
    long long ret = 1;
    for (int a : initializer_list<int>{args...}) {
      ret *= a;
    }
    return (int)(ret % md);
  }
  inline void mul (int &a, int b) {
    a = prod(a, b);
  }
  inline int inv (int a) {
    a %= md;
    if(a < 0) a += md;
    int b = md, u = 0, v = 1;
    while (a) {
      int t = b / a;
      b -= a * t; swap(a, b);
      u -= v * t; swap(u, v);
    }
    assert(b == 1);
    if(u < 0) u += md;
    return u;
  }
  inline int quat (int a, int b) {
    return prod(a, inv(b));
  }
  inline void div (int& a, int b) {
    a = quat(a, b);
  }
  inline int pow (int a, long long b) {
    int res = 1;
    for (; b; b >>= 1) {
      if (b & 1) mul(res, a);
      mul(a, a);
    }
    return res;
  }
}
struct factorials {
  const int sz;
  vector<int> fct, fnv;
  factorials (int n)
    : sz(n)
    , fct(n, 1)
    , fnv(n, 1)
    {
      for (int i = 1; i < n; i++) fct[i] = mint::prod(fct[i - 1], i);
      fnv[n - 1] = mint::inv(fct[n - 1]);
      for (int i = n - 1; i >= 1; i--) fnv[i - 1] = mint::prod(fnv[i], i);
    }
  inline int binom (int n, int k) {
    assert(0 <= k && k <= n && n < sz);
    return mint::quat(fct[n], mint::prod(fnv[k], fnv[n - k]));
  }
};
