  }
  mint::mul(ret0, mint::pow(q, n));
  int ret1 = 0;
  for (int j = 0, qj = 1, w = mint::prod(n, x); j < n; j++) {
    mint::add(ret1, mint::prod(qj, fct.binom(n - 1 + j, j), w));
    mint::mul(qj, q);
    mint::add(w, x);
  }
