	for(int i = 2; i < N; ++i)
	{
		fact[i] = fact[i - 1] * i % MOD;
		inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
		finv[i] = finv[i -1] * inv[i] % MOD;
	}
}

ll C(int a, int b)
{
	if(a < b) return 0;
	return fact[a] * (finv[b] * finv[a - b] % MOD) % MOD;
}

ll exp(ll a, ll b)
{
	ll res = 1;
	while(b)
	{
		if(b & 1)
			res = res * a % MOD;
		b >>= 1;
		a = a * a % MOD;
	}
	return res;
}

