struct PrimeNumber {
    const ll MOD = 1000000007;  // 10**9 + 7
    ll add(ll a, ll b)
    {
        return (a + b) % MOD;
    }
    ll sub(ll a, ll b)
    {
        return (a + MOD - b) % MOD;
    }
    ll mul(ll a, ll b)
    {
        return ((a % MOD) * (b % MOD)) % MOD;
    }
    ll power(ll x, ll y)
    {
        if (y == 0) {
            return 1;
        }
        else if (y == 1) {
            return x % MOD;
        }
        else if (y % 2 == 0) {
            ll t = this->power(x, y / 2);
            return this->mul(t, t);
        }
        else {
            ll t = this->power(x, y / 2);
            return this->mul(this->mul(t, t), x);
        }
    }
    ll div(ll a, ll b)
    {
        return this->mul(a, this->power(b, MOD - 2));
    }

    #define FACTORIAL_MAX 1000000
    ll memo_factorial[FACTORIAL_MAX+1];
    void init_factorial(void)
    {
        this->memo_factorial[0] = 1;
        for (ll i = 1; i <= FACTORIAL_MAX; ++i) {
            this->memo_factorial[i] = this->mul(i, this->memo_factorial[i-1]);
        }
    }
    ll factorial(ll n)
    {
        return this->memo_factorial[n];
    }
    ll combination(ll n, ll r)
    {
        ll ret = this->factorial(n);
        ret = this->div(ret, this->factorial(r));
        ret = this->div(ret, this->factorial(n-r));
        return ret;
    }
};


void solve()
{
    PrimeNumber prime;
    prime.init_factorial();
    ll N,A,B,C;
    cin >> N >> A >> B >> C;
    ll p = prime.div(A,A+B);
    ll q = prime.div(B,A+B);
    ll pn = prime.power(p,N);
    ll qn = prime.power(q,N);

    // N : i
    ll qi = 1;
    ll ans = 0;
    for1(i,N) {
        ll a1 = prime.mul(N+i, prime.mul(pn,qi));
        a1 = prime.mul(a1, prime.combination(N-1+i,i));
        ans = prime.add(ans, a1);
        qi = prime.mul(qi,q);
    }
    // i : N
    ll pi = 1;
    for1(i,N) {
        ll a1 = prime.mul(N+i, prime.mul(qn,pi));
        a1 = prime.mul(a1, prime.combination(N-1+i,i));
        ans = prime.add(ans, a1);
        pi = prime.mul(pi,p);
    }
    ans = prime.mul(ans, prime.div(A+B+C,A+B));
    cout << ans << endl;
}

int main()
{
    do {
        solve();
    } while (DEBUG);
}

