const long double Pi=acos(-1.0);
int rev[N];
void get(int l){for(int i=1;i<(1<<l);++i) rev[i]=(rev[i>>1]>>1)|((i&1)<<l-1);}
void FFT(Comp A[],int f)
{
    for(int i=0;i<len;++i) if(rev[i]<i) swap(A[i],A[rev[i]]);
    for(int l=2;l<=len;l<<=1)
    {
        Comp wn=Comp(cos(2*Pi/l),f*sin(2*Pi/l));
        for(int i=0;i<len;i+=l)
        {
            Comp w=Comp(1,0);
            for(int k=i;k<i+(l>>1);++k,w=w*wn)
            {
                Comp t1=A[k],t2=A[k+(l>>1)]*w;
                A[k]=t1+t2,A[k+(l>>1)]=t1-t2;
            }
        }
    }
    if(f==-1) for(int i=0;i<len;++i) A[i]=A[i]/len;
}
Comp T[N];
void DFT(int A[],int B[],Comp a[],Comp b[])
{
    for(int i=0;i<len;++i) T[i]=Comp(A[i],B[i]); FFT(T,1);
    for(int i=0;i<len;++i)
    {
        int j=(len-i)%len;
        a[i]=(T[i]+T[j].conj())*Comp(0.5,0);
        b[i]=(T[i]-T[j].conj())*Comp(0,-0.5);
    }
}
void IDFT(Comp A[],Comp B[],int a[],int b[])
{
    for(int i=0;i<len;++i) T[i]=A[i]+B[i]*Comp(0,1); FFT(T,-1);
    for(int i=0;i<len;++i) a[i]=((ll)(T[i].a+0.5))%mod,b[i]=((ll)(T[i].b+0.5))%mod;
}	
