  rep(i, 3 * N - 1) {
    Ap[i + 1] = Ap[i] * A;
    Bp[i + 1] = Bp[i] * B;
    ABp[i + 1] = ABp[i] * (A + B);
  }


  mint ans = 0;
  repp(i, N, 2 * N - 1) {
    mint temp = 1;
    temp *= COM(i - 1, N - 1);
    temp *= Ap[N] * Bp[i - N] + Ap[i - N] * Bp[N];
    temp *= i;
    temp /= ABp[i];
    ans += temp;
  }

  ans *= 100;
  ans /= (100 - C);
  cout << ans << "\n";
}

