#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define N 300005
#define mod 1000000007

int add(int x,int y) {
  int ret = ((x+y)%mod+mod)%mod;
  if(ret<0) {
    ret+= mod;
  }
  assert(ret>=0 && ret<mod);
  return ret;
}
int mul(int x,int y) {
  ll ret = x;
  ret*=y;
  ret%=mod;
  assert(ret>=0 );
  return ret%mod;
}
int mypow(int x,int c) {
  int ret = 1;
  while(c>0) {
    if(c&1) {
      ret = mul(ret,x);
    }
    c/=2;
    x = mul(x,x);
  }
  return ret;
}

int fac[N];

int combination(int n,int r) {
  return mul(fac[n], mul(mypow(fac[r],mod-2) , mypow(fac[n-r],mod-2)));
}

void solve() {
  fac[0] = 1;
  int n,a,b,c;scanf("%d %d %d %d ", &n,&a,&b,&c);

  a = mul(a, mypow(100-c,mod-2));
  b = mul(b, mypow(100-c,mod-2));
  for(int i=1;i<N;++i) {
    fac[i] = mul(fac[i-1],i);
  }

  int ret = 0,z = add(1,-c);
  z = mypow(z,mod-2);
  z = mul(100, mypow(add(100,-c),mod-2));
  for(int i=n;i<=2*n-1;++i)   {
    int tmp = mul(i,z);
    int combi = combination(i-1,n-1);
