/* 二項係数 C(n,k) mod p を計算 */
const int MAX = 114514 * 2;
long long fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++){
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

long long COM(int n, int k){
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll modpow(ll a , ll b){
  if (b == 0) return 1;

  if (b%2 == 0){
    ll  t = modpow(a, b/2)%MOD;
    return t*t % MOD;
  }else{
    ll t = modpow(a, (b-1)/2)%MOD;
    return a*t %MOD * t % MOD;
  }
}

ll inverse (ll a){
  return modpow(a,MOD-2)%MOD;
}

int main() {
  int N, A, B, C;
  cin >> N >> A >> B >> C;

  COMinit();
  ll ans = 0;

  ll pa = A*inv[A+B] %MOD;
  ll pb = B*inv[A+B] %MOD;

  REP(i, N){
    ans   += (modpow(pa, N) * modpow(pb, i) % MOD
             + modpow(pa, i) * modpow(pb, N) % MOD)
             * (N+i) % MOD
             * COM(N+i-1, i) % MOD
             ;
    ans %= MOD;
  }
  ans *= 100 % MOD * inv[100-C] % MOD;
  ans %= MOD;
  cout << ans << endl;
}

