const int MOD = 1000000007;

class Combination {
    vector<ll> factorial;
    vector<ll> fact_inverse;
    vector<ll> inverse;
    int mod;

    void init(int size) {
        factorial[0] = 1;
        factorial[1] = 1;
        fact_inverse[0] = 1;
        fact_inverse[1] = 1;
        inverse[1] = 1;

        for (int i = 2; i < size; i++) {
            factorial[i] = factorial[i - 1] * i % mod;
            inverse[i] = mod - inverse[mod % i] * (mod / i) % mod;
            fact_inverse[i] = fact_inverse[i - 1] * inverse[i] % mod;
        }
    }

    public:
        Combination(int size, int m) {
           factorial = vector<ll>(size);
           fact_inverse = vector<ll>(size);
           inverse = vector<ll>(size, 0);
           mod = m;
           init(size);
        }

        ll calc(int n, int k) {
            if (n < k) {
                return 0;
            }
            if (n < 0 || k < 0) {
                return 0;
            }
            return factorial[n] * (fact_inverse[k] * fact_inverse[n - k] % mod) % mod;
        }

        ll inv(int n) {
            return inverse[n];
        }
};

long long pow_mod(long long n, long long p, long long mod) {
    if (p == 0) {
        return 1;
    } else if (p % 2 == 1) {
        return pow_mod(n, p - 1, mod) * n % mod;
    } else {
        long long s = pow_mod(n, p / 2, mod);
        return s * s % mod;
    }
}

int main() {
    ll n, a, b, c;
    cin >> n >> a >> b >> c;
    Combination com = Combination(max(a + b, n) * 2, MOD);

    ll pa = a * com.inv(a + b) % MOD;
    ll pb = b * com.inv(a + b) % MOD;
    ll p = 0;
    REP(i, n) {
        p += com.calc(i + n - 1, i) * pow_mod(pb, i, MOD) % MOD * pow_mod(pa, n, MOD) % MOD * (i + n) % MOD;
        p += com.calc(i + n - 1, i) * pow_mod(pa, i, MOD) % MOD * pow_mod(pb, n, MOD) % MOD * (i + n) % MOD;
        p %= MOD;
    }
    p = p * com.inv(a + b) % MOD * 100 % MOD;
    cout << p << endl;
}

