// factorial(階乗)の計算
const int N_MAX = pow(10,5)*3;
ll fac[N_MAX+1] ={};
ll c_fac(int n=N_MAX) {
  if (fac[n]!=0) return fac[n];
  if (n==0) return fac[n]=1;
  return fac[n] = (c_fac(n-1)*n)%MOD;
}

// inverse(逆元)の計算
ll inv(ll a,ll m=MOD) {
  ll b = m, x = 1, y = 0;
  while (b!=0) {
    ll d = a/b;
    a -= b*d; swap(a, b);
    x -= y*d; swap(x, y);
  }
  return x>=0 ? x : x+m;
}

// combinataionの計算
ll nck(ll n, ll k) { 
  c_fac(n);
  if (n<k) return 0;
  ll nume = fac[n];
  ll deno = ( inv(fac[n-k]) * inv(fac[k]) ) % MOD;
  return ( nume * deno ) % MOD;
}

int main() {
  ll N, A, B, C; cin >> N >> A >> B >> C;
  ll result = 0, deno = 1;
  ll ma[N+1] = {}; ma[0] = 1; repr(i,1,N+1) { ma[i] = ma[i-1]*A; ma[i] %= MOD; }
  ll mb[N+1] = {}; mb[0] = 1; repr(i,1,N+1) { mb[i] = mb[i-1]*B; mb[i] %= MOD; }
  repr(i,1,2*N) {
    deno *= A+B; deno %= MOD;
    if (i>=N) {
      ll r1 = nck(i-1,i-N);
      ll r21 = ((ma[N]*mb[i-N])%MOD*inv(deno))%MOD;
      ll r22 = ((ma[i-N]*mb[N])%MOD*inv(deno))%MOD;
      ll r3 = i;
      // cout << i << ":" << r1 << " " << r21 << " " << r22 << " " << r3 << endl;
      result += (((r1*(r21+r22))%MOD)*r3)%MOD;
      result %= MOD;
    }
  }
  result *= (100*inv(100-C))%MOD; result %= MOD;
  cout << result << endl;
  return 0;
}

