ll comb(ll n, ll r) {
    if (fact[0]==0) {
        fact[0] = factr[0] = inv[1] = 1;
        for (int i=2; i<=MAXS; i++) inv[i] = inv[mod%i] * (mod-mod/i) %mod;
        for (int i=1; i<=MAXS; i++) fact[i] = fact[i-1]*i %mod, factr[i] = factr[i-1]*inv[i] %mod;
    }
    if (r<0 || n<r) return 0;
    return fact[n]*factr[r] %mod *factr[n-r] %mod;
}
