typedef long long ll;
using namespace std;
const ll MOD = 1000000007LL;

const int MAX_N = 2000000;
ll inv[MAX_N], fac[MAX_N], fiv[MAX_N];
void COMinit() {
    inv[1] = fac[1] = fiv[1] = inv[0] = fac[0] = fiv[0] = 1;
    for (ll i = 2; i < MAX_N; i++) {
        fac[i] = fac[i - 1] * i % MOD; // n!
        inv[i] = inv[MOD % i] * (MOD - MOD / i) % MOD; // n^-1
        fiv[i] = fiv[i - 1] * inv[i] % MOD; // (n!)^-1
    }
}
ll com(ll n, ll k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * fiv[k] % MOD * fiv[n-k] % MOD;
}

ll pow_mod(ll num, ll pow, ll mod) {
    ll prod = 1;
    num %= mod;
    while (pow > 0) {
        if (pow & 1) prod = prod * num % mod;
        num = num * num % mod;
        pow >>= 1;
    }
    return prod;
}

int main() {
    cin.sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    ll n, a, b, c;
    cin >> n >> a >> b >> c;
    COMinit();

    a = a * inv[100] % MOD;
    b = b * inv[100] % MOD;
    c = c * inv[100] % MOD;

    ll ret = 0;

    for (ll i = 0; i < n; i++) {
        ll tmp = com(n+i-1, i) * pow_mod(a, n, MOD) % MOD * pow_mod(b, i, MOD) % MOD;
        tmp = tmp * pow_mod(pow_mod(a + b, n + i, MOD), MOD - 2, MOD) % MOD;
        ret += (n+i) * pow_mod(a+b, MOD - 2, MOD) % MOD * tmp % MOD;
        ret %= MOD;
    }

    for (ll i = 0; i < n; i++) {
        ll tmp = com(n+i-1, i) * pow_mod(b, n, MOD) % MOD * pow_mod(a, i, MOD) % MOD;
        tmp = tmp * pow_mod(pow_mod(a + b, n + i, MOD), MOD - 2, MOD) % MOD;
        ret += (n+i) * pow_mod(a+b, MOD - 2, MOD) % MOD * tmp % MOD;
        ret %= MOD;
    }

    cout << ret << "\n";
    return 0;
}

