ll fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (int i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % MOD;
		inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}

ll COM(ll n, ll k) {
	if (n < k) return 0;
	if (n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll iv(ll i) {
	if (i == 1) { return 1; }
	return MOD - iv(MOD%i)*(MOD / i) % MOD;
}

int main() {

	COMinit();

	ll N, A, B, C;
	cin >> N >> A >> B >> C;


	ll pa[MAX], pb[MAX], pab[MAX];
	pa[0] = 1;
	pb[0] = 1;
	pab[0] = 1;
	repn(i, MAX) {
		pa[i] = pa[i - 1] * A%MOD;
		pb[i] = pb[i - 1] * B%MOD;
		pab[i] = pab[i - 1] * (A + B) % MOD;
	}

	ll si = 0;

	rep(i, N) {
		ll X = (pa[N] * pb[i] + pa[i] * pb[N]) % MOD;
		X = X * pab[N - 1 - i]%MOD;
		X = X * COM(N + i - 1, i) % MOD;
		//cout << X << endl;
		X = X * (N + i) % MOD;
		si = (si + X) % MOD;
	}

	si = si * (A+B+C) % MOD;

	ll bo = pab[2*N-1] * (A+B) % MOD;

	//cout << si << " " << bo<<endl;

	ll ans = si * iv(bo) % MOD;
	cout << ans;


	system("PAUSE");
}

