const ll mod=1e9+7;

ll d1[300100],d2[300100];

ll mult(ll n,ll m){//n^m%modを求める
    if(m==1){
        return n%mod;
    }else if(m%2==0){//オーバーフロー防止のためにn^(m/2)*n^(m/2)を考える
        ll t=mult(n,m/2);
        return (t*t)%mod;
    }else{//奇数の時はn^(m-1)*nを考える
        ll t=mult(n,m-1);
        return (t*n)%mod;
    }
}

void make_table(ll N){
	for(ll i=0;i<=N;i++){
		if(i==0){
			d1[i]=1;
			d2[i]=1;
		}else{
			d1[i]=(i*d1[i-1])%mod;
			d2[i]=mult(d1[i],mod-2);
		}
	}
}

template <class T>
T comb_mod_2(T n,T k){
    return (((d1[n]*d2[n-k])%mod)*d2[k])%mod;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    make_table(200000);
    ll n,a,b,c;
    cin>>n>>a>>b>>c;
    ll ans=0;
    ll x=mult(a+b,mod-2);
    rep(i,n){
      ll cnt,cnt1=1,cnt2=1;
      cnt1*=mult(a,n);
      cnt1*=mult(x,n);
      cnt1%=mod;
      if(i!=0){
        cnt1*=mult(b,i);
        cnt1%=mod;
        cnt1*=mult(x,i);
        cnt1%=mod;
      }
      cnt2*=mult(b,n);
      cnt2*=mult(x,n);
      cnt2%=mod;
      if(i!=0){
        cnt2*=mult(a,i);
        cnt2%=mod;
        cnt2*=mult(x,i);
        cnt2%=mod;
      }
      cnt=(cnt1+cnt2)%mod;
      cnt*=comb_mod_2(n+i-1,n-1);
      cnt%=mod;
      cnt*=(n+i);
      cnt%=mod;
      ans+=cnt;
      ans%=mod;
    }
    ans*=(100*x)%mod;
    ans%=mod;
    cout<<ans<<endl;
}

