  a = mint(A)/mint(100);
  b = mint(B)/mint(100);
  c = mint(C)/mint(100);
  p = mint(A)/mint(A+B);
  q = mint(B)/mint(A+B);
  ans = 0;
  t = p^N;
  rep(i,N){
    ans += t*(q^i)*com.aCb(N+i-1,i)*(N+i);
  }
  t = q^N;
  rep(i,N){
    ans += t*(p^i)*com.aCb(N+i-1,i)*(N+i);
  }
  ans /= (mint(1)-c);
  cout << ans << endl;
}

