        ans += mc.get(n+k-1, k) * (n+k) % M *
            ((modexp(a, n, M) * modexp(b, k, M) +
              modexp(a, k, M) * modexp(b, n, M)) % M) % M *
            100 % M * modinv(modexp(100-c, n+k+1, M), M) % M;
        // cerr << ans%M << endl;
    }
    cout << ans%M << endl;
}

