struct sint {
    int v;
    sint(int v) : v(v) {}
    operator int() { return v; }
    int operator[](int i) { return (v / p10[i]) % 10; }
    int top(int i) {
        int len = keta(v);
        return operator[](len - 1 - i);
    }
    //先頭からi番目にセット
    int top(int i, int k) {
        int len = keta(v);
        return set(len - 1 - i, k);
    }
    int set(int i, int k) {
        if (i < 0)return top(abs(i) - 1, k);
        return v += p10[i] * (k - (v / p10[i]) % 10);
    }
    int inc(int i, int k = 1) {
        return v += p10[i] * k;
    }
    int inct(int i, int k = 1) {
        return v += p10[keta(v) - i - 1] * k;
    }
    int dec(int i, int k = 1) {
        return v -= p10[i] * k;
    }
    int dect(int i, int k = 1) {
        return v -= p10[keta(v) - i - 1] * k;
    }
