template<typename T, T P> const Zp<T, P> operator+(const Zp<T, P> &n, const Zp<T, P> &m) { return Zp<T, P>(n) += m; }
template<typename T, T P, typename U> const Zp<T, P> operator+(const Zp<T, P> &n, const U &m) { return Zp<T, P>(n) += m; }
