        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

void powinit(ll a, ll b){
    a %= MOD;
    b %= MOD;
    powa[0] = powb[0] = powab[0] = 1;
    rea(i, 1, MAX){
        powa[i] = powa[i-1] * a % MOD;
        powb[i] = powb[i-1] * b % MOD;
        powab[i] = powab[i-1] * (a+b) % MOD;
    }
}

