const int mod=1000000007,MAX=200001,INF=1<<30;
ll inv[MAX],fac[MAX],finv[MAX];

void make(){

    fac[0]=fac[1]=1;
    finv[0]=finv[1]=1;
    inv[1]=1;

    for(int i=2;i<MAX;i++){
        inv[i]=mod-inv[mod%i]*(mod/i)%mod;
        fac[i]=fac[i-1]*(ll)i%mod;
        finv[i]=finv[i-1]*inv[i]%mod;
    }

}

ll rui(ll a,ll b){
    if(b==1) return a%mod;
    if(b==0) return 1;
    if(b%2==0) return (rui(a,b/2)*rui(a,b/2))%mod;
    return (rui(a,b-1)*a)%mod;
}

ll comb(ll a,ll b){
    if(a<b) return 0;
    return fac[a]*(finv[b]*finv[a-b]%mod)%mod;
}

int main(){
    make();

    int N,A,B,C;cin>>N>>A>>B>>C;
    vector<ll> pow100(2*N+1),powA(2*N+1),powB(2*N+1);
    for(ll i=0;i<=2*N;i++){
