int power(int x, int k)
{
    if(k == 0) return 1;
    int t = power(x, k / 2);
    if(k % 2 == 0) return 1LL * t * t % mod;
    else return 1LL * t * t % mod * x % mod;
}

void init()
{
    gt[0] = 1;
    for(int i = 1; i < maxn; ++i)
        gt[i] = gt[i - 1] * 1LL * i % mod;
    igt[maxn - 1] = power(gt[maxn - 1], mod - 2);
    for(int i = maxn - 2; i >= 0; --i)
        igt[i] = igt[i + 1] * 1LL * (i + 1) % mod;
    prob_a = a * 1LL * power(a + b, mod - 2) % mod;
    prob_b = b * 1LL * power(a + b, mod - 2) % mod;
    temp = 100 * 1LL * power(100 - c, mod - 2) % mod;
}

inline int C(int k, int n)
{
    return gt[n] * 1LL * igt[k] % mod * igt[n - k] % mod;
}

void solve()
{
    int ans = 0;
    for(int i = n; i < 2 * n; ++i)
    {
        int f;
        f = C(n - 1, i - 1) * 1LL * (power(prob_a, n) * 1LL * power(prob_b, i - n) % mod +
                                     power(prob_b, n) * 1LL * power(prob_a, i - n) % mod) % mod;
        ans = (ans + f * 1LL * i) % mod;
    }
    ans = ans * 1LL * temp % mod;
    cout << ans << '\n';
}

