	for(int cnt_a = 0; cnt_a < n; cnt_a++)
	{
		int av = n - 1 + cnt_a;
		Modint<mod> add = C(av, cnt_a);
		add *= pw(A2, cnt_a);
		add *= pw(B2, n);
		add *= (cnt_a + n);
		add *= per_t;
		answer += add;
	}

	for(int cnt_b = 0; cnt_b < n; cnt_b++)
	{
		int av = n - 1 + cnt_b;
		Modint<mod> add = C(av, cnt_b);
		add *= pw(B2, cnt_b);
		add *= pw(A2, n);
		add *= (cnt_b + n);
		add *= per_t;
		answer += add;
	}

	cout << answer << endl;
}

