ll fact[2 * MAX_N + 1], finv[2 * MAX_N + 1], inv[2 * MAX_N + 1];

ll solve() {
    fact[0] = fact[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i <= 2 * MAX_N; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = (finv[i - 1] * inv[i]) % MOD;
    }

    pa[0] = 1;
    pb[0] = 1;
    ph[0] = 1;
    for (int i = 1; i <= 2 * N; i++) {
        pa[i] = (pa[i - 1] * A) % MOD;
        pb[i] = (pb[i - 1] * B) % MOD;
        ph[i] = (ph[i - 1] * inv[100 - C]) % MOD;
