  }

  swap(A, B);
  //A-win
  for(ll M = 0; M < N; M++){
    ans += comb(N+M-1, N-1) * pow_mod(A * inverse(A + B) % MOD, N) % MOD * pow_mod(B * inverse(A + B) % MOD, M) % MOD * (p * (N+M) % MOD) % MOD;
