long mod_pow(long x, int k) {
    long ret = 1;
    while (k > 0) {
        if (k & 1) {
            ret = (ret * x) % BASE;
        }
        k >>= 1;
        x = (x * x) % BASE;
    }
    return ret;
}

inline long mod_inv(long x) {
    return mod_pow(x, BASE - 2);
