template <typename T, typename U>
T power(T x, U y)
{
    T ret(1);
    while (y > 0)
    {
        if ((y & 1) > 0)
        {
            ret *= x;
        }
        x *= x;
        y >>= 1;
    }
    return ret;
}

int main()
{
    long long N;
    Mod<MOD> A, B, C;
    cin >> N >> A >> B >> C;

    Mod<MOD> ans = 0;
    Mod<MOD> a = power(A / (A + B), N);
    Mod<MOD> b = power(B / (A + B), N);

    Mod<MOD> current_a = 1;
    Mod<MOD> current_b = 1;

    Mod<MOD> binomial = 1;
    for (long long i = 0; i < N; i++)
    {
        ans += binomial * (N + i) * a * current_b;
        ans += binomial * (N + i) * b * current_a;
        current_a *= A / (A + B);
        current_b *= B / (A + B);
        binomial *= Mod<MOD>(N + i) / (i + 1);
    }
    if (C != 0)
    {
        ans *= Mod<MOD>(100) / (100 - C);
    }
    cout << ans << endl;
}

