#define MOD   ((ll)(1e9)+7LL)

void make_perms(ll perms[200005])
{
    perms[0] = 1LL;
    srep (i, 1, 200005) {
        perms[i] = perms[i-1] * i;
        perms[i] %= MOD;
    }
}

ll solve(ll takahashi_cnt, ll aoki_cnt, ll takahashi_p, ll aoki_p, ll n,
         const ll perms[200005])
{
    ll lose_cnt, win_p, lose_p;

    if (takahashi_cnt == n) {
        assert(aoki_cnt < n);
        lose_cnt = aoki_cnt;
        win_p = takahashi_p;
        lose_p = aoki_p;
    }
    else if (aoki_cnt == n) {
        assert(takahashi_cnt < n);
        lose_cnt = takahashi_cnt;
        win_p = aoki_p;
        lose_p = takahashi_p;
    }
    else {
        assert(false);
    }

    ll ret = takahashi_cnt + aoki_cnt;

    ret *= mod_pow(win_p, n, MOD);
    ret %= MOD;
    ret *= mod_pow(lose_p, lose_cnt, MOD);
    ret %= MOD;

    // (n-1+lose_cnt)_C_lose_cnt
    ll comb = 1LL;
    comb *= perms[n-1+lose_cnt];
    comb %= MOD;
    comb *= mod_inv(perms[n-1], MOD);
    comb %= MOD;
    comb *= mod_inv(perms[lose_cnt], MOD);
    comb %= MOD;

    ret *= comb;
    ret %= MOD;

    return ret;
}

