    rep (i, n) {
        ans += solve(n, i, takahashi_p, aoki_p, n, perms);
        ans %= MOD;
    }
    rep (i, n) {
        ans += solve(i, n, takahashi_p, aoki_p, n, perms);
        ans %= MOD;
    }

    ans *= 100LL;
    ans %= MOD;
    ans *= mod_inv(100 - c, MOD);
    ans %= MOD;

    cout << ans << endl;

    return 0;
}

