LL bigmod(LL a, LL b) {
	if (b == 0) return 1;
	LL x = bigmod(a, b / 2);
	x = (x * x) % MOD;
	if (b & 1) x = (x * a) % MOD;
	return x;
}

LL r[300005];

void solve(int ks) {
	r[1] = 1;
	for (int i = 2; i < 300000; ++i) {
		r[i] = (MOD - (MOD / i) * r[MOD%i] % MOD) % MOD;
	}

	int n, a, b, c;
	scanf("%d %d %d %d", &n, &a, &b, &c);
	int p, q, R;
	p = (a * bigmod((100 - c), MOD - 2)) % MOD;
	q = (b * bigmod((100 - c), MOD - 2)) % MOD;
	R = (100 * bigmod(100 - c, MOD - 2)) % MOD;
	LL ans = 0, cur = 0;
	double ansd = 0, curd = 0;
	for (int i = 0; i < n; i++) {
		if (i == 0) {
			cur = bigmod(p, n) * n;
			cur %= MOD;
		}
		else {
			cur = cur * q; cur %= MOD;
			cur = cur * (n + i - 1); cur %= MOD;
			cur = cur * (n + i); cur %= MOD;
			cur = cur * (r[i]); cur %= MOD;
			cur = cur * (r[n + i - 1]); cur %= MOD;			
		}
		ans += cur;
		ans %= MOD;
	}
	for (int i = 0; i < n; i++) {
		if (i == 0) {
			cur = bigmod(q, n) * n;
			cur %= MOD;
		}
		else {
			cur = cur * p; cur %= MOD;
			cur = cur * (n + i - 1); cur %= MOD;
			cur = cur * (n + i); cur %= MOD;
			cur = cur * (r[i]); cur %= MOD;
			cur = cur * (r[n + i - 1]); cur %= MOD;
		}
		ans += cur;
		ans %= MOD;
	}
	ans *= R;
	ans %= MOD;
	printf("%lld\n", ans);
}

