  int res=nCk(M-1,N-1);
  int tmp=pw(A,M-N)*pw(B,N)%MOD+pw(B,M-N)*pw(A,N)%MOD;
  tmp*=M;tmp%=MOD;
  res*=tmp;res%=MOD;
  tmp=pw(100,M-1);
  tmp*=(100-C);tmp%=MOD;
  res*=pw(tmp,MOD-2);res%=MOD;
  return res;
}

