ll mpow(ll a, ll b){
	if(b==0) return 1;
	ll t1 = mpow(a,b/2);
	t1 *= t1;
	t1 %= MOD;
	if(b%2) t1 *= a;
	t1 %= MOD;
	return t1;
}

void solve(){
	ll n,ga,gb,c;
	cin >> n >> ga >> gb >> c;
	ll ans=0;
	ll glfact = mpow(ga+gb,MOD-2);
	ll a[n+1],b[n+1],fact[n+1];
	a[0]=1;b[0]=1,fact[0]=mpow(glfact,n);
	forsn(i,1,n+1){
		a[i]=(a[i-1]*ga)%MOD;
		b[i]=(b[i-1]*gb)%MOD;
		fact[i]=(fact[i-1]*glfact)%MOD;
	}
	ll ncx[n];
	ncx[0]=1;
	forsn(i,1,n){
		ncx[i]=((ncx[i-1]*(n-1+i))%MOD)*mpow(i,MOD-2);
		ncx[i]%=MOD;
	}
	// forn(i,n+1){
