	// forn(i,n){
	// 	cout << ncx[i] << " ";
	// }
	// cout << ln;
	forn(i,n){
		ans += ((((n+i)*ncx[i] % MOD)*(a[n]*b[i] % MOD) % MOD) * fact[i])%MOD;
		ans %= MOD;
	}
	// cout << ans << ln;
	// (n+i)
	forn(i,n){
		ans += ((((n+i)*ncx[i] % MOD)*(b[n]*a[i] % MOD) % MOD) * fact[i])%MOD;
		ans %= MOD;
	}
	// cout << ans << ln;
	if(c!=0){
		ans *= 100;
		ans %= MOD;
		ans *= mpow(ga+gb,MOD-2);
		ans %= MOD;
	} 

	cout << ans << ln;
}


