int main() {
    int N, A, B, C;
    cin >> N >> A >> B >> C;
    ModInt ret  = 0;
    ModInt aiko = ModInt(C) / (100 - C);
    cerr << *aiko << endl;
    for (int i : range(N)) {
        ModInt p = pow(ModInt(A), N) * pow(ModInt(B), i)
                   * factorial::combination(N + i - 1, i)
                   * inv(pow(ModInt(100 - C), N + i));
        ret = ret + (ModInt(N + i) + aiko * (N + i)) * p;
    }
    cerr << *ret << endl;
    for (int i : range(N)) {
        ModInt p = pow(ModInt(B), N) * pow(ModInt(A), i)
                   * factorial::combination(N + i - 1, i)
                   * inv(pow(ModInt(100 - C), N + i));
