#define rep(i,n) for(int i=0;i<n;i++)
#define Rep(i,n) for(int i=1;i<n+1;i++)


array<ll,2> inv(ll a,ll m){
    array<ll,2> val;
    a=a%m;
    if(a==1){
        val[0]=1;
        val[1]=0;
    }else{
        array<ll,2> hoge;
        ll k=m/a,mm=m%a;
        hoge=inv(mm,a);
        val[1]=hoge[0]-k*a;
        val[0]=hoge[1]-k*hoge[0]+k*m;
    }
    if(val[0]>m-1){
        ll n=val[0]/m;
        val[0]=val[0]%m;
        val[1]=val[1]+n*a;
    }
    return val;
}

int main(){
    int N,A,B,C;
    cin>>N>>A>>B>>C;
    ll frac[200000],pa[100001],pb[100001],fracinv[100001];
    frac[0]=pa[0]=pb[0]=fracinv[0]=1;
    ll invab=inv(A+B,mod)[0];
    ll Atot=(A*invab)%mod,Btot=(B*invab)%mod;
    Rep(i,N){
        pa[i]=(pa[i-1]*Atot)%mod;
        pb[i]=(pb[i-1]*Btot)%mod;
    }
    Rep(i,2*N-1){
        frac[i]=(frac[i-1]*i)%mod;
        if(i<=N){
            fracinv[i]=inv(frac[i],mod)[0];
        }
    }
    ll ans=0,t;
    rep(x,N){
        t=(pa[N]*pb[x]+pb[N]*pa[x])%mod;
        t=(t*frac[N+x])%mod;
        t=(t*fracinv[N])%mod;
        t=(t*fracinv[x])%mod;
        ans=(ans+t)%mod;
    }
    ans=(ans*N)%mod;
    ans=((ans*100%mod)*invab)%mod;
    cout<<ans<<endl;
    return 0;
}

