map<P, ll> memo;

ll nCk(ll n, ll k, ll mod) {
  if (k == 0) return 1;
  if (memo[P(n, k)]) return memo[P(n, k)];
  return memo[P(n, k)] = nCk(n-1, k-1, mod) * n % mod * invmod(k, mod) % mod;
}

