const unsigned M = 1000000007;

pair<unsigned, unsigned> updm(unsigned m, unsigned mm) {
	if (mm == 1) return make_pair(0u, 1u);
	pair<unsigned, unsigned> buf = updm(mm, m % mm);
	pair<unsigned, unsigned> ans;
	ans.first = buf.second;
	ans.second = ((ULL)(M - m / mm) * buf.second + buf.first) % M;
	return ans;
}

unsigned updm(unsigned d) {
	d %= M;
	return updm(M, d).second;
}

unsigned mulm(unsigned a, unsigned b) {
	return ((ULL)a * b) % M;
}
unsigned divm(unsigned p, unsigned d) {
	return mulm(updm(d), p);
}

unsigned powa[100001], powb[100001], powc[100001];
