unsigned solve2(unsigned t, unsigned n) {
	unsigned pc =
		divm(fact[n + t - 1],
			mulm(fact[t], fact[n - 1]));

	unsigned ap = mulm(powa[n], powb[t]);
	unsigned bp = mulm(powb[n], powa[t]);

	unsigned ppc = mulm(pp, n + t);
	unsigned res = mulm(ppc, mulm((ap + bp) % M, pc));

	return res;
}

