ll extgcd(ll a, ll b, ll &x, ll &y)
{ //extended Euclidean algorithm, used for modular multiplicative inverse
    ll d = a;
    if (b != 0)
    {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    }
    else
    {
        x = 1;
        y = 0;
    }
    return d; //return gcd(a,b)
}

ll mod_inv(ll a, ll m = MOD)
{ //return inv(a) mod m, ax+my=gcd(a,m)=1, m is prime int, ax-1=mq equiv. ax-mq=1
    ll x, y;
    extgcd(a, m, x, y);
    return (m + x % m) % m; //From (possibly) negative x to positive x
}

vector<ll> powa,powb;
void calc_power(int n, ll a, ll b, ll m = MOD)
{ //Calculate power of p_a,p_b up to n
    powa.resize(n + 1);
    powb.resize(n + 1);
    powa[0] = powb[0] = 1;
    ll invhund = mod_inv(100);
    REP(i, n)
    {
        powa[i + 1] = powa[i] * a % m * invhund % m;
        powb[i + 1] = powb[i] * b % m * invhund % m;
    }
}

vector<ll> expcpow;
void calc_expcpower(int n, ll expc, ll m = MOD)
{ //Calculate power of p_a,p_b up to n
    expcpow.resize(n + 1);
    expcpow[0] = 1;
    REP(i, n)
    {
        expcpow[i + 1] = expcpow[i] * expc % m ;
    }
}

vector<ll> fact, invfact;
void calc_fact(int n, ll m = MOD)
{ //Calculate factorial up to n
    fact.resize(n + 1);
    invfact.resize(n + 1);
    fact[0] = invfact[0] = 1;
    REP(i, n)
    {
        fact[i + 1] = fact[i] * (i + 1) % m;
        invfact[i + 1] = invfact[i] * mod_inv(i + 1) % m;
    }
}
ll perm(int n, int k, ll m = MOD)
{
    if (n < 0 || k < 0 || k > n)
        return 0;
    return fact[n] * invfact[n - k] % m;
}
ll comb(int n, int k, ll m = MOD)
{
    if (n < 0 || k < 0 || k > n)
        return 0;
    return (fact[n] * invfact[n - k] % m) * invfact[k] % m;
}

