    Combination nCk(2 * n);
    for (int i = 0; i < n; ++i) {
        ret += mint(nCk(n + i - 1, i)) * a.pow(n) * b.pow(i) * (n + i) * mint(mint(1) - c).inv();
        ret += mint(nCk(n + i - 1, i)) * a.pow(i) * b.pow(n) * (n + i) * mint(mint(1) - c).inv();
    }
    cout << ret << "\n";
    return 0;
}

