long long getprob(int A, int B, int N) {
    long long invA = A * InverseEuler(A + B, MMOD) % MMOD;
    long long invB = B * InverseEuler(A + B, MMOD) % MMOD;

	long long cA = 1;
	long long cB = 1;
	for (int i=0; i < N;i++) {
      cA = (cA * invA) % MMOD;
	}
	// cout<<cA<<endl;
