void mod_add(lint &a, lint b){
    a = (a+b) % MOD;
}

lint mod_pow(lint n, lint x){
    lint res = 1;
    while(x){
        if(x&1) res = res * n % MOD;
        x >>= 1, n = n * n % MOD;
    }
    return res;
}

lint comb(int n, int r){
    return fact[n] * fact_inv[r] % MOD * fact_inv[n-r] % MOD;
}

int main(){
