        bp[i] = bp[i-1] * B % MOD;
        inv_ab[i] = mod_pow(A+B, MOD-i-1);
    }
    fact_inv[2*N] = mod_pow(fact[2*N], MOD-2);
    for(int i=2*N-1;0<=i;i--) fact_inv[i] = fact_inv[i+1] * (i+1) % MOD;
