// モジュール
// 剰余演算。中身はlong longで固定（intによるオーバーフロー防止）
struct modint {

    static ll p;
    ll n;

    static inline ll normalize(ll x, ll p = modint::p) { return (x % p + p) % p; }
    static        ll pow(ll a, ll n, ll p = modint::p) {
        n = modint::normalize(n, p - 1);
        if (n == 0) {
            return 1LL;
        } else if (n == 1) {
            return normalize(a, p);
        } else {
            ll temp = pow(a, n/2, p);
            temp = temp * temp % p;
            return n % 2 ? temp * normalize(a, p) % p : temp;
        }
    }

    modint() : n(0) {}
    modint(ll _n) { this->assign(_n); }
    modint(const modint &_m) : n(_m.n) {}

    void assign(ll _n) { this->n = modint::normalize(_n); }
    void assign(modint &x) { this->n = x.n; }

    modint pow(const ll m) const { return modint(modint::pow(this->n, m)); }

    // 演算子オーバーロード
    operator ll() const { return this->n; }
    bool operator== (const modint &x) const { return x.n == this->n; }
    modint operator+ () const { return modint(this->n); }
    modint operator- () const { return modint(modint::p - this->n); }
    modint operator+ (const modint &x) { return modint(this->n + x.n); }
    modint operator- (const modint &x) { return modint(this->n - x.n); }
    modint operator* (const modint &x) { return modint(this->n * x.n); }
    modint operator/ (const modint &x) { return modint(this->n * modint::pow(x.n, -1)); }
    modint& operator++ () { this->n = this->n == p-1 ? 0 : this->n+1; return *this; }
    modint operator++ (int) { modint cp = *this; this->n = this->n == p-1 ? 0 : this->n+1; return cp; }
    modint& operator+= (const modint &x) { this->assign(this->n + x.n); return *this; }
    modint& operator-= (const modint &x) { this->assign(this->n - x.n); return *this; }
    modint& operator*= (const modint &x) { this->assign(this->n * x.n); return *this; }
    modint& operator/= (const modint &x) { this->assign(this->n * modint::pow(x.n, -1)); return *this; }

    // 階乗・組み合わせ
    static vector<ll> fac_cache;
    static modint fac(ll n) { // n!
        if (n >= modint::fac_cache.size()) {
            ll oldsize = modint::fac_cache.size();
            modint::fac_cache.resize(n+1);
            RANGE(i, oldsize, n) {
                modint::fac_cache[i] = modint::fac_cache[i-1] * i % modint::p;
            }
        }
        return modint(modint::fac_cache[n]);
    }
    static inline bool isout(ll n, ll r) { return n < 0 || r < 0 || n < r; }
    static inline modint nPr(ll n, ll r) { return modint::isout(n, r) ? modint(0) : fac(n) / fac(n-r); }
    static inline modint nCr(ll n, ll r) { return modint::isout(n, r) ? modint(0) : fac(n) / fac(n-r) / fac(r); }
    static inline modint nHr(ll n, ll r) { return modint::nCr(n+r-1, r); }

};

