typedef long long int ll;
const int MAX = 200005;
const int MOD = 1000000007;
const int maxn = 100000+5;
ll fac[MAX], finv[MAX], inv[MAX];
ll memp1[maxn], memp2[maxn];
int n, A, B, C;

void COMinit()
{
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++)
    {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

ll COM(int n, int k)
{
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

void make()
{
	repn(i, n)
	{
		if(i)
		{
			memp1[i] = memp1[i-1] * (ll)A % MOD * inv[A+B] % MOD; 
			memp2[i] = memp2[i-1] * (ll)B % MOD * inv[A+B] % MOD; 
		}
		else if(!i) memp1[0] = memp2[0] = 1;
	}
}

ll solve()
{
	make();
	ll sum1 = 0, sum2 = 0;;
	rep(i, n)
	{
		sum1 += memp1[n] * memp2[i] % MOD * COM(n+i-1, i) % MOD * (ll)(n+i) % MOD;
		sum2 += memp2[n] * memp1[i] % MOD * COM(n+i-1, i) % MOD * (ll)(n+i) % MOD;
	}
	return (sum1 + sum2) % MOD * 100LL % MOD * inv[A+B] % MOD;
}

