struct mod_fac{
    private:
        vector<ll> f,i_f;
        int n;ll MOD;
    public:
        void init(int n,ll m){
            MOD=m;
            f.resize(n+1,0);
            i_f.resize(n+1,0);
            f[0]=1;
            rep(i,n){
                f[i+1]=f[i]*(i+1)%MOD;
            }
            i_f[n]=power(f[n],MOD-2);
            per(i,n){
                i_f[i]=(i_f[i+1]*(i+1))%MOD;
            }
        }
        ll power(ll a ,ll x){
            if (x==0) return 1;
            if (x==1) return a%MOD;
            if (x==2) return (a*a)%MOD;
            if (x%2==1) return (a*power(power(a,(x-1)/2),2))%MOD;
            return (power(power(a,x/2),2))%MOD;
        }
        ll fac(int x){
            return f[x];
        }
        ll invfac(int x){
            return i_f[x];
        }
        ll comb(int m,int k){
            if (m<0 or k<0) return 0;
            if (m<k) return 0;
            return (((f[m]*i_f[k])%MOD)*i_f[m-k])%MOD;
        }
};

ll n,a,b,c,ans=0;

void solve(){
    cin >> n >> a >> b >> c;
    mod_fac mo;mo.init(2*n+1,mod);
    ll A=a*mo.power(a+b,mod-2)%mod;
    ll B=b*mo.power(a+b,mod-2)%mod;
    ll C=100ll*mo.power(100ll-c,mod-2)%mod;
    //cout << A << " " << B << " " << C << endl;
    rep(i,n){
        //cout << mo.comb(n-1+i,i) << endl;
