        ll b_=n+i;b_*=mo.comb(n-1+i,i);b_%=mod;b_*=mo.power(B,n);b_%=mod;b_*=mo.power(A,i);b_%=mod;
        //cout << a_ << " " << b_ << endl;
        ans+=a_+b_;
        ans%=mod;
        //scout << ans << endl;
    }
