    for(ll m = n; m < 2 * n; m++){
        ll x = (comb(m - 1, n - 1, MOD) * 
               ((POW(a * mod_inv(a + b) % MOD, n, MOD) * POW(b * mod_inv(a + b) % MOD, m - n, MOD) % MOD) +
                (POW(b * mod_inv(a + b) % MOD, n, MOD) * POW(a * mod_inv(a + b) % MOD, m - n, MOD) % MOD)) % MOD) % MOD;
        ll y = ((m * 100 % MOD) * mod_inv(a + b)) % MOD;
        ans += x * y % MOD;
        ans %= MOD;
    }
