const int MAX = 5e6;
const int MOD = 1e9 + 7;
int fac[MAX], finv[MAX], inv[MAX];

void init(){
  fac[1] = 1; //fac[i]で、(i-1)!を返すものとする
  fac[2] = 1;
  for(int i = 3; i < MAX; i++){ 
    fac[i] = (fac[i-1]*(i-1))%MOD;
  }
