  LL a, b, c;
  Factorial<> fac;
  Solver(LL n) : n(n), fac(222222){};

  void solve() {
    cin >> a >> b >> c;
    Modint<> A = Modint<>(a) / Modint<>(a + b);
    Modint<> B = Modint<>(b) / Modint<>(a + b);
    Modint<> C = Modint<>(100 - c) / Modint<>(100);
    Modint<> ans(0);
    for (int i = 0; i < n; ++i) {
      ans += Modint<>(n + i) * A.mpow(n) * B.mpow(i) * fac.C(n + i - 1, i);
    }
    for (int i = 0; i < n; ++i) {
      ans += Modint<>(n + i) * A.mpow(i) * B.mpow(n) * fac.C(n + i - 1, i);
    }
    cout << ans / C << endl;
  }
};
