		}

		fact_init = true;
	}

	ll ret = fact[n];
	ret *= powmod(fact[k],MOD-2);
	ret %= MOD;
	ret *= powmod(fact[n-k],MOD-2);
	ret %= MOD;
	return ret;

	// X^(-1) = X^(p-2) (mod p) (Fermat's little theorem)
