long long modpow(long long x,long long n) {
    long long result = 1;
    while (n > 0) {
        if ((n & 1) == 1) {
            result = (result * x) % mod;
        }
        x = (x * x) % mod;
        n >>= 1;
    }

    return result;
}

#define N 200000

long long x[N+1],y[N+1];

void make_fact_table(int n){
    int i;
    x[0]=y[0]=1;
    for(i=1;i<=n;i++){
        x[i]=(long long)(x[i-1]*i)%mod;
        y[i]=modpow(x[i],mod-2);
    }
}

long long mod_nCr(int n, int r){
    return x[n]*y[n-r]%mod*y[r]%mod;
}

void run(){
    int n,a,b,c;
    cin>>n>>a>>b>>c;
    make_fact_table(2*n+1);
    int ans=0;
    int pa=a*modpow(a+b,mod-2)%mod;
