    REP(i,n,2*n-1){
        ans+=mod_nCr(i-1,n-1)*(fa[n]*fb[i-n]%mod+fb[n]*fa[i-n]%mod)%mod*i%mod*ec%mod;
        ans%=mod;
    }
    cout<<ans<<endl;
}

