//并查集
struct UnionFind {
  vi par, sz;
  int n_tree;

  explicit UnionFind(int n) : sz(n, 1), n_tree(n) { //0-indexed
    sz.resize(n);
    iota(par.begin(), par.end(), 0);
  }

  int n_cluster() const {
    return n_tree;
  }

  int size(int x) {
    return sz[root(x)];
  }

  int root(int x) {
    return x == par[x] ? x : par[x] = root(par[x]);
  }

  bool unite(int x, int y) {
    int rx = root(x), ry = root(y);
    if (rx != ry) {
      par[rx] = ry;
      --n_tree;
      sz[ry] += sz[rx];
      return true;
    }
    return false;
  }

  bool is_root(int x) const {
    return par[x] == x;
  }
};

template<typename T, typename Compare = std::less<T>>
struct SparseTable {
  size_t n{}; // 0-indexed
  vv<T> a;

  template<typename ptr_t>
  SparseTable(ptr_t beg, ptr_t end):n(end - beg) {
    a.resize((size_t) h_bit(n) + 1); // 注意：不能写成 h_bit(n)
    a[0].assign(beg, end);
    rng (i, 0, SZ(a) - 1) {
      a[i + 1].resize(n);
      rng(j, 0, n - (1u << i)) {
        a[i + 1][j] = min(a[i][j], a[i][j + (1u << i)], Compare());
      }
      rng(j, n - (1u << i), n) {
        a[i + 1][j] = a[i][j];
      }
    }
  }

  using idx_t = long;

  T query(idx_t l, idx_t r) { // l <=  r
    int i = h_bit(r - l + 1ul);
    return min(a[i][l], a[i][r + 1 - (1u << i)], Compare());
  }
};

