typedef struct real_t {
    long long P;
    long long Q;
} real;
real mul(real a, real b) {
    real out;
    out.P = (a.P * b.P) % MOD;
    out.Q = (a.Q * b.Q) % MOD;
    return out;
}
real add(real a, real b) {
    real out;
    out.P = (a.P * b.Q) % MOD + (a.Q * b.P) % MOD;
    out.Q = (a.Q * b.Q) % MOD;
    out.P %= MOD;
    return out;
}
real mul(real a, long long c) {
    real out;
    out.P = (a.P * c) % MOD;
    out.Q = a.Q;
    return out;
}

long long modinv(long long a, long long b)
{
    long long b0 = b, t, q;
    long long x0 = 0, x1 = 1;
    if (b == 1) return 1;
    while (a > 1) {
        q = a / b;
        t = b, b = a % b, a = t;
        t = x0, x0 = x1 - q * x0, x1 = t;
    }
    if (x1 < 0) x1 += b0;
    return x1;
}

