        (cnt += (Pow_Mod(A,M-N,MOD)*Pow_Mod(B,N,MOD)%MOD)) %= MOD;
        (cnt *= Pow_Mod(A+B,-M,MOD)) %= MOD;
        (cnt *= CM.num(M-1,N-1)) %= MOD;
        (cnt *= M) %= MOD;
        (cnt *= (100LL*Pow_Mod(100-C,-1,MOD)%MOD )) %= MOD;
        (ans += cnt) %= MOD;
    }
