using LL = long long;

const LL MOD = 1000000007;
LL mpow(LL a, LL x) {
	if (x == 0)return 1;
	LL half = mpow(a, x / 2);
	half *= half;
	half %= MOD;
	if (x % 2) {
		half *= a;
		half %= MOD;
	}
	return half;
}

LL fact[1234567];
LL nCr(LL n, LL r) {
	if (n == 0 && r == 0)return 1;
	if (r == 0 || r == n)return 1;
	return ((fact[n] * mpow(fact[r], MOD - 2)) % MOD * mpow(fact[n - r], MOD - 2)) % MOD;
}

LL N, A, B, C;

LL prob(LL lcnt, LL wp, LL lp, LL tp) {
	LL res = mpow(wp, N);
	res *= mpow(lp, lcnt);
	res %= MOD;
	LL tmp = nCr(N - 1 + lcnt, lcnt);
	res *= tmp;
	res %= MOD;
	LL one = mpow((MOD + 1 - tp) % MOD, N + lcnt);
	one = mpow(one, MOD - 2);
	LL two = mpow((MOD + 1 - tp) % MOD, N + lcnt + 1);
	two = mpow(two, MOD - 2);
	two *= tp;
	two %= MOD;
	two *= (N + lcnt);
	two %= MOD;
	LL right = (two + (one * (N + lcnt)) % MOD) % MOD;
	res *= right;
	//res *= 16;
	res %= MOD;
	return res;
}

