// 拡張gcd
int ext_gcd(int a, int b, int &x, int &y) {
  if (b == 0) {
    x = 1; y = 0; return a;
  }
  int q = a/b;
  int g = ext_gcd(b,a-q*b,x,y);
  int z = x-q*y;
  x = y; y = z;
  return g;
}

// 逆元 | a と m は互いに素
int inv_mod(int a, int m) {
  int x,y;
  ext_gcd(a,m,x,y);
  x %= m;
  if (x < 0) x += m;
  return x;
}

