// 解説は条件付き期待値
// （ゲームの回数の期待値）= 
// Σ(ゲーム中AかBが出る回数がM回である確率(A Bは正規化する)) * (ゲーム中AかBが出る回数がM回である時に、Cが出る回数も含めた総合回数の期待値)
// https://www.creativ.xyz/best-of-2n-1-1080/

const int MAX = 2000005;
long long fac[MAX], finv[MAX], inv[MAX];

void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAX; i++){
        fac[i] = fac[i-1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod/i) % mod;
        finv[i] = finv[i-1] * inv[i] % mod;
    }
}
long long COM(int n, int k){
    if(n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
}


int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int N;
    ll A, B, C;
    cin >> N >> A >> B >> C;

    COMinit();
    ll a = A * modpow(A+B, mod-2) % mod;
    ll b = B * modpow(A+B, mod-2) % mod;
    ll c = 100 * modpow(100-C, mod-2) % mod;

    ll ans = 0;
    repr(m, N, 2*N){
        ll add = c * m % mod;
        add *= COM(m-1, N-1) * modpow(a, N) % mod * modpow(b, m-N) % mod;
        chmod(add);
        ans += add;
        chmod(ans);
    }
    repr(m, N, 2*N){
        ll add = c * m % mod;
        add *= COM(m-1, N-1) * modpow(a, m-N) % mod * modpow(b, N) % mod;
        chmod(add);
        ans += add;
        chmod(ans);
    }
    cout << ans << endl;

    return 0;
}

