void createFactInvMod(int n){
    fact.resize((unsigned int)n+1); fact_inv.resize((unsigned int)n+1);
    fact[0] = 1;
    for(int i=1;i<=n;i++) fact[i] = fact[i-1] * i % MOD;
    fact_inv[n] = mod_pow(fact[n], MOD-2);
    for(int i=n-1;0<=i;i--) fact_inv[i] = fact_inv[i+1] * (i+1) % MOD;
}

void createInvMod(int n){
    inv.resize((unsigned int)n+1);
    createFactInvMod(n);
    inv[0] = 0;
    for(int i=1;i<=n;i++) inv[i] = fact[i-1] * fact_inv[i] % MOD;
}

lint comb(lint n, lint r){
    return fact[n] * fact_inv[r] % MOD * fact_inv[n-r] % MOD;
}

