void Pre(){
	fact[0] = 1;
	For(i,MAXN-1) fact[i] = fact[i-1]*i % MOD;
	invfact[MAXN-1] = Inv(fact[MAXN-1]);
	fOR0(i,MAXN-1) invfact[i] = invfact[i+1]*(i+1) % MOD;
	// O(invfact[0]);
}
il ll C( int n , int m ){
	if( n < m ) return 0;
	if( m == 0 or m == n ) return 1;
	return fact[n] * invfact[m] % MOD * invfact[n-m] % MOD;
}

ll P( ll w , ll h ){
	return Pow(aa,w) * Pow(bb,h) % MOD * C(w+h,h) % MOD;
}
ll E( ll w , ll h ){
	return (w+h)*e % MOD;
}

