	make_kai();
	vel rw(n+1, 1), rl(n+1, 1);
	rep(i, n) { rw[i + 1] = (rw[i] * w) % p; rl[i + 1] = (rl[i] * l) % p; }
	rep(i, n) {
		int pl = (com(n - 1 + i, i)*rw[i]) % p;
		pl *= rl[n]; pl %= p;
		ans += pl*(n+i); ans %= p;
		all += pl;
	}
	rep(i, n) {
		int pl = (com(n - 1 + i, i)*rl[i]) % p;
		pl *= rw[n]; pl %= p;
		ans += pl * (n + i); ans %= p;
		all += pl;
	}
	ans *= 100; ans %= p; ans *= inv(100 - c); ans %= p;
	cout << (ans*inv(all)) % p << endl;
	return 0;
}

