template<typename T=long long, const T P=(T)MOD>
class COM {
  private:
  int m;
  vector<Zp<T, P>> fac, finv, inv;
  void init(const int &n) {
    if(m >= n) return ;
    fac.resize(n+1);
    inv.resize(n+1);
    finv.resize(n+1);
    for (int i = m+1; i <= n; i++){
      fac[i] = fac[i - 1] * i;
      inv[i] = P - inv[P % i] * (P / i);
      finv[i] = finv[i - 1] * inv[i];
    }
    m = n;
  }
  public:
  COM() : m(1), fac(2, 1), finv(2, 1), inv(2, 1) {}
  COM(const int &n) : m(1), fac(2, 1), finv(2, 1), inv(2, 1) { init(n); }
  Zp<T, P> operator()(const int &n, const int &k) {
    if (n < k) return Zp<T, P>(0);
    if (n < 0 || k < 0) return Zp<T, P>(0);
    init(n);
    return fac[n] * (finv[k] * finv[n - k]);
  }
};

using Mod = Zp<>;

int N;
Mod A, B, C;
Mod a[limit], b[limit], c;
COM<> com;

signed main() {
  cin.tie(0);cout.tie(0);
  ios_base::sync_with_stdio(false);

  cin >> N >> A >> B >> C;

  A /= 100-C;
  B /= 100-C;
  C /= 100;

  a[0] = b[0] = 1;
  rep(i, N) a[i+1] = a[i] * A;
  rep(i, N) b[i+1] = b[i] * B;

  Mod P = 0, Q = 1 - C;
  rep(i, N) P += com(N+i-1, i) * (a[N]*b[i] + a[i]*b[N]) * (N+i);

  // cout << P << '/' << Q << " = ";
  cout << P/Q << endl;

  return 0;
}

