inline constexpr ll invmod(ll a, ll m = mod) noexcept { ll x = 0, y = 0; extgcd(a, m, x, y); return (x + m) % m; }
struct Modint{
    ll _num;
    constexpr Modint() noexcept : _num() { _num = 0; }
    constexpr Modint(ll x) noexcept : _num() { _num = x % mod; if(_num < 0) _num += mod; }
    inline constexpr Modint operator= (int x) noexcept { _num = x % mod; if(_num<0) _num += mod; return *this; }
    inline constexpr Modint operator= (ll x) noexcept { _num = x % mod; if(_num<0) _num += mod; return *this; }
    inline constexpr Modint operator= (Modint x) noexcept { _num = x._num; return *this; }
    inline constexpr Modint operator+ (int x) noexcept { return Modint(_num + x); }
    inline constexpr Modint operator+ (ll x) noexcept { return Modint(_num + x); }
    inline constexpr Modint operator+ (Modint x) noexcept { ll a = _num + x._num; if(a >= mod) a -= mod; return Modint{a}; }
    inline constexpr Modint operator+=(int x) noexcept { _num += x; _num %= mod; if(_num < 0) _num += mod; return *this; }
    inline constexpr Modint operator+=(ll x) noexcept { _num += x; _num %= mod; if(_num < 0) _num += mod; return *this; }
    inline constexpr Modint operator+=(Modint x) noexcept { _num += x._num; if(_num >= mod) _num -= mod; return *this; }
    inline constexpr Modint operator++() noexcept { _num++; if(_num == mod) _num = 0; return *this; }
    inline constexpr Modint operator- (int x) noexcept { return Modint(_num - x); }
    inline constexpr Modint operator- (ll x) noexcept { return Modint(_num - x); }
    inline constexpr Modint operator- (Modint x) noexcept { ll a = _num - x._num; if(a < 0) a += mod; return Modint{a}; }
    inline constexpr Modint operator-=(int x) noexcept { _num -= x; _num %= mod; if(_num < 0) _num += mod; return *this; }
    inline constexpr Modint operator-=(ll x) noexcept { _num -= x; _num %= mod; if(_num < 0) _num += mod; return *this; }
    inline constexpr Modint operator-=(Modint x) noexcept { _num -= x._num; if(_num < 0) _num += mod; return *this; }
    inline constexpr Modint operator--() noexcept { _num--; if(_num == -1) _num = mod - 1; return *this; }
    inline constexpr Modint operator* (int x) noexcept { return Modint(_num * (x % mod)); }
    inline constexpr Modint operator* (ll x) noexcept { return Modint(_num * (x % mod)); }
    inline constexpr Modint operator* (Modint x) noexcept { return Modint{_num * x._num % mod}; }
    inline constexpr Modint operator*=(int x) noexcept { _num *= Modint(x); _num %= mod; return *this; }
    inline constexpr Modint operator*=(ll x) noexcept { _num *= Modint(x); _num %= mod; return *this; }
    inline constexpr Modint operator*=(Modint x) noexcept { _num *= x._num; _num %= mod; return *this; }
    inline constexpr Modint operator/ (int x) noexcept { return Modint(_num * invmod(Modint(x), mod)); }
    inline constexpr Modint operator/ (ll x) noexcept { return Modint(_num * invmod(Modint(x), mod)); }
    inline constexpr Modint operator/ (Modint x) noexcept { return Modint{_num * invmod(x._num, mod) % mod}; }
    inline constexpr Modint operator/=(int x) noexcept { _num *= invmod(Modint(x), mod); _num %= mod; return *this; }
    inline constexpr Modint operator/=(ll x) noexcept { _num *= invmod(Modint(x), mod); _num %= mod; return *this; }
    inline constexpr Modint operator/=(Modint x) noexcept { _num *= invmod(x._num, mod); _num %= mod; return *this; }
    inline constexpr Modint pow(ll x) noexcept { ll i = 1; Modint ans = 1, cnt = *this; while(i <= x){ if(x & i){ ans *= cnt; x ^= i; } cnt *= cnt; i *= 2; } return ans; }
    inline constexpr operator ll() const noexcept { return _num; }
};
vector<Modint> fac(1, 1), inv(1, 1);
inline void reserve(ll a){
    if(fac.size() >= a) return;
    if(a < fac.size() * 2) a = fac.size() * 2;
    if(a >= mod) a = mod;
    while(fac.size() < a) fac.push_back(fac.back() * ll(fac.size()));
    inv.resize(fac.size());
    inv.back() = Modint(1) / fac.back();
    for(ll i = inv.size() - 1; !inv[i - 1]; i--) inv[i - 1] = inv[i] * i;
}
inline Modint fact(ll n){ if(n < 0) return 0; reserve(n + 1); return fac[n]; }
inline Modint perm(ll n, ll r){ if(r < 0 || n < r) return 0; reserve(n + 1); return fac[n] * inv[n - r]; }
inline Modint comb(ll n, ll r){ if(r < 0 || n < r) return 0; reserve(n + 1); return fac[n] * inv[r] * inv[n - r]; }
