vector<modint> fact, fact_inv;

void COMinit(const ll &MAX) {
    fact.resize(MAX + 1);
    fact_inv.resize(MAX + 1);
    fact[0] = 1;
    rep(i, MAX) fact[i + 1] = fact[i] * (i + 1);
    fact_inv[MAX] = fact[MAX].inverse();
    for(int i = MAX; i; i--)
        fact_inv[i - 1] = fact_inv[i] * i;
}

modint COM(const ll &n, const ll &k) {
    if(n < k || k < 0) return 0;
    return fact[n] * fact_inv[k] * fact_inv[n - k];
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);

    int n;
    cin >> n;
    COMinit(2 * n);
    modint a, b, c;
    cin >> a >> b >> c;
    modint ab = a + b;
    a /= ab;
    b /= ab;
    modint an = a.pow(n), bn = b.pow(n);
    modint ans(0), x(1), y(1);
    FOR(i, n, 2 * n) {
        ans += COM(i - 1, n - 1) * (an * x + bn * y) * i;
        x *= b;
        y *= a;
    }
    cout << ans * 100 / (modint(100) - c) << endl;

    return 0;
}

