void Cinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < 100010; i++){
        fac[i] = (fac[i-1]*i)%MOD;
        inv[i] = (MOD - inv[MOD%i]*(MOD/i))%MOD;
        finv[i] = (finv[i-1]*inv[i])%MOD;
    }
}

ll nCk(ll n,ll k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n]*(finv[k]*finv[n-k]%MOD)%MOD;
}

ll mpow(ll a, ll b){
    if(b == 0) return 1;
    ll z = mpow(a,b/2);
    z = z*z%MOD;
    if(b % 2 == 1) z = z*a%MOD;
    return z;
}

int main(){
    Cinit();
    ll A,B,C,N;
    cin >> N >> A >> B >> C;
    ll ka = A*inv[A+B]%MOD;
    ll kb = B*inv[A+B]%MOD;
    ll r = 0;
    for(int i = 0; i <= N; i++){
        ll sa = nCk(N-1+i,N-1)*ka%MOD*mpow(ka,N-1)%MOD*mpow(kb,i);
        ll sb = nCk(N-1+i,N-1)*kb%MOD*mpow(kb,N-1)%MOD*mpow(ka,i);
        r = (r + (sa + sb)%MOD*(N+i))%MOD;
    }
    cout << r*100%MOD*inv[A+B]%MOD << endl;
}

