using namespace std;

long long exp(long long b, long long i){
    if(i == 0) return 1;
    long long ret = 1;
    if(i % 2 == 1) ret *= b;
    long long e = exp(b, i / 2);
    ret *= e;
    ret %= MOD;
    ret *= e;
    ret %= MOD;
    return ret;
}

long long fact(long long n){
    static long long memo[3000001] = {0};
    if(memo[0] == 0){
        memo[0] = 1;
        for(int i = 1; i <= 300000; i++) memo[i] = (i * memo[i - 1]) % MOD;
    }
    return memo[n];
}

long long inv(long long n){
    return exp(n, MOD - 2);
}

long long comb(long long n, long long k){
    long long ret = fact(n);
    ret *= inv(fact(n - k));
    ret %= MOD;
    ret *= inv(fact(k));
    ret %= MOD;
    return ret;
}

long long gcd(long long x, long long y){
    if(y == 0) return x;
    return gcd(y, x % y);
}

