        sub %= MOD;
        sub *= comb(N + i - 1, N - 1);
        sub %= MOD;
        // cout << sub << endl;
        ans += sub;
        ans %= MOD;
    }
    for(long long i = 0; i < N; i++){
        long long sub = N + i;
        sub *= exp(b, N);
        sub %= MOD;
        sub *= exp(a, i);
        sub %= MOD;
        sub *= comb(N + i - 1, N - 1);
        sub %= MOD;
        // cout << sub << endl;
        ans += sub;
