long modu(long x){
    return (x%MOD+2*MOD)%MOD;
}

long modinv(long a) {
    a=modu(a);
    long b = MOD, u = 1, v = 0;
    while (b) {
        long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= MOD;
    if (u < 0) u += MOD;
    return u;
}

void modif(long &x){
    x=modu(x);
}

