    t %= d;
    ll ta = (modpow(B, k, d) * modpow(A, N, d)) % d;
    ll tb = (modpow(A, k, d) * modpow(B, N, d)) % d;
    t *= modinv(modpow(100 - C, N + k + 1, d), d);
    t %= d;
    ans += t * ((ta + tb) % d);
    ans %= d;
  }
