int tle_solution() {
  i64 N, A, B, C;
  std::cin >> N >> A >> B >> C;

  tools::fact_mod_cache<P> cache(2 * N);

  std::vector<tools::int_mod<P>> A_pow(2 * N + 1);
  A_pow[0] = tools::int_mod<P>(1);
  for (i64 i = 1; i <= 2 * N; ++i) {
    A_pow[i] = A_pow[i - 1] * tools::int_mod<P>(A);
  }

  std::vector<tools::int_mod<P>> B_pow(2 * N + 1);
  B_pow[0] = tools::int_mod<P>(1);
  for (i64 i = 1; i <= 2 * N; ++i) {
    B_pow[i] = B_pow[i - 1] * tools::int_mod<P>(B);
  }

  std::vector<tools::int_mod<P>> AB_pow(2 * N + 1);
  AB_pow[0] = tools::int_mod<P>(1);
  for (i64 i = 1; i <= 2 * N; ++i) {
    AB_pow[i] = AB_pow[i - 1] * tools::int_mod<P>(A + B);
  }

  tools::int_mod<P> numerator = tools::int_mod<P>(N) * AB_pow[2 * N - 2];
  for (i64 i = 0; i <= N - 2; ++i) {
    tools::int_mod<P> factor(0);
    for (i64 j = 0; j <= i; ++j) {
      factor += cache.fact(2 * N - 2 - i)
        * cache.inv_fact(N - 1 - j)
        * cache.inv_fact(N - 1 - i + j)
        * A_pow[N - 1 - j]
        * B_pow[N - 1 - i + j];
    }
    numerator += AB_pow[i] * factor;
  }
  numerator *= tools::int_mod<P>(100);

  tools::int_mod<P> denominator = AB_pow[2 * N - 1];

  std::cout << static_cast<u32>(numerator / denominator) << std::endl;
  return 0;
}

