    tmp = tmp * modcomb(M - 1, N - 1, mod) % mod;
    tmp = tmp * M % mod;
    tmp = tmp * 100 % mod;
    p = (p + tmp) % mod;
  };
  ll q = modpow(a + b, N + 1, mod);
  ll r = p * modinv(q, mod);
  cout << r % mod << endl;
};

