		tmp = (tmp * 100 * i)%inf;
		tmp = (tmp * hv[2*n-1-i])%inf;
		ans = (ans +tmp)%inf;
	}
	ans = (ans * hnv[2*n-1])%inf;
	ans = (ans * w)%inf;
	cout<<ans<<endl;
	return 0;
}

