    int n;
    modint a, b, c;
    cin >> n >> a >> b >> c;
    modint X = modint(100) / (modint(100) - c);
    a /= 100, b /= 100;
    Combination<modint> comb(n * 2);
    modint ans = 0;
    for(int m = n; m < n * 2; ++m){
        modint val = a.pow(n) * b.pow(m - n) + a.pow(m - n) * b.pow(n);
        val *= comb.get_combination(m - 1, n - 1);
        val /= (a + b).pow(m);
        val *= X * m;
        ans += val;
    }
    cout << ans << endl;
}

