	for (int i = 0; i < num; i++) {
		fact[i + 1] = fact[i] * ((ll)i + 1LL) % mod;
	}
	fact_inv[num] = power(fact[num], mod - 2);
	for (int i = num - 1; i >= 0; i--) {
		fact_inv[i] = fact_inv[i + 1] * (i + 1) % mod;
	}
}

// 逆元を求める
long long mod_inv(long long value) {

	long long b = mod, u = 1, v = 0;

	while (b) {
		long long t = value / b;
		value -= t * b;
		swap(value, b);
		u -= t * v;
		swap(u, v);
	}
	u %= mod;
	if (u < 0) u += mod;

	return u;
}

ll mod_pow(ll num, long long n) {
	long long a = num;
	long long res = 1;
	while (n > 0) {
		if (n & 1) res = res * a % mod;
		a = a * a % mod;
		n >>= 1;
	}
	return res;
}

