}
void mul(int& a, int b){
	a = (a*b) % MOD;
}
int mod_pow(int x, int n) {
	int res = 1;
	while (n > 0) {
		if (n & 1) res = res * x % MOD;
		x = x * x % MOD;
		n >>= 1;
	}
	return res;
}
int mod_inv(int x)
{
	return mod_pow(x, MOD - 2);
}
