template <ll M>
struct ModInt {
    ll num;
    ModInt(): num(0){ }
    operator ll (){ return num; }
    ModInt(ll num): num(num){ }
    template <class T> ModInt operator + (T n){ return (num + n) % M; }
    template <class T> ModInt operator - (T n){ return (num - n + M) % M; }
    template <class T> ModInt operator * (T n){ return (num * n) % M; }
    template <class T> ModInt operator / (T n){ return num * modInv(ModInt(n)) % M; }
    template <class T> ModInt operator >> (T n){ return num >> n; }
    template <class T> ModInt operator << (T n){ return (num << n) % M; }
    template <class T> ModInt operator | (T n){ return num | n; }
    template <class T> ModInt operator & (T n){ return num & n; }
    template <class T> bool operator < (T n){ return num < n; }
    template <class T> bool operator > (T n){ return num > n; }
    template <class T> bool operator <= (T n){ return num <= n; }
    template <class T> bool operator >= (T n){ return num >= n; }
    template <class T> bool operator == (T n){ return num == n; }
    template <class T> bool operator != (T n){ return num != n; }
    ModInt operator ++ (int){ ll ret = num; num = (num + 1) % M; return ret; }
    ModInt operator -- (int){ ll ret = num; num = (num - 1 + M) % M; return ret; }
    ModInt operator ++ (){ return num = (num + 1) % M; }
    ModInt operator -- (){ return num = (num - 1 + M) % M; }
    template <class T> ModInt operator += (T n){ return num = (num + n) % M; }
    template <class T> ModInt operator -= (T n){ return num = (num - n) % M; }
    template <class T> ModInt operator *= (T n){ return num = (num * n) % M; }
    template <class T> ModInt operator /= (T n){ return num = num * modInv(n) % M; }
    template <class T> ModInt operator >>= (T n){ return num = num >> n; }
    template <class T> ModInt operator <<= (T n){ return num = (num << n) % M; }
    friend ModInt modPow(ModInt base, ModInt ex) {
        ModInt ret = 1;
        while(ex.num){
            if(ex.num & 1){ ret = ret * base; }
            ex >>= 1;
            base = base * base;
        }
        return ret;
    }
    static vector<ModInt> mFacts, mInvFacts;
    friend ModInt modFact(ModInt n){ return mFacts[n.num]; }
    friend ModInt modInvFact(ModInt n){ return mInvFacts[n.num]; }
    friend ModInt modInv(ModInt n){ return modPow(n, M - 2); }
    friend ModInt modC(ModInt n, ModInt k){ return modFact(n) * modInvFact(k) * modInvFact(n - k); }
    static void init(int n){
        mFacts.resize(n + 1);
        mInvFacts.resize(n + 1);
        mFacts[0] = 1;
        for(int i = 1; i <= n; i++){
            mFacts[i] = mFacts[i - 1] * i;
        }
        mInvFacts[n] = modInv(mFacts[n]);
        for(int i = n - 1; i >= 0; i--){
            mInvFacts[i] = mInvFacts[i + 1] * (i + 1);
        }
    }
    friend istream& operator >> (istream& in, ModInt& e){
        return in >> e.num;
    }
};
