void calcComb() {
	const int n = 300000;
	fact[0] = 1;
	for (int i = 0; i < n; i++) {
		fact[i + 1] = fact[i] * (i + 1) % mod;
	}
	fact_inv[n] = power(fact[n], mod - 2);
	for (int i = n - 1; i >= 0; i--) {
		fact_inv[i] = fact_inv[i + 1] * (i + 1) % mod;
	}
}

