	long long b = mod, u = 1, v = 0;

	while (b) {
		long long t = value / b;
		value -= t * b;
		swap(value, b);
		u -= t * v;
		swap(u, v);
	}
	u %= mod;
	if (u < 0) u += mod;

	return u;
}

ll mod_pow(ll num, long long n) {
	long long a = num;
	long long res = 1;
	while (n > 0) {
		if (n & 1) res = res * a % mod;
		a = a * a % mod;
		n >>= 1;
	}
	return res;
}

void solve() {

	cin >> N >> A >> B >> C;

	calcComb();

	ll ans = 0;
	for (int M = N; M < 2 * N; M++) {
		ll X = comb(M - 1, N - 1) * ((mod_pow(A * mod_inv(100 - C) % mod, N) * mod_pow(B * mod_inv(100 - C) % mod, M - N) % mod + mod_pow(B * mod_inv(100 - C) % mod, N) * mod_pow(A * mod_inv(100 - C) % mod, M - N) % mod) % mod) % mod;
		ll Y = M * 100 % mod * mod_inv(100 - C) % mod;
		ans += X * Y % mod;
	}
	cout << ans % mod << endl;

	return;

}

int main() {

	cin.tie(0);
	ios::sync_with_stdio(false);

	solve();

	return 0;

}

