    return F(a.x * b.x);
}

F powi(const F &a, size_t n) {
    if (n == 0) {
        return F(1);
    } else if (n % 2 == 0) {
        F b = powi(a, n / 2);
        return b * b;
    } else {
        F b = powi(a, n / 2);
        return a * b * b;
    }
}

F operator/(const F& a, const F& b) {
