      return ((a%MOD)+(b%MOD))%MOD;
}

ll mulMod(ll a,ll b){
      return ((a%MOD)*(b%MOD))%MOD;
}

ll powMod(ll a,ll b){
      if(b==0) return 1;
      else if(b%2==0){
            ll ret=powMod(a,b/2);
            return ((ret%MOD)*(ret%MOD))%MOD;
      }
      else return ((powMod(a,b-1)%MOD)*(a%MOD))%MOD;
}
ll divMod(ll a,ll b){
      return ((a%MOD)*(powMod(b,MOD-2)%MOD))%MOD;
}

