struct modint{
    modint(lint x = 0, bool b = false): num(x % mod), bitflag(b) {}
    lint val(){ return num; }

    bool operator !=(bool x){
        return bitflag != x;
    }

    bool operator ==(bool x){
        return bitflag == x;
    }

    modint operator +(modint x){
        modint ret = *this; ret += x;
        return ret;
    }

    modint operator -(modint x){
        modint ret = *this; ret -= x;
        return ret;
    }

    modint operator *(modint x){
        modint ret = *this; ret *= x;
        return ret;
    }

    modint operator /(modint x){
        modint ret = *this; ret /= x;
        return ret;
    }

    modint& operator +=(modint x){
        num += x.num;
        if(num >= mod) num -= mod;
        return *this;
    }

    modint& operator -=(modint x){
        if(num < x.num) num += mod;
        num -= x.num;
        return *this;
    }

    modint& operator *=(modint x){
        num = num * x.num % mod;
        return *this;
    }

    modint& operator /=(modint x){
        num = num * inv(x).val() % mod;
        return *this;
    }

    bool flag(){
        return bitflag;
    }

private:
    lint num;
    bool bitflag;

    modint inv(modint x){
        lint exp = mod - 2;
        modint ret = 1;
        while(exp){
            if(exp & 1) ret *= x;
            x *= x;
            exp >>= 1;
        }
        return ret;
    }
};

ostream& operator <<(ostream& out, modint x){
    out << x.val();
    return out;
}

