struct mint {
    ll x;
    mint(ll x = 0) : x(x % MOD) {}
    mint& operator += (const mint a) {
        if ( (x += a.x) >= MOD) { x -= MOD; }
        return *this;
    }
    mint& operator -= (const mint a) {
        if ( (x += MOD - a.x) >= MOD) { x -= MOD; }
        return *this;
    }
    mint& operator *= (const mint a) {
        (x *= a.x) %= MOD;
        return *this;
    }
    mint operator + (const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator - (const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator * (const mint a) const {
        mint res(*this);
        return res *= a;
    }
};

class NumberOfCase {
    public:
        // 初期化 O(n log m) m は素数
        // n : 求めたい組み合わせの最大値, m : 剰余(素数)
        NumberOfCase(ll n, ll m) : m_Size(n), m_Mod(m) {
            m_Fact = new ll[m_Size + 1];
            m_FInv = new ll[m_Size + 1];
            m_Inv = new ll[m_Size + 1];
            // 0! ～ m_Size! までの階乗を保管する配列の作成 (mod m_Mod をとってある)
            m_Fact[0] = 1;
            for(int i = 1; i <= m_Size; ++i) { m_Fact[i] = (m_Fact[i-1] * i) % m_Mod; }
            // m_Size! の逆元 1/m_Size! を二分累乗法で求める
            // フェルマーの小定理より a^-1 = a^(p-2) mod p -> (m_Size!)^-1 = (m_Size!)^(p-2) mod p
            m_FInv[m_Size] = Pow(m_Fact[m_Size], m_Mod-2);
            // 以下 1 / (N-1)! = N / N! であることを利用
            for(int i = m_Size - 1; i >= 0; --i) { m_FInv[i] = (m_FInv[i + 1] * (i + 1)) % m_Mod; }
            // 逆元の作成（割り算のとき利用）
            m_Inv[1] = 1;
            for(int i = 2; i <= m_Size; ++i) { m_Inv[i] = m_Inv[m_Mod % i] * (m_Mod - m_Mod / i) % m_Mod; }
        }
        ~NumberOfCase() {
            delete[] m_Fact;
            delete[] m_FInv;
            delete[] m_Inv;
        }
        // x の y 乗を求める O(log MOD)
        ll Pow(ll x, ll y) {
            if (y == 0) return 1;
            ll res = Pow(x, y / 2);
            return res * res % m_Mod * (y & 1 ? x : 1) % m_Mod;
        }
        // 階乗 n! の取得 O(1)
        ll Factorial(ll n) { return m_Fact[n]; }
        // n! の逆元の取得 O(1)
        ll FInverse(ll n) { return m_FInv[n]; }
        // 逆元の取得 O(1) or O(log MOD)
        // m_Size を超える値も可能。ただし O(log M)
        ll Inverse(ll n) {
            if(n < m_Size) { return m_Inv[n]; }
            else { return Pow(n, m_Mod - 2); }
        }
        // 剰余を考慮した割り算 n / m の結果を返す
        ll Div(ll n, ll m) { return (n * m_Inv[m]) % m_Mod; }
        // 順列 nPr の取得 O(1)
        ll Permutation(ll n, ll r) { return (m_Fact[n] * m_FInv[n - r]) % m_Mod; }
        // 組み合わせ nCr の取得 O(1)
        ll Combination(ll n, ll r) {
            ll ret = (m_Fact[n] * m_FInv[n - r]) % m_Mod;
            ret = (ret * m_FInv[r]) % m_Mod;
            return ret;
        }
        // 重複組み合わせ nHr の取得 O(1)
        ll Homogen(ll n, ll r) { return Combination(r+n-1, r); }
    private:
        const ll    m_Size;     // 導出する範囲 (10^5 くらいまでにして欲しい)
        const ll    m_Mod;      // 剰余
        ll*         m_Fact;     // 階乗
        ll*         m_FInv;     // 階乗の逆元
        ll*         m_Inv;      // 逆元
};

ll N, A, B, C;
vector<mint> fact_a, fact_b, fact_ab;    // a/b/a+b の i 乗

signed main()
{
    cin >> N >> A >> B >> C;

    NumberOfCase noc(2 * MAX_N, MOD);

    mint ans = 0;
    // fact_a, fact_b の作成
    fact_a.resize(N + 1);
    fact_b.resize(N + 1);
    fact_ab.resize(N + 1);
    fact_a[0] = 1;
    fact_b[0] = 1;
    fact_ab[0] = 1;
    for(int i = 1; i <= N; ++i) {
        fact_a[i] = fact_a[i-1] * A;
        fact_b[i] = fact_b[i-1] * B;
        fact_ab[i] = fact_ab[i-1] * (A+B);
    }

    // C を考えない場合
    for(int i = 0; i < N; ++i) {
        ll M = N + i;
        // ゲームを M 回行ったときに決着がついたと仮定
        // 高橋君が勝った場合
        // N 回高橋君が、 i 回青木君が勝利
        // (A/A+B)^N * (B/A+B)^i の確率で、ゲームが M 回になり、これが (M-1)C(i) パターン起きる
        mint taka_win = fact_a[N] * noc.Inverse(fact_ab[N].x);
        taka_win *= fact_b[i] * noc.Inverse(fact_ab[i].x);
        taka_win *= M;
        taka_win *= noc.Combination(M-1, i);

        // 同様に青木君が勝った場合も起きる
        mint ao_win = fact_a[i] * noc.Inverse(fact_ab[i].x);
        ao_win *= fact_b[N] * noc.Inverse(fact_ab[N].x);
        ao_win *= M;
        ao_win *= noc.Combination(M-1, i);

        // これらを足し合わせて期待値が出せる
        ans += taka_win;
        ans += ao_win;
    }

    // C がある場合を考慮
    // 確率 (A+B)/100 で勝敗が決まるゲームで勝敗が決まるまでにかかるゲーム数
    // → 100 / (A+B)
    mint mul_tmp = 100 * noc.Inverse(A+B);
    // これを C を考えないケースに書けると、答え
    ans *= mul_tmp;

    printf("%lld\n", ans);
    return 0;
}

