ll fact[N_MAX], rfact[N_MAX];

ll perm(ll n, ll r){
    return (fact[n] * rfact[r]) % MOD;
}

ll comb(ll n, ll r){
    return (perm(n, r) * rfact[n-r]) % MOD;
}

void init(ll n){
    fact[0] = fact[1] = 1;
    rfact[0] = rfact[1] = 1;
    for(int i=2;i<=n;++i) {
        fact[i] = (fact[i-1] * (ll)i) % MOD;
        rfact[i] = 1;
        ll k = MOD-2;
        ll a = fact[i];
        while(k > 0){
            if(k & 1){
                rfact[i] *= a;
                rfact[i] %= MOD;
            }
            a *= a;
            a %= MOD;
            k  >>= 1;
        }
    }
}

ll modpow(ll a, ll t) {
    ll ret = 1LL;
    while(t){
        if(t & 1LL){
            ret *= a;
            ret %= MOD;
        }
        a *= a;
        a %= MOD;
        t >>= 1;
    }
    return ret;
}

int main() {
    std::ios::sync_with_stdio(0); cin.tie(0);
    ll n,a,b,c;
    cin >> n >> a >> b >> c;

    init(2*n);

    vector<ll> pow_a(n+1, 1), pow_b(n+1, 1);
    for(int i=1;i<=n;++i) {
        pow_a[i] = (pow_a[i-1] * a) % MOD;
        pow_b[i] = (pow_b[i-1] * b) % MOD;
    }

    ll ans = 0LL;
    for(int i=n;i<2*n;++i){
        ll tmp = (((pow_a[n] * pow_b[i-n]) % MOD) + ((pow_a[i-n] * pow_b[n]) % MOD)) % MOD;
        tmp = (((tmp * i) % MOD) * comb(i-1, n-1)) % MOD;
        tmp = (tmp * modpow(modpow(a+b, i), MOD-2)) % MOD;
        ans = (ans + tmp) % MOD;
    }
    ans = (ans * 100  * modpow(100-c, MOD-2)) % MOD;
    cout << ans << endl;


}

