    //cout << a << ' ' << b << ' ' << c << endl;
    ll ans = 0;
    //AがN勝、Bがi勝である場合
    rep(i, N){
        ll p = comb(N-1+i, i);
        p *= mpow(a, N), p %= MOD;
        p *= mpow(b, i), p %= MOD;
        ll cnt = (N+i)*(c+1)%MOD;
        ans += p*cnt;
        ans %= MOD;
    }
    //Aがi勝、BがN勝である場合
    rep(i, N){
        ll p = comb(N-1+i, i);
        p *= mpow(b, N), p %= MOD;
        p *= mpow(a, i), p %= MOD;
        ll cnt = (N+i)*(c+1)%MOD;
        ans += p*cnt;
        ans %= MOD;
    }
    cout << ans << endl;
}

