const int MXN=200001;//変更可
ll fac[MXN],inv[MXN],finv[MXN];

void COMinit(int M) {
    fac[0]=fac[1]=1;
    inv[1]=1;
    finv[0]=finv[1]=1;
    for(int i=2;i<MXN;i++){
        fac[i]=fac[i-1]*i%M;
        inv[i]=M-M/i*inv[M%i]%M;
        finv[i]=finv[i-1]*inv[i]%M;
    }
}

ll COMBI(int N,int K,int M){
    if(N<K){
        return 0;
    }
    if(N<0||K<0){
        return 0;
    }
    return fac[N]*finv[N-K]%M*finv[K]%M;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll N,A,B,C;//Cは別物として考えていい（線形性より）
    cin >> N >> A >> B >> C;
    COMinit(MOD);
    ll resA=0,resB=0,powa=1,powb=1;
    rep(i,N){//aoki が i 回勝つ
        resA+=(N+i)*((powb*COMBI(N-1+i,i,MOD))%MOD)%MOD;
        powb*=(B*inv[A+B])%MOD;
        powb%=MOD;
        resA%=MOD;
    }
    resA*=pow_mod(A,N);
    rep(i,N){//takahashi が i 回勝つ
        resB+=(N+i)*((powa*COMBI(N-1+i,i,MOD))%MOD)%MOD;
        powa*=(A*inv[A+B])%MOD;
        powa%=MOD;
        resB%=MOD;
    }
    resB*=pow_mod(B,N);
    resA%=MOD;resB%=MOD;
    ll res=(resA+resB)%MOD;
    res*=pow_mod(inv[A+B],N);
    res%=MOD;
    res*=100;
    res%=MOD;
    res*=inv[100-C];
    res%=MOD;
    cout << res << endl;
}
