  tie(fs, i_fs) = MakeFactorialTables(2 * n);

  auto c_fn = [&](int x, int y) -> FiniteField {
    if (y < 0 || x < y ) return 0;
    return fs[x] * i_fs[y] * i_fs[x - y];
  };

  FiniteField p = FiniteField(a) / (FiniteField(a) + FiniteField(b));
  FiniteField q = FiniteField(b) / (FiniteField(a) + FiniteField(b));

  vector<FiniteField> p_powers(n + 1), q_powers(n + 1);
  p_powers[0] = 1;
  q_powers[0] = 1;
  for (int i = 1; i <= n; i++) {
    p_powers[i] = p_powers[i - 1] * p;
    q_powers[i] = q_powers[i - 1] * q;
  }

  FiniteField ans = 0;

  for (int k = 0; k < n; k++) {
    ans += FiniteField(n + k) * p_powers[n] * q_powers[k] * c_fn(n - 1 + k, k);
    ans += FiniteField(n + k) * q_powers[n] * p_powers[k] * c_fn(n - 1 + k, k);
  }

  // cout << ans << endl;

  ans *= FiniteField(100) / (FiniteField(100) - FiniteField(c));

  cout << ans << endl;
}

