void calc_inv() {
	fact[0] = 1, fact[1] = 1;
	for (int i = 2; i <= 200000 + 10; i++) {
		fact[i] = fact[i - 1] * i;
		fact[i] %= MOD;
	}

	fact_inv[200000 + 10] = modpow(fact[200000 + 10], MOD - 2);
	for (int i = 200000 + 9; i >= 0; i--) {
		fact_inv[i] = fact_inv[i + 1] * (i + 1);
		fact_inv[i] %= MOD;
	}
}

ll comb(int a, int b) {
