    modint tak_win = modint(A) / (A + B);
    modint aok_win = modint(B) / (A + B);

    REP(i, N, 2 * N) {
        modint tmp = modint::C(i - 1, N - 1);
        tmp *= ((tak_win ^ N) * (aok_win ^ (i - N))) + ((tak_win ^ (i - N)) * (aok_win ^ N));
        tmp *= i;
        res += tmp;
    }

    res *= 100;
    res /= 100 - C;

    print(res);

}

