ll pow_mod(ll a, ll n, ll MOD) {
    ll res = 1;
    while (n > 0) {
        if (n & 0x01) { 
            res *= a;
            res %= MOD;
        }
        a = a * a;
        a %= MOD;
        n >>= 1LL;
    }
    return res;
}

ll recipro_mod(ll num, ll MOD) {
    return pow_mod(num, MOD - 2, MOD);
}

void fact_mod(vl& fact, vl& rFact, const int Size, const ll MOD) {
    fact = vl(Size, 0);

    fact[0] = 1;
    FOR(i, 1, Size) fact[i] = fact[i-1] * i % MOD;

    rFact = vl(Size, 0);
    rFact[0] = 1;
    rFact[Size-1] = recipro_mod(fact[Size-1], MOD);
    for (int i = Size-1; i > 0; i--) rFact[i - 1] = rFact[i] * i % MOD;
}

ll combi_mod(vl& fact, vl& rFact, ll n, ll k, const ll MOD){
    if (n < 0 || k < 0 || n < k) return 0;
    return fact[n] % MOD * rFact[k] % MOD * rFact[n - k] % MOD;
