typedef modular<int> mint;

struct Comb {
    int N;
    vector<mint> fac, ifac, inv;

    Comb(int _n=1) {
        resize(2);
        fac[0] = fac[1] = ifac[0] = ifac[1] = inv[1] = 1;
        N = 1; grow(_n);
    }

    void resize(int _s) {
        fac.resize(_s); ifac.resize(_s); inv.resize(_s);
    }
    bool grow(int _n) {
        if (_n <= N) return false;
        swap(_n, N); resize(N+1);
        for (int i = _n+1; i <= N; i++) {
            fac[i] = fac[i-1] * i;
            inv[i] = (-MOD/i) * inv[MOD%i];
            ifac[i] = ifac[i-1] * inv[i];
        }
        return true;
    }
    // perm
    mint a(int n, int k) {
        if (n < k || k < 0) return 0;
        if (n > N) grow(n);
        return fac[n] * ifac[n-k];
    }
    // choose
    mint c(int n, int k) {
        if (n < k || k < 0) return 0;
        if (n > N) grow(n);
        return fac[n] * ifac[n-k] * ifac[k];
    }
}c(2e5+10);

void solve() {
    int n,x,y,z;
    cin >> n;
    cin >> x >> y >> z;
    mint p = mint(x)/(x+y);
    mint q = 1-p;
    mint coeff = mint(100)/(x+y);

    vector<mint> pw(n+1), qw(n+1);
    pw[0] = qw[0] = 1;
    for (int i = 1; i <= n; i++) {
        pw[i] = pw[i-1] * p;
        qw[i] = qw[i-1] * q;
    }

    mint res = 0;
    for (int i = 0; i < n; i++) {
        mint prob = c.c(n-1+i, i) * (pw[n] * qw[i] + pw[i] * qw[n]);
        res += prob * (n+i);
    }
    res *= coeff;
    cout << res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    solve();
    cout << endl;
}

