    mint_t ans = 0;
    mint_t AN = A.pow( N ); // A^N
    mint_t BN = B.pow( N ); // B^N
    mint_t AM_N = 1;        // A^(M-N)
    mint_t BM_N = 1;        // B^(M-N)
    for ( int M = N; M < 2 * N; M++ )
    {
        mint_t tmp = comb( M - 1, N - 1 );
        tmp *= ( AN * BM_N + AM_N * BN );
        tmp *= M;
        tmp /= mint_t( 1 ) - C;

        ans += tmp;

        AM_N *= A;
        BM_N *= B;
    }

    cout << ans << endl;

    return 0;
}

