    // 階乗計算
    fact[0]=1;
    for(int i = 1; i < MAX_FACT; ++i) {
        fact[i] = fact[i-1] * i % mod;
    }

    // 引き分け無視して後で 100/(A+B) を掛ければいい
    vector<ll>tk_win(N);
    vector<ll>ao_win(N);
    ll aa = A * inv_ab % mod;
    ll bb = B * inv_ab % mod;
    ll aN = modPow(aa, N);
    ll bN = modPow(bb, N);
    ll ac = 1;
    ll bc = 1;
    for (int i = 0; i < N; ++i) {
        tk_win[i] = aN * bc % mod;
        tk_win[i] = tk_win[i] * nCk(N+i-1, i) % mod;
        bc = bc * bb % mod;
        ao_win[i] = bN * ac % mod;
        ao_win[i] = ao_win[i] * nCk(N+i-1, i) % mod;
        ac = ac * aa % mod;
    }
    ll ans = 0;
    for (int i = 0; i < N; ++i) {
        ans += tk_win[i] * (N+i);
        ans += ao_win[i] * (N+i);
        ans %= mod;
    }
    ans = ans * 100 % mod;
    ans = ans * inv_ab % mod;
    cout << ans;
    return 0;
}

