typedef long long ll;
ll expmod(ll a, ll b, ll mod) {
	ll rlt = 1;
	for (a %= mod; b; a = a * a % mod, b >>= 1) if (b & 1) rlt = rlt * a % mod;
	return rlt;
}

#define N 200020
int fac[N], rfac[N], ri[N];
void init() {
	fac[0] = 1;
	for (int i = 1; i < N; i ++) fac[i] = 1ll * fac[i-1] * i % mod;
	rfac[0] = rfac[1] = 1, ri[1] = 1;
   	for(int i = 2; i < N; i ++){
      		int t = mod / i;
      		ri[i] = (1ll * t * (mod - ri[mod % i])) % mod;
      		rfac[i] = (1ll * rfac[i-1] * ri[i]) % mod;
   	}
}

int func(int a, int b, int c) {
	int r = expmod(1 - c, mod - 2, mod);
	int now = expmod(r, n + 1, mod);
	int sum = 0;
	for (int i = 0; i < n; i ++) {
		sum = (sum + 1ll * fac[n+i] * rfac[i] % mod * now) % mod;
		now = 1ll * now * b % mod * r % mod;
	}
	return 1ll * sum * expmod(a, n, mod) % mod * rfac[n-1] % mod;
}

