  long long r = 1LL;
  while (b) {
    if (b & 1LL)r *= a;
    if (r >= MOD)r %= MOD;
    a *= a;
    if (a >= MOD)a %= MOD;
    b >>= 1LL;
  }
  return r % MOD;
}

long long fact[200000];
long long rfact[200000];


long long nCr(long long n, long long r){ 
  long long ret = 1LL;
  ret *= fact[n];
  ret %= MOD;
  ret *= rfact[r];
  ret %= MOD;
  ret *= rfact[n-r];
  ret %= MOD;
  return ret;
}

int main() {
  clr(fact, 0);
  fact[0] = 1;
  rep(i, 1, 200000) {
    fact[i] = fact[i - 1] * i;
    fact[i] %= MOD;
  }
  clr(rfact, 0);
  rfact[0] = 1;
  rep(i, 1, 200000) {
    rfact[i] = rfact[i - 1] * modpow(i, MOD - 2);
    rfact[i] %= MOD;
  }
  ll n, a, b, c;
  cin >> n >> a >> b >> c;
  ll a1 = a * modpow(100 - c, MOD - 2) % MOD;
  ll b1 = b * modpow(100 - c, MOD - 2) % MOD;
  ll c1 = 100 * modpow(c, MOD - 2) % MOD;
  ll ans = 0;
  rep(i, 0, n) {
    ll a2 = n;
    ll b2 = i;
    ll t = a2+b2;
    ll p = nCr(t-1,b2);
    ll r = (modpow(a1, a2) * modpow(b1, b2) % MOD) * t % MOD;
    r *= p;
    r %= MOD;
    ans += r;
    ans %= MOD;
  }
  rep(i, 0, n) {
    ll a2 = i;
    ll b2 = n;
    ll t = a2+b2;
    ll p = nCr(t-1,a2);
    ll r = (modpow(a1, a2) * modpow(b1, b2) % MOD) * t % MOD;
    r *= p;
    r %= MOD;
    ans += r;
    ans %= MOD;
  }
  if (c == 0) {
    cout << ans << endl;
  }
  else {
    cout << ans*c1 % MOD << endl;
  }
  return 0;
}

