#define SIZE 500000

// a^b（on Z^mod) : O(log(b))
ll modpow(ll a, ll b){
	if (b == 0)return 1;
	ll z = modpow(a, b / 2);
	z = z*z%mod;
	if (b % 2 == 1)z = z*a%mod;
	return z;
}

// a^-1 (on Z^mod) : O(log(mod))
ll modinv(ll a) {
    return modpow(a, mod-2);
}

ll inv[SIZE + 1]; // a^-1 (on Z^mod)のテーブル : O(SIZE)
ll kai[SIZE + 1]; // (a)! (on Z^mod)のテーブル : O(SIZE)
ll invkai[SIZE + 1]; // (a)!^(-1) (on Z^mod)のテーブル : O(SIZE)
void invinit()
{
	inv[1] = 1;
	for (int i = 2; i <= SIZE; i++)
	{
		inv[i] = mod - (mod / i)*inv[mod%i] % mod;
	}

	kai[0] = invkai[0] = 1;
	for (int i = 1; i <= SIZE; i++)
	{
		kai[i] = kai[i - 1] * i%mod;
		invkai[i] = invkai[i - 1] * inv[i] % mod;
	}
}


int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    invinit();
    int N, a, b, c;
    cin >> N >> a >> b >> c;
    ll aa = (a * (modinv(a+b)))%mod;
    ll bb = (b * (modinv(a+b)))%mod;

    ll asum = 0;
    ll bsum = 0;
    for (int k=0;k<N;k++){
        asum +=(((((((kai[N+k-1]*invkai[k])%mod)*invkai[N-1])%mod)*(N+k)%mod)*modpow(aa,N))%mod)*modpow(bb,k)%mod;
        asum %= mod;
        bsum +=(((((((kai[N+k-1]*invkai[k])%mod)*invkai[N-1])%mod)*(N+k)%mod)*modpow(bb,N))%mod)*modpow(aa,k)%mod;
        bsum %= mod;
    }

    cout << (((asum+bsum) *100)%mod * modinv(100-c))%mod << endl;

}

