const ll MOD = 1e9 + 7;

ll power(ll x, ll e) {
  ll v = 1;
  for (; e > 0; e >>= 1) {
    if (e & 1) {
      v = v * x % MOD;
    }
    x = x * x % MOD;
  }
  return v;
}

ll inverse(ll x) {
  return power(x, MOD - 2);
}

vector<ll> fact, factInv;
void initFact(int N) {
  fact.resize(N + 1);
  factInv.resize(N + 1);
  fact[0] = 1;
  for (int i = 1; i <= N; i++) {
    fact[i] = fact[i - 1] * i % MOD;
  }
  factInv[N] = inverse(fact[N]);
  for (int i = N - 1; i >= 0; i--) {
    factInv[i] = factInv[i + 1] * (i + 1) % MOD;
  }
}

ll choose(int n, int k) {
  if (k > n) {
    return 0;
  } else {
    return fact[n] * factInv[k] % MOD * factInv[n - k] % MOD;
  }
}

ll f(ll pA, ll pB, ll pC, ll N) {
  ll qA = pA * inverse((pA + pB) % MOD) % MOD;
  ll qB = pB * inverse((pA + pB) % MOD) % MOD;
  ll res = 0;
  for (int M = N; M < 2 * N; M++) {
    ll e1 = 1;
    e1 = e1 * power(qA, N) % MOD;
    e1 = e1 * power(qB, M - N) % MOD;
    ll e2 = 1;
    e2 = e2 * power(qA, M - N) % MOD;
    e2 = e2 * power(qB, N) % MOD;
    ll e = (e1 + e2) % MOD;
    e = e * choose(M - 1, N - 1) % MOD;
    e = e * M % MOD;
    e = e * inverse((1 - pC + MOD) % MOD) % MOD;
    //e = e * inverse(power((1 - pC + MOD) % MOD, M + 1)) % MOD;
    res = (res + e) %  MOD;
  }
  return res;
}

