        mInt subAns = (cA * cB * mInt::comb(x + y, x)) * (x + y + 1);
        ans += subAns;
    }
    for (int y = 0; y < N; y++) {
        int x = N - 1;
        mInt cA = A ^(x + 1);
        mInt cB = B ^(y);

        mInt subAns = (cA * cB * mInt::comb(x + y, x)) * (x + y + 1);
        ans += subAns;
    }
    cout << (int) (ans / C) << endl;

}

