li fastexp(li x, li n) {
    if (n == 0)return 1;
    if (n == 1)return x;
    li x2 = x * x % MOD;
    li res = fastexp(x2, n / 2);
    if (n % 2 > 0)res = (res * x) % MOD;
    return res % MOD;
}

