long long Power(long long a, long long k)
{
    long long t=1, S=a, Su=1;
    while (k > 0)
    {
        if (k % (2*t) != 0)
        {
            k -= t;
            Su *= S;
            Su %= MOD;
        }
        t *= 2;
        S *= S;
        S %= MOD;
    }
    return Su;
}

