const long long mod = 1e9 + 7;

long long mod_pow(long long x, long long k){
  x += mod;
  x %= mod;
  long long ret = 1;
  while(k){
    if(k&1) ret *= x, ret %= mod;
    x *= x, x %= mod;
    k >>= 1;
  }
  return ret;
}

