using namespace std;
using ll = long long;

const ll MAX = 200010;
const ll MOD = 1e7LL;

long long fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

long long pow_mod(long long x, long long n) {
    long long a = 1, x2n = x;
    x2n %= MOD;
    while (n!=0) {
        if (n&1==1) {
            a *= x2n;
            a %= MOD;
        }
        x2n *= x2n;
        x2n %= MOD;
        n >>= 1;
    }
    return a;
}

ll mod_inv(ll a, ll m) {
    ll b = m, x = 1, y = 0, s, t;
    while ( b != 0 ) {
        s = y;
        y = x - ( a / b ) * y;
        x = s;
        t = b;
        b = a % b;
        a = t;
    }
    return (x % m + m) % m;
}

int main() {
    ll N, A, B, C;
    cin >> N >> A >> B >> C;

    COMinit();
    ll a = A * mod_inv(A+B, MOD) % MOD;
    ll b = B * mod_inv(A+B, MOD) % MOD;
    ll an = pow_mod(a, N);
    ll bn = pow_mod(b, N);
    ll ak = 1, bk = 1;
    ll sum =  0;
    for ( int i = 0; i < N; i++ ) {
        ll x = COM(N-1+i, N-1) * bk % MOD;
        x = x * an % MOD;
        x = x * (N+i) % MOD;
        sum += x;
        sum %= MOD;
        bk = bk * b % MOD;
    }
    for ( int i = 0; i < N; i++ ) {
        ll x = COM(N-1+i, N-1) * ak % MOD;
        x = x * bn % MOD;
        x = x * (N+i) % MOD;
        sum += x;
        sum %= MOD;
        ak = ak * a % MOD;
    }
    sum = sum * 100 % MOD;
    sum = sum * mod_inv(100-C, MOD) % MOD;
    ll ans = sum;
    cout << ans << '\n';
    return 0;
}

