long long Calc(long long A, long long B, long long C) {
	if (B == 0) return 1;
	if (B % 2 == 0) {
		long long D = Calc(A, B / 2, C) % C;
		return (D * D) % C;
	}
	return (A * Calc(A, B - 1, C)) % C;
}

long long Comb(long long A, long long B) {
	long long RT = 1;
	RT *= F[A]; RT = RT % MOD;
	RT *= RF[B]; RT = RT % MOD;
	RT *= RF[A - B]; RT = RT % MOD;
	return RT;
}

void init(long long N) {
	F[0] = 1, F[1] = 1, RF[0] = 1, RF[1] = 1;
	for (int i = 2; i <= N; i++) F[i] = (F[i - 1] * i) % MOD;
	for (int i = 2; i <= N; i++) RF[i] = Calc(F[i], MOD - 2, MOD);
}

