    cin >> N >> A >> B >> C;
}

void solve() {
    ans = mint(0);
    mint pa = mint(A) / mint(A+B);
    mint pb = mint(B) / mint(A+B);
    rep(i,N) {
        mint ans1 = pa.pow(N) * pb.pow(i);
        mint ans2 = pa.pow(i) * pb.pow(N);
        ans += ncr(N+i-1,N-1) * (ans1 + ans2) * mint(N+i);
    }
    ans *= mint(100);
    ans /= mint(A+B);
}

