void calc_expcpower(int n, ll expc, ll m = MOD)
{ //Calculate power of p_a,p_b up to n
    expcpow.resize(n + 1);
    expcpow[0] = 1;
    REP(i, n)
    {
        expcpow[i + 1] = expcpow[i] * expc % m ;
    }
}

vector<ll> fact, invfact;
void calc_fact(int n, ll m = MOD)
{ //Calculate factorial up to n
    fact.resize(n + 1);
    invfact.resize(n + 1);
    fact[0] = invfact[0] = 1;
    REP(i, n)
    {
        fact[i + 1] = fact[i] * (i + 1) % m;
        invfact[i + 1] = invfact[i] * mod_inv(i + 1) % m;
    }
}
ll perm(int n, int k, ll m = MOD)
{
    if (n < 0 || k < 0 || k > n)
        return 0;
    return fact[n] * invfact[n - k] % m;
}
ll comb(int n, int k, ll m = MOD)
{
