class Combinatons {
public:
    Combinatons(int n = 0) :fact(n + 1), rev(n + 1) {
        fact[0] = 1;
        for (int i = 1; i < n + 1; ++i)fact[i] = fact[i - 1] * i;
        for (int i = 0; i < n + 1; ++i)rev[i] = fact[i].inverse();
    }

    mint C(int n, int r) {
        if (n < r)return 0;
        return fact[n] * rev[r] * rev[n - r];
    }

    mint H(int n, int r) {
        return C(n + r - 1, r);
    }

    mint P(int n, int r) {
        if (r > n)return 0;
        return fact[n] * rev[n - r];
    }

    mint catalan(int n) {
        return fact[2 * n] * rev[n + 1] * rev[n];
    }

private:
    vector<mint> fact, rev;
};

void solve() {
    int N, A, B, C;
    cin >> N >> A >> B >> C;
    mint a(A), b(B), c(C);
    mint diff = mint(100) / (a + b);

    Combinatons cm(2 * N);
    mint p = a / (a + b), q = b / (a + b);

    // AとBのどちらかが勝った回数がiのときの試行回数の期待値
    vector<mint> dp(2 * N);
    rep(i, 2 * N - 1) dp[i + 1] = dp[i] + diff;
    mint ans;
    for (int i = N; i < 2 * N; ++i) {
        // AがN-1回勝つ=>Aが勝つ
        ans += dp[i] * cm.C(i - 1, N - 1)
            * (p.pow(N) * q.pow(i - N) + q.pow(N)*p.pow(i - N));
    }
    cout << ans << endl;
}

