using namespace std;

constexpr int64_t mod = 1'000'000'007;

int64_t mpow(int64_t x, int64_t y){
    if(y==0) return 1;
    if(y==1) return x%mod;
    if(y%2 == 0) return mpow(x*x%mod, y/2) % mod;
    return mpow(x*x%mod, y/2) % mod * x % mod;
}

static int64_t fact[200001], finv[200001];
int64_t comb(int64_t n, int64_t r){
    if(n < r) return 0;
    return fact[n]*finv[r] % mod * finv[n-r] % mod;
}

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n, a, b, c;
    cin >> n >> a >> b >> c;

    fact[0] = 1;
    for(int i=0;i<200000;i++) fact[i+1] = (i+1)*fact[i]%mod;
    finv[200000] = mpow(fact[200000], mod-2);
    for(int i=200000;i>0;i--) finv[i-1] = finv[i]*i%mod;

    int64_t prob, ex = 0;
    for(int64_t aoki=0;aoki<n;aoki++){
        prob = comb(n+aoki-1, aoki) * mpow(a,n)%mod *mpow(a+b,(mod-2)*n)%mod * mpow(b,aoki)%mod * mpow(a+b,(mod-2)*aoki)%mod;
        ex = (ex + prob * (n+aoki) % mod) % mod;
    } 
    for(int64_t taka=0;taka<n;taka++){
        prob = comb(n+taka-1, taka) * mpow(a,taka)%mod *mpow(a+b,(mod-2)*taka)%mod * mpow(b,n)%mod * mpow(a+b,(mod-2)*n)%mod;
        ex = (ex + prob * (n+taka) % mod) % mod;
    }  
    cout << ex * 100 % mod * mpow(a+b, mod-2) % mod << endl;

    return 0;
}

