	map<ll, pair<ll, ll>> mp;

	ll an = comb.mod_pow(A, N, MOD);
	ll bn = comb.mod_pow(B, N, MOD);
	ll base = comb.mod_pow(A + B, N, MOD);
	ll ai = 1;
	ll bi = 1;
	FOR(i, N, 2 * N) {
		ll up = (an * bi + ai * bn) % MOD;
		(up *= comb.comb(i, i - N)) %= MOD;
		mp[i] = { up, base };
		(base *= A + B) %= MOD;
		(ai *= A) %= MOD;
		(bi *= B) %= MOD;
	}

	ll res = 0;
	for (auto itr = mp.begin(); itr != mp.end(); ++itr) {
		ll eval = itr->first;
		ll up = itr->second.first;
		ll base = itr->second.second;
		base = comb.mod_pow(base, MOD - 2, MOD);

		ll tmp = (eval*up) % MOD;
		tmp = (tmp*base) % MOD;
		res = (res + tmp) % MOD;
	}
	res = (res * 100) % MOD;
	//res = (res*(A + B)) % MOD;
	res = (res* comb.mod_pow(A + B, MOD - 2, MOD)) % MOD;
