vl fact,fact_inv;

// 繰り返し二乗法
ll power(ll a, ll b) {
	ll res = 1LL;
	while (b > 0) {
		if (b & 1LL) res = res * a%mod;
		a = a * a%mod;
		b >>= 1LL;
	}
	return res;
}

ll comb(ll n, ll r) {
	return (fact[n] * fact_inv[r]) % mod*fact_inv[n - r] % mod;
}

void calcComb() {
	ll num = 200020LL;
    fact.resize(num);
    fact_inv.resize(num);
	fact[0] = 1LL;
	for (ll i = 0; i < num; i++) {
		fact[i + 1] = fact[i] * ((ll)i + 1LL) % mod;
	}
	fact_inv[num] = power(fact[num], mod - 2LL);
	for (ll i = num - 1LL; i >= 0; i--) {
		fact_inv[i] = fact_inv[i + 1] * ((ll)i + 1LL) % mod;
	}
}

// 逆元を求める
long long mod_inv(long long value) {

	long long b = mod, u = 1LL, v = 0LL;

	while (b) {
		long long t = value / b;
		value -= t * b;
		swap(value, b);
		u -= t * v;
		swap(u, v);
	}
	u %= mod;
	if (u < 0) u += mod;

	return u;
}

ll mod_pow(ll num, long long n) {
	long long a = num;
	long long res = 1;
	while (n > 0) {
		if (n & 1) res = res * a % mod;
		a = a * a % mod;
		n >>= 1;
	}
	return res;
}

void solve() {

	cin >> N >> A >> B >> C;

	calcComb();

	ll ans = 0;
	for (ll M = N; M < 2 * N; M++) {
		ll X = comb(M - 1, N - 1) * ((mod_pow(A * mod_inv(100 - C) % mod, N) * mod_pow(B * mod_inv(100 - C) % mod, M - N) % mod + mod_pow(B * mod_inv(100 - C) % mod, N) * mod_pow(A * mod_inv(100 - C) % mod, M - N) % mod) % mod) % mod;
		ll Y = M * 100 % mod * mod_inv(100 - C) % mod;
		ans += X * Y % mod;
	}
	cout << ans % mod << endl;

	return;

}

