ll po(ll x,ll y,ll p = mod) {ll res=1;x%=p;while(y>0){if(y&1)res=(res*x)%p;y=y>>1;x=(x*x)%p;}return res;}

int poA[N] , poB[N] , fac[N] , invfac[N] , ihun[N] , c;

void pre(int A , int B , int C){

    int tmp = po(100LL , mod - 2);
    c =  (100LL * po(100 - C , mod - 2)) % mod ;
    fac[0] = poA[0]  = ihun[0] = poB[0] = 1;

    for(int i = 1 ; i < N ; ++i){
        poA[i] = (poA[i-1] * A) % mod ;
        poB[i] = (poB[i-1] * B) % mod ;
        ihun[i] = (ihun[i - 1] * tmp) % mod;
        fac[i] = (i * fac[i - 1]) % mod;
    }
    invfac[N - 1] = po(fac[N-1] , mod - 2);
    for(int i = N - 2 ; i >= 0 ; --i){
        invfac[i] = (invfac[i + 1] * (i + 1)) % mod ;
    }
}

int ncr(int n , int r){
    if(r > n) return 0; 
    int res = (fac[n] * invfac[r]) % mod ;
    res = (res * invfac[n - r]) % mod ;
    return res;
}


int get_term(int K , int n){
    int res = ncr(K - 1 , n - 1);
    int res2 = ((poA[K-n] * poB[n]) % mod + (poA[n] * poB[K - n])%mod) % mod;
    res = ( res * res2 ) % mod ;
    res = (res * ihun[K]) % mod;
    res = (res * K) % mod ;
    res = (res * c) % mod ;
    return res;
}

void solve()
{
    int n , A , B , C ;
    cin >> n >> A >> B >> C ;
    int su = (100LL * po(A + B , mod - 2)) % mod;
    A = (su * A) % mod ;
    B = (su * B) % mod ;

    pre(A , B , C);
    int ans = 0;
    for(int K = n ; K <= 2 * n - 1 ; ++K) ans = (ans + get_term(K , n)) % mod ;
    cout << ans;
}   


