long long extended_euclid(long long a, long long b, long long *x, long long *y)
{
    if (a == 0) {
        *x = 0;
        *y = 1;
        return b;
    }
    long long x1,y1,g;
    g = extended_euclid(b%a, a, &x1, &y1);
    *x = y1 - (b/a)*x1;
    *y = x1;
    return g;
}

long long mod_divide(long long a, long long b, long long mod)
{
    long long x,y;
    long long g = extended_euclid(b,mod,&x,&y);
    assert(g == 1);
    x = (x%mod + mod)%mod;
    return (a*x) %mod;
}

