        cur_B_pow = (cur_B_pow * B) % MOD; 
        coef = (coef * (N+B_exp)) % MOD; 
        coef = mod_divide(coef, B_exp+1, MOD); 
        nl
    }

    ll B_pow_N = cur_B_pow; 
    ll cur_A_pow = 1; 
    coef = 1; 
    for (int A_exp=0; A_exp<N; A_exp++) {
        ll len = N + A_exp; 
        ll term = len * coef % MOD * B_pow_N % MOD * cur_A_pow % MOD; 
        ans = (ans + term) % MOD; 
        prl(A_exp) 
        prl(len)
        prl(coef) 
        prl(B_pow_N) 
        prl(cur_A_pow) 
        prl(term)
        cur_A_pow = (cur_A_pow * A) % MOD; 
        coef = (coef * (N+A_exp)) % MOD; 
        coef = mod_divide(coef, A_exp+1, MOD); 
        nl
    }

    ans = (ans*inv) % MOD; 
    cout << ans << endl; 
    return 0;
}

