class combination_mod{
  const long long mod;
  const long long size;

  vector<long long> fact; //n!
  vector<long long> fact_inv; // (n!)^-1

  void make_fact(){
    fact[0] = 1;
    for(long long i=1; i<size; i++){
      fact[i] = fact[i-1]*i % mod;
    }
  }

  void make_fact_inv(){
    fact_inv[0] = fact_inv[1] = 1;
    for(long long i=2; i<size; i++){
      fact_inv[i] = fact_inv[mod%i] * (mod - mod/i) % mod;  // x ^ -1
    }
    for(int i=2; i<size; i++){
      fact_inv[i] = fact_inv[i-1] * fact_inv[i] % mod;  // x! ^ -1
    }
  }

public:
  combination_mod(long long mod_, long long size_ = 2000000) : mod(mod_), size(size_+1){
    fact.resize(size);
    fact_inv.resize(size);
    make_fact();
    make_fact_inv();
  }

  //nCk mod p O(1)
  long long operator()(long long n, long long k){
    if(k==0 || n==k) return 1;
    long long ret = fact[n] * fact_inv[k] % mod * fact_inv[n-k] % mod;
    return ret;
  }
};

int main(){
  long long n,A,B,C;
  cin >> n,A,B,C;

  combination_mod choose(mod, n*2 + 100);

  long long ans = 0;
  long long pa = A * my_pow_mod(100-C, mod-2, mod) % mod;
  long long pb = B * my_pow_mod(100-C, mod-2, mod) % mod;
  long long pc = C * my_pow_mod(100, mod-2, mod) % mod;

  long long pc_ = (1 - pc + mod) % mod;
  long long pc_inv = my_pow_mod(pc_, mod-2, mod);

  for(int k=0; k<2; k++, swap(pa, pb))
  for(int ak=0; ak<n; ak++){
    long long prob = choose(ak+n-1, ak) * my_pow_mod(pa, ak, mod) % mod;
    prob = prob * my_pow_mod(pb, n, mod) % mod;
    long long e = (ak+n) * pc_inv % mod;
    ans += e * prob % mod;
    ans %= mod;
  }

  println(ans);

  return 0;
}

