//Pow_Mod O(log(n))
long long Pow_Mod(long long x, long long n, long long mod) {
    long long res = 1;
    for (; n > 0; n >>= 1, (x *= x) %= mod) if (n & 1) (res *= x) %= mod;
    return res;
}

//Inv_Mod O(log(mod))
long long Inv_Mod(long long x, long long mod){
	return Pow_Mod(x,mod-2,mod); 
}


//Combination Mod
class Combination_Mod {
public:
	vector<long long> fac,finv,inv;
	long long MOD;

	Combination_Mod(int N,long long mod) : fac(vector<long long>(N + 1)), finv(vector<long long>(N + 1)), inv(vector<long long>(N + 1)), MOD(mod) {
		fac[0] = fac[1] = finv[0] = finv[1] = inv[1] = 1;
		for (int i = 2; i <= N; ++i) {
			fac[i] = fac[i - 1] * i % MOD;
			inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
			finv[i] = finv[i - 1] * inv[i] % MOD;
		}
	}

	long long num(int n, int k) {
		return ((n < 0 || k < 0 || n < k) ? 0 : fac[n] * (finv[k] * finv[n - k] % MOD) % MOD);
	}
};

int main() {
	ll N,A,B,C; cin >> N >> A >> B >> C;
	Combination_Mod CM(2*N+10,MOD);
	(A *= Inv_Mod(100,MOD)) %= MOD;
	(B *= Inv_Mod(100,MOD)) %= MOD;
	(C *= Inv_Mod(100,MOD)) %= MOD;
	ll F = (1 - C + MOD) % MOD;
	F = Inv_Mod(F,MOD);
	ll G = (((C * F) % MOD) * F) % MOD;

	ll sumA = 1, sumB = 1;
	for(int i = 0; i < N; ++i) (sumA *= A) %= MOD;
	for(int i = 0; i < N; ++i) (sumA *= B) %= MOD;

	ll ans = 0;
	for(ll k = 0; k < N; ++k){
		ll M = N + k;
		ll cnt = (M*F + G) % MOD;
		ans += (cnt*sumA)*CM.num(N-1 + k,k);
		(sumA *= B) %= MOD;
	}
	for(ll k = 0; k < N; ++k){
		ll M = N + k;
		ll cnt = (M*F + G) % MOD;
		ans += (cnt*sumB)*CM.num(N-1 + k,k);
		(sumB *= A) %= MOD;
	}
	cout << ans << endl;

    return 0;
}

