	Modint(long long value) : Modint((unsigned int)(value % mod +mod)) { }
	Modint(const Modint& rhs) : Modint(rhs.value) { }
	bool operator==(const Modint& rhs) const;
	inline bool operator!=(const Modint& rhs) const
