const ll MOD = 1e9 + 7;

ll power(ll x, ll e) {
  ll v = 1;
  for (; e > 0; e >>= 1) {
    if (e & 1) {
      v = v * x % MOD;
    }
    x = x * x % MOD;
  }
  return v;
}

ll inverse(ll x) {
  return power(x, MOD - 2);
}

vector<ll> fact, factInv;
void initFact(int N) {
  fact.resize(N + 1);
  factInv.resize(N + 1);
  fact[0] = 1;
  for (int i = 1; i <= N; i++) {
    fact[i] = fact[i - 1] * i % MOD;
  }
  factInv[N] = inverse(fact[N]);
  for (int i = N - 1; i >= 0; i--) {
    factInv[i] = factInv[i + 1] * (i + 1) % MOD;
  }
}

ll choose(int n, int k) {
  if (k > n) {
    return 0;
  } else {
    return fact[n] * factInv[k] % MOD * factInv[n - k] % MOD;
  }
}

ll f(ll pA, ll pB, ll N) {
  ll res = 0;
  ll qA = pA * inverse((pA + pB) % MOD) % MOD;
  ll qB = pB * inverse((pA + pB) % MOD) % MOD;
  for (int b = 0; b < N; b++) {
    ll e = 1;
    e = e * power(qA, N) % MOD;
    e = e * power(qB, b) % MOD;
    e = e * choose(N + b - 1, N - 1) % MOD;
    e = e * (N + b) % MOD;
    res = (res + e) %  MOD;
  }
  return res;
}

