	ll res = mod_pow(x * x % mod, n / 2, mod);
	if (n & 1) res = res * x % mod;

	return res;
}

 // 20^5以下階乗とその逆元(mod mod[素数])を求める
vector<ll> fact, inv;
void fact_inv(int n, ll mod = MOD) {
	fact.resize(n + 1);
	inv.resize(n + 1);

	fact[0] = 1;
	FOR(i, 1, n + 1) fact[i] = fact[i - 1] * i % mod;
	inv[n] = mod_pow(fact[n], mod - 2, mod);
	for (int i = n; i > 0; i--) inv[i - 1] = inv[i] * i % mod;
}

// nCr % modを求める(modは素数)
ll ncr(ll n, ll r, ll mod = MOD) {
	if (n < r || r < 0 || n < 0) return 0;
	return fact[n] * inv[r] % mod * inv[n - r] % mod;
}


ll div(ll a, ll b, ll mod) {
	a %= mod;
	b %= mod;
	return a * mod_pow(b, mod - 2, mod) % mod;
}

