// x^n
long long mod_pow(long long x,long long n,long long MOD=1000000007LL){
    long long res=1;
    while(n){
        if(n&1) res=(res*x)%MOD;
        x=(x*x)%MOD;
        n>>=1;
    }
    return res;
}

// x^-1
long long mod_inv(long long x,long long MOD=1000000007LL){
    return mod_pow(x,MOD-2);
}

// x + y
long long mod_add(long long x,long long y,long long MOD=1000000007LL){
    return (x+y)%MOD;
}

// x-y
long long mod_sub(long long x,long long y,long long MOD=1000000007LL){
    return (x-y+MOD)%MOD;
}

// x * y
long long mod_mul(long long x, long long y, long long MOD=1000000007LL){
    return x * y % MOD;
}

// x / y
long long mod_div(long long x,long long y,long long MOD=1000000007LL){
    return x * mod_inv(y,MOD) % MOD;
}

template<long long MOD=1000000007ll>
struct ModCombination{
    vector<long long> f,fi;
    ModCombination(){}
    ModCombination(int N){
        init(N);
    }

    // x^-1
    long long invp(long long x){
        return mod_pow(x,MOD-2);
    }

    long long mod_pow(long long x,long long n){
        long long res=1;
        while(n){
            if(n&1) res=(res*x)%MOD;
            x=(x*x)%MOD;
            n>>=1;
        }
        return res;
    }

    void init(int N){
        f.resize(N+1);
        fi.resize(N+1);
        f[0]=1;
        for(int i=1;i<N+1;i++) f[i]=(f[i-1]*i)%MOD;
        for(int i=0;i<N+1;i++) fi[i]=invp(f[i]);
    }

    // nCr
    long long get(long long n,long long r){
        long long ret=f[n];
        ret=(ret*fi[r])%MOD;
        ret=(ret*fi[n-r])%MOD;
        return ret;
    }
};

int main(){
