int N,A,B,C;

ModInt pa,pb,pc;
void solve() {
  ModInt res(0);
  FOR(x,N,2*N) {
    ModInt e=ModInt(1)/(ModInt(1)-pc);
    ModInt c(choose(x-1,N-1));
    ModInt a=ModInt(pa).pow(N)*ModInt(pb).pow(x-N);
    ModInt b=ModInt(pa).pow(x-N)*ModInt(pb).pow(N);
    res+=ModInt(x)*e*c*(a+b);
  }
  cout<<res<<endl;
}

