        (a *= probA) %= MOD;
        (ans += (a * one_step % MOD * (N + i)) % MOD) %= MOD;

        ll b = comb(N - 1 + i, N - 1) * MODpow(probB, N - 1) % MOD * MODpow(probA, i) % MOD;
        (b *= probB) %= MOD;
        (ans += (b * one_step % MOD * (N + i)) % MOD) %= MOD;
    }

    cout << ans << endl;
}

