// template

// fact(n)%MOD, invFact(n)%MOD, inv(n)%MOD, nCk
// Constructor O(N)
// other O(1)
template<typename T>
class Choose {
public:
	vector<T> fact, inv, invFact;

	Choose(T N):fact(N), inv(N), invFact(N){
		inv[1] = 1;
		FOR(i, 2, inv.size()) inv[i] = MOD - (MOD / i) * inv[MOD%i] % MOD;
		fact[0] = invFact[0] = 1;
		FOR(i, 1, fact.size()) {
			fact[i] = fact[i - 1] * i % MOD;
			invFact[i] = (invFact[i - 1] * inv[i]) % MOD;
		}
	}

	//Get nCk
	T operator () (T n, T k) const {
		if (not ((T)0 <= k and k <= n)) return 0;
		return (((fact[n] * invFact[k]) % MOD)*invFact[n - k]) % MOD;
	}
};

struct mint {
	int64_t value;
	mint():value(0){}
	mint(int64_t value_) : value(value_%MOD) {}
	inline mint& operator += (const mint& rhs) {
		value += rhs.value;
		if (value >= MOD) { value -= MOD; }
		return *this;
	}
	inline mint& operator -= (const mint& rhs) {
		value -= rhs.value;
		if (value < 0) {
			value += MOD;
		}
		return *this;
	}
	inline mint& operator *= (const mint& rhs) {
		value *= rhs.value;
		value %= MOD;
		return *this;
	}
	inline mint& operator %= (const mint& rhs) {
		return *this;
	}
};

inline mint operator + (const mint& lhs, const mint& rhs) { mint res = lhs; res += rhs; return res; }
inline mint operator - (const mint& lhs, const mint& rhs) { mint res = lhs;	res -= rhs;	return res; }
inline mint operator * (const mint& lhs, const mint& rhs) { mint res = lhs;	res *= rhs;	return res; }
inline mint operator % (const mint& lhs, const uint64_t& rhs) { return lhs; }

ostream & operator << (ostream & out, mint n) { return out << n.value; }

// x^n % mod
// O(log n)
mint mod_pow(mint x, uint64_t n) {
	mint res = 1;
	while (n > 0) {
		if (n & 1) res = res * x;
		x = x*x;
		n >>= 1;
	}
	return res;
}

void solve() {
	int N, Aorg, Borg, Corg; cin >> N >> Aorg >> Borg >> Corg;
	vector<mint> apow(N+1), bpow(N+1);
	apow[0] = 1;
	bpow[0] = 1;

	Choose<int> choose(max(2*N+1, 101LL));
	mint A, B, C;
	A = Aorg * choose.inv[100LL - Corg];
	B = Borg * choose.inv[100LL - Corg];

	REP(i, N) {
		apow[i + 1] = apow[i] * A;
		bpow[i + 1] = bpow[i] * B;
	}

	mint res = 0;

	REP(i, N) {
		res += mint(choose((N + i - 1), i)) * apow[N] * bpow[i] * (N + i);
		res += mint(choose((N + i - 1), i)) * apow[i] * bpow[N] * (N + i);
	}

	cout << res * 100 * choose.inv[100 - Corg] << endl;
}

