    (A *= 570000004) %= MOD;
    (B *= 570000004) %= MOD;
    (C *= 570000004) %= MOD;
    C = (1 - C + MOD) % MOD;
    {
        auto n = MOD - 3, t = C;
        while(n){
            if(n & 1)(C *= t) %= MOD;
            (t *= t) %= MOD;
            n >>= 1;
        }
    }
    (A *= C) %= MOD;
    (B *= C) %= MOD;
    vector<unsigned long> ifr(N);
    ifr[0] = ifr[1] = 1;
    for(unsigned long i = 2; i < N; ++i)ifr[i] = (MOD - MOD / i) * ifr[MOD % i] % MOD;
