    for(unsigned long i = 0, a = C * N, bin = 1; i < N; ++i){
        (ansA += a * bin % MOD * Ap) %= MOD;
        (ansB += a * bin % MOD * Bp) %= MOD;
        (a += C) %= MOD;
        (Ap *= A) %= MOD;
        (Bp *= B) %= MOD;
        (bin *= (N + i) * ifr[i + 1] % MOD) %= MOD;
    }
    cout << (ansA * Bp + ansB * Ap) % MOD << endl;
