const int MOD = 1000000007,MAX_N = 500000;
vector<ll> an(MAX_N), bn(MAX_N), bunbo(MAX_N), comb(MAX_N);

ll fastpow(ll a, ll pw) {
	ll res = 1;
	while (pw) {
		if (pw & 1) res = res * a % MOD;
		a = a * a % MOD;
		pw >>= 1;
	}
	return res;
}

void makevec(ll a,ll n, vector<ll> &vec){
    ll temp = 1;
    rep(i,n*2+10){
        vec.at(i) = temp;
        (temp *= a)%=MOD;
    }
    return;
}
void makecomb(ll n, vector<ll> &vec){
    ll temp = 1;
    //comb.at(i)が(i-1)C(N-1)になるので、iはNから2N-1
    //つまりi=M
    reps(i,n,n*2){
        vec.at(i) = temp;
        (temp *= i)%=MOD;
        (temp *= fastpow(i-n+1,MOD-2))%=MOD;
    }
    return;
}
