const ll MOD = (ll)1e9 + 7;
using mll = ModLL<MOD>;

int main_C() {
    std::cin.tie(0);
    ios::sync_with_stdio(false);

    ll N, A, B, C; std::cin >> N >> A >> B >> C;

    ModCombination comb(2 * N, MOD);

    mll pt = mll(A) / mll(A+B);
    mll pa = mll(B) / mll(A+B);

    mll ans = mll(0);
    FOR(i,N,2*N) {
        // Σ M-1CN-1 {pt^N pa^(M-N) + pt^(M-N) pa^N} 100M/(A+B)
        mll t = mll(1);
        mll cmb = comb.C(i - 1, N - 1);
        mll pow = (pt.pow(N)*pa.pow(i-N) + pt.pow(i-N)*pa.pow(N));
        t *= cmb;
        t *= pow;
        t *= mll(100);
        t *= mll(i);
        t /= mll(A + B);
        ans += t;
    }

    cout << ans << endl;

    return 0;
}

