const ll mod=1e9+7;
ll fac[200005];
ll multi(ll a,ll b){
	ll ans=0;
	while(b){
		if(b&1)
			ans=(ans+a)%mod;
		a=(a<<1)%mod;
		b>>=1;
	}
	return ans;
}
ll qpow(ll a,ll b){
	ll ans=1;
	while(b){
		if(b&1)
			ans=multi(ans,a);
		a=multi(a,a);
		b>>=1;
	}
	return ans;
}
ll inv(ll a){//mod为素数
	return qpow(a,mod-2);
}
ll C(ll n,ll m){
	return fac[n]*inv(fac[m])%mod*inv(fac[n-m])%mod;
}
