constexpr ll MOD = (ll)((1E+9)+7);

class Modulo{
  private:
    ll MAX = 200000;
    vll fac_v, finv_v, inv_v;
  public:

    void Modulo_setting(ll MAX_){
      MAX = MAX_;

      fac_v.resize(MAX);
      finv_v.resize(MAX);
      inv_v.resize(MAX);

      fac_v[0] = fac_v[1] = 1;
      finv_v[0] = finv_v[1] = 1;
      inv_v[1] = 1;
      for(int i=2; i<=MAX; ++i){
        //i!
        fac_v[i] = (fac_v[i-1]*i)%MOD;
        //i^{-1}
        inv_v[i] = (MOD-(inv_v[MOD%i]*(MOD/i))%MOD)%MOD;
        //(i!)^{-1}
        finv_v[i] = (finv_v[i-1]*inv_v[i])%MOD;
      }
    };

    Modulo(ll MAX_){
      Modulo_setting(MAX_);
      return;
    };

    Modulo(void){
      Modulo_setting(MOD);
      return;
    };

    ~Modulo(void){
      return;
    };

    ll inv(ll n){
      if(n<0 || n>MAX){
        fprintf(stderr, "n range error\n");
        exit(0);
      }
      return inv_v[n];
    };

    ll fac(ll n){
      if(n<0 || n>MAX){
        fprintf(stderr, "n range error\n");
        exit(0);
      }
      return fac_v[n];
    };

    ll inv_fac(ll n){
      if(n<0 || n>MAX){
        fprintf(stderr, "n range error\n");
        exit(0);
      }
      return finv_v[n];
    };

    ll Comb(ll n, ll k){
      if(n<k) return 0;
      if(n<0 || k<0) return 0;
      return (fac_v[n]*((finv_v[k]*finv_v[n-k])%MOD))%MOD;
    };

};

// TakがN回勝って終わる期待値
// N A^(N-1)*A + NC1 (N+1) A^(N-1)B^1 * A + (N+1)C2 (N+2) A^(N-1)B^2 * A + ... + (2N-2)C(N-1) (2N-1) A^(N-1)B^(N-1) * A
// = A^N (N + (N+1) NC1 B + (N+2) (N+1)C2 B^2 + ... + (2N-1) (2N-2)C(N-1) B^(N-1))
// = A^N (N + (N+1)C2 2B + (N+2)C3 3B^2 + ... + (2N-1)CN NB^(N-1)
//

ll N, A, B, C;
Modulo que(200000);
vll dpA, dpB;

ll calc(void){
  ll ans = 0;
  REP(i,N){
    ans += (((N+i)* que.Comb(N-1+i, i))%MOD) * ((dpA[N] * dpB[i])%MOD + (dpB[N] * dpA[i])%MOD);
    ans %= MOD;
  }
  return ans;
}

ll calc_inv(ll x){
  if(x==1) return (ll)1;
  return (MOD-(calc_inv(MOD%x)*(MOD/x))%MOD)%MOD;
}

