  IN(N,A,B,C);

  ll inv_100 = que.inv(100);
  A = (A*inv_100)%MOD;
  B = (B*inv_100)%MOD;
  ll inv = calc_inv((A+B)%MOD);

   A = (A*inv)%MOD;
   B = (B*inv)%MOD;

  dpA.resize(N+1, 1);
  dpB.resize(N+1, 1);
  REP(i,N){
    dpA[i+1] = (dpA[i]*A)%MOD;
    dpB[i+1] = (dpB[i]*B)%MOD;
  }

  ll ans = calc();
  ans *= inv;
  ans %= MOD;


  OUT(ans);

  return 0;
}

