ll fac[MX], faci[MX];

void init()
{
	fac[0] = 1;
	for(int i=1; i<MX; i++) fac[i] = fac[i-1] * i % MOD;
	faci[MX-1] = inv(fac[MX-1]);
	for(int i=MX-1; i>=1; i--) faci[i-1] = faci[i] * i % MOD;
}

ll C(int x, int y)
{
	return fac[x] * faci[y] % MOD * faci[x-y] % MOD;
}

