int fac[MAX], finv[MAX], inv[MAX];


void COMinit() {
 fac[0] = fac[1] = 1;
 finv[0] = finv[1] = 1;
 inv[1] = 1;
  for (int i = 2; i < MAX; i++){
  fac[i] = fac[i - 1] * i % MOD;
  inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
       finv[i] = finv[i - 1] * inv[i] % MOD;
        }
      }

   int COM(int n, int k){
  if (n < k){ return 0;}
  if (n < 0 || k < 0) {return 0;}
     return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
     }

int memo[MAX];

int fra(int a){ // a! % MODを返す
  // いちいち計算し直すのは大変なのでメモしておこう
  if( memo[a] != -1 ){ return memo[a];}

  return memo[a] = ( fra(a-1)*a ) % MOD;
}

int powe(int a, int b){ // a^b%MODを返す

  if( b == 0 ){ return 1LL;}
  else if( b == 1 ){ return a%MOD;}

  if( b % 2 == 0 ){ return ( powe(a,b/2)*powe(a,b/2) ) % MOD;}
  else{
    return ( ( ( powe(a,(b-1)/2 )*powe( a,(b-1)/2 ) )%MOD )*a )%MOD;
  }
}



