template<typename T, long long modulus=1000000007>
class ModInt {
    private:
        T value_;
    public:
        ModInt() {}
        ModInt(const T& _value) {
            value_ = _value % modulus;
        }
        ModInt(const ModInt& x) {
            value_ = x.value_;
        }
        T getValue() const {
            return value_;
        }
        ModInt& operator=(const ModInt& x) {
            value_ = x.value_;
            return *this;
        }
        ModInt& operator+=(const ModInt& x)  {
            value_ += x.value_;
            if (value_ >= modulus) value_ -= modulus;
            return *this;
        }
        ModInt& operator-=(const ModInt& x) {
            if (value_ < x.value_) value_ += modulus;
            value_ -= x.value_;
            return *this;
        }
        ModInt& operator*=(const ModInt& x) {
            value_ = (value_ * x.value_) % modulus;
            return *this;
        }
        ModInt& operator/=(const ModInt& x) {
            T now_value = x.value_;
            long long cnt = modulus - 2;
            while (cnt > 0) {
                if (cnt & 1) {
                    value_ = (value_ * now_value) % modulus;
                }
                now_value = (now_value * now_value) % modulus;
                cnt /= 2;
            }
            return *this;
        }
        const ModInt operator+(const ModInt& x) const {
            return ModInt(*this) += x;
        }
        const ModInt operator-(const ModInt& x) const {
            return ModInt(*this) -= x;
        }
        const ModInt operator*(const ModInt& x) const {
            return ModInt(*this) *= x;
        }
        const ModInt operator/(const ModInt& x) const {
            return ModInt(*this) /= x;
        }
        ModInt operator++(int) {
            ModInt tmp(*this);
            value_ = (value_ + 1 == modulus ? 0 : value_ + 1);
            return tmp;
        }
        ModInt operator--(int) {
            ModInt tmp(*this);
            value_ = (value_ - 1 < 0 ? modulus - 1 : value_ - 1);
            return tmp;
        }
        friend std::istream& operator>>(std::istream& stream, ModInt& x) {
            stream >> x.value_;
            x.value_ %= modulus;
            return stream;
        }
        friend std::ostream& operator<<(std::ostream& stream, const ModInt& x) {
            stream << x.value_;
            return stream;
        }
};

template<typename T>
class Combination {
    private:
        T mod;
        vector<T> factorial, inv_factorial, inv;
    public:
        Combination(int max_number, T _mod):
        mod(_mod), factorial(max_number + 1), inv_factorial(max_number + 1), inv(max_number + 1) {
            factorial[0] = factorial[1] = 1;
            inv_factorial[0] = inv_factorial[1] = 1;
            inv[1] = 1;
            for (int i = 2; i <= max_number; i++) {
                factorial[i] = (factorial[i - 1] * i) % mod;
                inv[i] = mod - inv[mod % i] * (mod / i) % mod;
                inv_factorial[i] = inv_factorial[i - 1] * inv[i] % mod;
            }
        }
        T calc(int n, int k) {
            if (n < k) return 0;
            if (n < 0 || k < 0) return 0;
            return factorial[n] * (inv_factorial[k] * inv_factorial[n - k] % mod) % mod;
        }
};

