      ans += comb(n-1, N-1) * (
            (GF(A)/GF(A+B)).power(N) * (GF(B)/GF(A+B)).power(n-N) +
            (GF(A)/GF(A+B)).power(n-N) * (GF(B)/GF(A+B)).power(N));
   }
   cout << ans << endl;

   return 0;
}

