    return Modint(MOD - val);
  }

  Modint operator- (Modint other) const {
    return Modint(val + MOD - other.val);
  }

  void operator-= (Modint other) {
    val += MOD - other.val;
    val %= MOD;
  }

  Modint operator* (Modint other) const {
    return Modint(val * other.val);
  }

  void operator*= (Modint other) {
    val *= other.val;
    val %= MOD;
  }

  bool operator== (Modint other) const {
    return val == other.val;
  }

  bool operator!= (Modint other) const {
    return val != other.val;
  }
};

Modint exp (Modint a, int k) {
  if (k == 0) {
    return Modint(1);
  } else if (k % 2 == 0) {
    Modint half = exp(a, k / 2);
    return half * half;
  } else {
    return a * exp(a, k - 1);
  }
}

Modint inv (Modint a) {
  return exp(a, MOD - 2);
}

ostream& operator<< (ostream& out, Modint p) {
  out << p.val;
  return out;
}

const int MAX_N = 2e5 + 5;

Modint fact [MAX_N];
Modint ifact [MAX_N];

Modint choose (int n, int r) {
  return fact[n] * ifact[r] * ifact[n - r];
}

int n;
Modint a, b, c;
Modint ans;

Modint expa [MAX_N];
Modint expb [MAX_N];

Modint ic;

Modint sprob;

void consider (int ca, int cb) {
  Modint prob;
  int steps = ca + cb;
  if (ca == n) {
    prob = choose(steps - 1, ca - 1) * expa[ca] * expb[cb];
  } else {
    // assume cb == n
    prob = choose(steps - 1, cb - 1) * expa[ca] * expb[cb];
  }

  sprob += prob;
  // cerr << ca << " " << cb << " " << prob << " " << Modint(steps) + Modint(steps) * ic << endl;
  ans += prob * (Modint(steps) + Modint(steps) * c * ic);
}

