class Combination{
public:
    ll N;
    ll mod;
    vector<ll> fact;

    Combination(ll n, ll m) : N(n), mod(m), fact(n+1){
        fact.at(0) = 1;
        for(ll i=1; i<=N; i++){
            fact.at(i) = i * fact.at(i-1) % mod;
        }
    }

    ll POW(ll a, ll b){
        ll res = 1;
        while(b > 0){
            if(b & 1){
                res = res * a % mod;
            }
            a = a * a % mod;
            b >>= 1;
        }
        return res;
    }

    ll combin(ll n, ll k){
        if(n < 0 || k < 0 || n < k){
            return 1;
        }
        return fact.at(n) * POW(fact.at(k) * fact.at(n-k) % mod, mod - 2) % mod;
    }
};

signed main(){
    ll n, a, b, c;
    cin >> n >> a >> b >> c;

    Combination C(2*n, MOD);

    vector<ll> powa(2*n+1, 1), powb(2*n+1, 1), powc(2*n+1, 1), pow100(2*n+1, 1);
    REP(i, 2*n){
        powa[i+1] = powa[i] * a % MOD;
        powb[i+1] = powb[i] * b % MOD;
        powc[i+1] = powc[i] * (100 - c) % MOD;
        pow100[i+1] = pow100[i] * 100 % MOD;
    }

    ll ans = 0;

    FOR(i, n, 2*n){
        ll x = C.combin(i-1, n-1) * ((powa[n]*powb[i-n]%MOD + powa[i-n]*powb[n]%MOD) % MOD) % MOD;
        x = (x * i * 100) % MOD;
        x *= C.POW(powc[i+1], MOD-2);
        x %= MOD;
        ans = (ans + x) % MOD;
    }

    cout << ans << endl;

    return 0;
}

