template <ULL mod> class modint {
public:
	ULL v;
	modint(const LL x = 0) : v((x% mod + mod) % mod) {}
	modint operator+(const modint rhs) { return modint(*this) += rhs; }
	modint operator-(const modint rhs) { return modint(*this) -= rhs; }
	modint operator*(const modint rhs) { return modint(*this) *= rhs; }
	modint operator/(const modint rhs) { return modint(*this) /= rhs; }
	modint operator-() {return modint(mod-v);}
	modint& operator+=(const modint rhs) {
		v += rhs.v;
		if (v >= mod)v -= mod;
		return *this;
	}
	modint& operator-=(const modint rhs) {
		if (v < rhs.v)v += mod;
		v -= rhs.v;
		return *this;
	}
	modint& operator*=(const modint rhs) {
		v = v * rhs.v % mod;
		return *this;
	}
	modint inverse(modint a) {
		ULL exp = mod - 2;
		modint ret(1ULL);
		while (exp) {
			if (exp % 2) {
				ret *= a;
			}
			a *= a;
			exp >>= 1;
		}
		return ret;
	}
	modint& operator/=(modint rhs) {
		(*this) *= inverse(rhs);
		return *this;
	}
};

using mint = modint<MOD>;

const int MAX = 210000;
mint fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (int i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i;
		inv[i] = - inv[MOD % i] * (MOD / i) + MOD;
		finv[i] = finv[i - 1] * inv[i];
	}
}

mint nCr(int n, int r) {
	if (n < 0 || r < 0 || n - r < 0)return 0;
	return fac[n] * finv[r] * finv[n - r];
}

int main() {
	COMinit();
	int n, a, b, c;
	scanf("%d%d%d%d", &n, &a, &b, &c);
	mint pa = mint(a) / 100, pb = mint(b) / 100, pc = mint(c) / 100;
	mint qa = pa / (pa+pb), qb = pb /( pa + pb);
	vector<mint> pqa(n + 1, 1), pqb(n + 1, 1);
	REP(i, n)pqa[i + 1] = pqa[i] * qa;
	REP(i, n)pqb[i + 1] = pqb[i] * qb;
	mint ans = 0;
	FOR(i, n, 2 * n)ans += nCr(i - 1, n - 1) * (pqa[i - n] * pqb[n] + pqa[n] * pqb[i - n]) * i;
	ans /= - pc + 1;
	printf("%lld\n", ans.v);
	return 0;
}

