    auto ArN = mc.power(Ar, N);
    auto BrN = mc.power(Br, N);
    auto Ari = 1;
    auto Bri = 1;
    vector<ll> combCache(N, -1);
    combCache[0] = 1;
    for(ll i=1;i<N;i++){
        combCache[i] = mc.multi(combCache[i-1], N+i-1);
        combCache[i] = mc.div(combCache[i], i);
    }
    ll res=0;
    for(ll i=0;i<N;i++){
        auto tmpA = (N+i);
        //tmpA = mc.multi(tmpA, mc.comb(N+i-1, i));
        tmpA = mc.multi(tmpA, combCache[i]);
        tmpA = mc.multi(tmpA, ArN);
