        //tmpB = mc.multi(tmpB, mc.power(Ar, i));
        tmpB = mc.multi(tmpB, Ari);
        res += (tmpA+tmpB);
        res %= MOD;

        Ari = mc.multi(Ari, Ar);
        Bri = mc.multi(Bri, Br);
    }
    res = mc.multi(res, 100);
    res = mc.div(res, 100-C);
