LL ch(LL n, LL m){
  return fact[n] * facti[m] % MOD * facti[n-m] % MOD;
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  LL N, A, B, C;
  cin >> N >> A >> B >> C;

  fact[0] = 1;
  facti[0] = 1;
  FOR(i,1,200010){
    fact[i] = fact[i-1] * i % MOD;
    facti[i] = inv(fact[i]);
  }

  LL pc = C * inv(100) % MOD;
  LL pc_ = (100 - C) * inv(100) % MOD;
  LL pa = (A * inv(A + B)) % MOD;
  LL pb = (B * inv(A + B)) % MOD;


  LL ans1 = 0, ans2 = 0;
  LL p = 1;
  for(int i=0;i<N;++i){
    (ans1 += ch(N-1+i, i) * p % MOD * (N+i) % MOD) %= MOD;
    p = p * pa % MOD;
  }
  ans1 = ans1 * powm(pb, N) % MOD;

  p = 1;
  for(int i=0;i<N;++i){
    (ans2 += ch(N-1+i, i) * p % MOD * (N+i) % MOD) %= MOD;
    p = p * pb % MOD;
  }
  ans2 = ans2 * powm(pa, N) % MOD;

  LL ans = (ans1 + ans2) % MOD;

  cout << (ans * inv(pc_) % MOD) << endl;

  return 0;
}

