#define MOD 1000000007
#define SIZE 200005

using namespace std;
typedef long long ll;

ll inv[SIZE], fac[SIZE], finv[SIZE];

void com_init() {
		fac[0] = fac[1] = 1;
		finv[0] = finv[1] = 1;
		inv[1] = 1;

		for (int i = 2; i < SIZE; i++) {
				inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
				fac[i] = fac[i-1] * (ll)i % MOD;
				finv[i] = finv[i-1] * inv[i] % MOD;
		}
}

ll com(int a, int b) {
		if (a < b) return 0;
		return fac[a] * (finv[b] * finv[a-b] % MOD) % MOD;
}

ll mpow(ll x, ll t) {
		if (t == 0) return 1;
		ll ret = mpow(x, t/2);
		ret = ret * ret % MOD;
		if(t%2==1) ret = ret * x % MOD;

		return ret;
}

int main() {
		com_init();
		int n, A, B, DC;
		scanf("%d %d %d %d", &n, &A, &B, &DC);
		ll pa = (ll)A * inv[A+B] % MOD;
		ll pb = (ll)B * inv[A+B] % MOD;
		ll ret = 0;

		for (int k = 0; k < n; k++) {
				ret += com(k+n-1, k) * mpow(pb, k) % MOD * mpow(pa, n) % MOD * (ll)(k+n) % MOD;
				ret += com(k+n-1, k) * mpow(pa, k) % MOD * mpow(pb, n) % MOD * (ll)(k+n) % MOD;
				ret %= MOD;
		}

		ret = ret * inv[A+B] % MOD * 100LL % MOD;
		printf("%lld\n", ret);

		return 0;
}

