  fac_b[0] = 1;

  const auto av_inv = modinv(a + b, mod);
  for (int64_t i = 1; i <= n; i++) {
    fac_a[i] = (fac_a[i - 1] * a % mod) * av_inv;
    fac_a[i] %= mod;
    fac_b[i] = (fac_b[i - 1] * b % mod) * av_inv;
    fac_b[i] %= mod;
  }

  const int64_t c_r = ((c * modinv(100 - c, mod)) % mod + 1) % mod;
  combination(2 * n - 1, 1, mod);

  int64_t a_v = 0;
  for (int64_t i = 0; i < n; i++) {
    int64_t tmp =
        fac_b[i] * combination(n + i - 1, i, mod) % mod * (n + i) % mod * c_r;
    tmp %= mod;
    a_v += tmp;
    a_v %= mod;
  }

  int64_t b_v = 0;
  for (int64_t i = 0; i < n; i++) {
    int64_t tmp =
        fac_a[i] * combination(n + i - 1, i, mod) % mod * (n + i) % mod * c_r;
    tmp %= mod;
    b_v += tmp;
    b_v %= mod;
  }

  int64_t ans = (a_v * fac_a[n] % mod) + (b_v * fac_b[n] % mod);
  ans %= mod;
  std::cout << ans << std::endl;

  return 0;
}

