ll pw[3][MAXN];

ll inv(ll x) {
	ll ret = 1;
	for(int p = P - 2; p; p >>= 1) {
		if(p & 1) {
			ret *= x;
			ret %= P;
		}
		x *= x;
		x %= P;
	}
	if(ret < 0) ret += P;
	return ret;
}

int main() {
	ios_base::sync_with_stdio(0);

	cin >> n;
	cin >> a >> b >> c;

	A = a * inv(100) % P;
	B = b * inv(100) % P;
	c *= inv(100);
	c %= P;

	ll ans = 0;

	ll cnk = 1;

	pw[0][0] = pw[1][0] = pw[2][0] = 1;
	for(int i = 1; i < 2*n; i++) {
		pw[0][i] = (pw[0][i-1] * A) % P;
		pw[1][i] = (pw[1][i-1] * B) % P;
		pw[2][i] = (pw[2][i-1] * (A+B)) % P;
	}

	for(int m = n; m < 2*n; m++) {
		ll add = m * inv(1 - c);
		add %= P;

		ll prob = (cnk * inv(pw[2][m])) % P;
		ll s1 = ((pw[0][n-1] * pw[1][m-n]) % P * A) % P;
		ll s2 = ((pw[1][n-1] * pw[0][m-n]) % P * B) % P;
		prob *= (s1 + s2) % P;
		prob %= P;
		ans += (prob * add) % P;
		ans %= P;

		cnk *= m;
		cnk %= P;
		cnk *= inv(m+1-n);
		cnk %= P;
	}

