// nCrで用いる
vector<mint> fact, factinv;
// nCrで用いる 予め計算しておく
void nCr_compute_factinv(int N) {
	N = min(N, mint::Mod - 1);
	fact.resize(N + 1);
	factinv.resize(N + 1);
	fact[0] = 1;
	rep(i, 1, N + 1) fact[i] = fact[i - 1] * i;
	factinv[N] = fact[N].inverse();
	for (int i = N; i >= 1; i--)
		factinv[i - 1] = factinv[i] * i;
}
mint nCr(int n, int r) {
	if (n >= mint::Mod)
		return nCr(n % mint::Mod, r % mint::Mod) *
		nCr(n / mint::Mod, r / mint::Mod);
	return r > n ? 0 : fact[n] * factinv[n - r] * factinv[r];
}

mint nHr(int n, int r) { return r == 0 ? 1 : nCr(n + r - 1, r); }

mint solve(int N, int A, int B, int C) {
	mint a = mint(A) / mint(A+B);
	mint b = mint(B) / mint(A+B);
	mint c = mint(C) / mint(100);
	mint ans = 0;

	auto X = [&](int M)->mint {
		return (pow(a, N)*pow(b, M - N) + pow(b, N)*pow(a, M - N))*nCr(M - 1, N - 1);
	};
	auto Y = [&](int M)->mint {
		return mint(100) / mint(100 - C)*M;
	};

	rep(M, N, 2 * N) {
		ans += X(M)*Y(M);
	}

	return ans;
}


signed main(signed argc, char *argv[]) {
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout << fixed << setprecision(12);

	int N; cin >> N;
	nCr_compute_factinv(3 * N);
	int A, B, C; cin >> A >> B >> C;

	cout << solve(N, A, B, C) << endl;


	return 0;
}

