template <typename T>
T mypow(T a, T b)
{
    if (b == 0)
        return 1;
    T tmp = mypow(a, b / 2);
    if (b % 2)
        return (((tmp * tmp) % MOD) * a) % MOD;
    else
        return (tmp * tmp) % MOD;
}

vector<ll> fact(200010, 1), inv(200010, 1);

ll comb(int n, int r)
{
    if (r < 0 || n < r)
        return 0;
    ll ret = fact[n] * inv[r] % MOD;
    ret = ret * inv[n - r] % MOD;
    return ret;
}

