	fact[0] = 1; aa[0] = 1; bb[0] = 1; f100[0] = 1;
	a2 = division(a, a + b, MOD);
	a2 = (a2 * 100) % MOD;
	b2 = division(b, a + b, MOD);
	b2 = (b2 * 100) % MOD;

	for (i = 1; i < nn; i++) {
		fact[i] = (fact[i - 1] * i) % MOD;
		aa[i] = (aa[i - 1] * a2) % MOD;
		bb[i] = (bb[i - 1] * b2) % MOD;
		f100[i] = (f100[i - 1] * 100) % MOD;
	}

	p = 0; q = 1;
	for (m = n; m < nn; m++) {
		pp = (fact[m - 1] * m) % MOD;
		x = (aa[n] * bb[m - n] + aa[m - n] * bb[n]) % MOD;
		pp = (pp * x) % MOD;

		qq = (fact[n - 1] * fact[m - 1 - (n - 1)]) % MOD;
		x = (f100[m - 1] * (100 - c)) % MOD;
		qq = (qq * x) % MOD;

		newp = (p * qq + pp * q) % MOD;
		newq = (q * qq) % MOD;

		p = newp;
		q = newq;
	}

	g = gcd(p, q);
	p /= g;
	q /= g;

	ans = division(p, q, MOD);

