ModInt<MOD> solve() {
  Combination comb;
  ModInt<MOD> ans = 0, hand = 100, ab = a + b;
  dp.assign(2 * n + 1, 0);
  for(int i = 1; i < 2 * n; ++i)
    dp[i] = dp[i - 1] + hand / ab;
  a /= ab;
  b /= ab;
  for(int i = 0; i < n; ++i)
    ans += comb.C(n + i - 1, n - 1) * dp[n + i] *
           (a.pow(n) * b.pow(i) + a.pow(i) * b.pow(n));
  return ans;
}

