lint power(lint n, lint p) {
    lint res = 1;
    while (p > 0) {
        if (p % 2 == 1) {
            res = res * n % MOD;
        }
        n = n * n % MOD;
        p /= 2;
    }
    return res;
}

lint minv(lint n) {
    return power(n, MOD - 2);
}

