		ll tmp2 = n + x;
		ll tmp3 = modpow(A, x) * modpow(B, n) % mod;
		ll tmp4 = modpow(B, x) * modpow(A, n) % mod;
		ll tmp = tmp1 * ((tmp3 + tmp4) % mod) % mod * tmp2 % mod;
		res += tmp;
		res %= mod;
	}
	res *= 100 * inverse(100 - c) % mod;
	res %= mod;
	cout << res << endl;
	return 0;
}

