        ab_c[i] = (ab_c[i - 1] + invMod(p_ab)) % MOD;
        an[i] = an[i - 1] * a % MOD;
        bn[i] = bn[i - 1] * b % MOD;
        abn[i] = abn[i - 1] * (a + b) % MOD;
    }

    li res = 0;
    rep(i, n) {
        // どちらかがn回勝つまでにもう片方がi回勝つ場合
        li bunbo = abn[n + i];
        li bunshi = ((an[n] * bn[i] % MOD + an[i] * bn[n] % MOD) % MOD) * combi(n + i - 1, i) % MOD;
        li now = bunshi * invMod(bunbo) % MOD;
        res = (res + (ab_c[n + i] * now)) % MOD;
        if (res < 0) {
            p3(i, now, ab_c[n + i]);
        }
    }
    cout << res << endl;

    return 0;
}

