class frac
{
    long long a;
    long long b;

    void set_value(const long long x, const long long y)
    {
        // assert(y > 0);
        this->a = x;
        this->b = y;
        if (x != 0)
        {
            reduction();
        }
    }

    long long calcGCD(long long x, long long y)
    {
        if (x < y)
        {
            swap(x, y);
        }
        long long remain = x % y;
        while (remain != 0)
        {
            x = y;
            y = remain;
            remain = x % y;
        }
        return y;
    }

public:
    frac()
    {
        set_value(0ll, 1ll);
    }

    template <typename T>
    frac(T x)
    {
        set_value((long long)x, 1ll);
    }

    template <typename T, typename U>
    frac(T x, U y)
    {
        set_value((long long)x, (long long)y);
    }

    void reduction()
    {
        long long gcd = calcGCD(this->a, this->b);
        this->a /= gcd;
        this->b /= gcd;
    }

    friend istream &operator>>(istream &is, frac &x)
    {
        long long tmp;
        is >> tmp;
        x.set_value(tmp, 1);
        return is;
    }

    friend ostream &operator<<(ostream &os, const frac &x)
    {
        os << x.a << "/" << x.b;
        return os;
    }

    long long numerator() const
    {
        return this->a;
    }

    long long denominator() const
    {
        return this->b;
    }

    template <typename T>
    frac &operator=(const T x)
    {
        set_value((long long)x, 1ll);
        return *this;
    }

    frac &operator+=(const frac x)
    {
        this->a *= x.b;
        this->a += x.a * this->b;
        this->b *= x.b;
        return *this;
    }

    frac &operator-=(const frac x)
    {
        this->a *= x.b;
        this->a -= x.a * this->b;
        this->b *= x.b;
        return *this;
    }

    frac &operator*=(const frac x)
    {
        this->a *= x.a;
        this->b *= x.b;
        return *this;
    }

    frac &operator/=(const frac x)
    {
        this->a *= x.b;
        this->b *= x.a;
        return *this;
    }

    frac operator+(const frac x)
    {
        return frac(*this) += x;
    }

    frac operator-(const frac x)
    {
        return frac(*this) -= x;
    }

    frac operator*(const frac x)
    {
        return frac(*this) *= x;
    }

    frac operator/(const frac x)
    {
        return frac(*this) /= x;
    }
};

template <long long mod>
class Mod
{
    long long value;
    void set_value(const long long x)
    {
        this->value = x % mod;
    }

public:
    Mod()
    {
        set_value(0ll);
    }

    template <typename T>
    Mod(T x = 0)
    {
        set_value((long long)x);
    }

    friend istream &operator>>(istream &is, Mod &x)
    {
        long long tmp;
        is >> tmp;
        x.set_value(tmp);
        return is;
    }

    friend ostream &operator<<(ostream &os, const Mod &x)
    {
        os << x.value;
        return os;
    }

    operator long long() const
    {
        return this->value;
    }

    template <typename T>
    bool operator<(const T x)
    {
        return this->value < (long long)x;
    }

    template <typename T>
    bool operator<=(const T x)
    {
        return this->value <= (long long)x;
    }

    template <typename T>
    bool operator>(const T x)
    {
        return this->value > (long long)x;
    }

    template <typename T>
    bool operator>=(const T x)
    {
        return this->value >= (long long)x;
    }

    template <typename T>
    bool operator==(const T x)
    {
        return this->value == (long long)x;
    }

    template <typename T>
    Mod &operator=(const T x)
    {
        set_value((long long)x);
        return *this;
    }

    template <typename T>
    Mod &operator&=(const T x)
    {
        set_value(this->value & (long long)x);
        return *this;
    }

    template <typename T>
    Mod &operator|=(const T x)
    {
        set_value(this->value | (long long)x);
        return *this;
    }

    template <typename T>
    Mod &operator^=(const T x)
    {
        set_value(this->value ^ (long long)x);
        return *this;
    }

    template <typename T>
    Mod &operator<<=(const T x)
    {
        set_value(this->value << (long long)x);
        return *this;
    }

    template <typename T>
    Mod &operator>>=(const T x)
    {
        set_value(this->value >> (long long)x);
        return *this;
    }

    template <typename T>
    Mod &operator+=(const T x)
    {
        set_value(this->value + (long long)x);
        return *this;
    }

    template <typename T>
    Mod &operator-=(const T x)
    {
        set_value(this->value - (long long)x);
        return *this;
    }

    template <typename T>
    Mod &operator*=(const T x)
    {
        set_value(this->value * (long long)x);
        return *this;
    }

    template <typename T>
    Mod &operator/=(const T x)
    {
        long long a = (long long)x;
        long long b = mod;
        long long u = 1;
        long long v = 0;
        while (b)
        {
            long long t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        u %= mod;
        if (u < 0)
            u += mod;
        *this *= Mod(u);
        return *this;
    }

    template <typename T>
    Mod operator&(const T x) const
    {
        return Mod(*this) &= x;
    }

    template <typename T>
    Mod operator|(const T x) const
    {
        return Mod(*this) |= x;
    }

    template <typename T>
    Mod operator^(const T x) const
    {
        return Mod(*this) ^= x;
    }

    template <typename T>
    Mod operator<<(const T x) const
    {
        return Mod(*this) <<= x;
    }

    template <typename T>
    Mod operator>>(const T x) const
    {
        return Mod(*this) >>= x;
    }

    template <typename T>
    Mod operator+(const T x) const
    {
        return Mod(*this) += x;
    }

    template <typename T>
    Mod operator-(const T x) const
    {
        return Mod(*this) -= x;
    }

    template <typename T>
    Mod operator*(const T x) const
    {
        return Mod(*this) *= x;
    }

    template <typename T>
    Mod operator/(const T x) const
    {
        return Mod(*this) /= x;
    }

    Mod &operator++()
    {
        *this += 1;
        return *this;
    }

    Mod &operator--()
    {
        *this -= 1;
        return *this;
    }

    Mod operator++(auto)
    {
        Mod ret(*this);
        ++*this;
        return ret;
    }

    Mod operator--(auto)
    {
        Mod ret(*this);
        --*this;
        return ret;
    }
};

template <typename T, typename U>
T power(T x, U y)
{
    T ret(1);
    while (y > 0)
    {
        if ((y & 1) > 0)
        {
            ret *= x;
        }
        x *= x;
        y >>= 1;
    }
    return ret;
}

