{
    long long N, A, B, C;
    cin >> N >> A >> B >> C;

    vector<long long> dp(N, 1);
    for (long long i = 1; i < N; i++)
    {
        dp[i] = dp[i - 1] * (N - 1 + i) / i;
        dp[i] %= MOD;
    }

    frac ans(0);
    frac a = power(frac(A, A + B), N);
    frac b = power(frac(B, A + B), N);
    frac current_a(1);
    frac current_b(1);
    for (long long i = 0; i < N; i++)
    {
        ans += frac(dp[i]) * frac(N + i) * a * current_b;
        ans += frac(dp[i]) * frac(N + i) * b * current_a;
        current_a *= frac(A, A + B);
        current_b *= frac(B, A + B);
    }
    if (C != 0)
    {
        ans *= frac(100, C);
    }
    ans.reduction();
    cout << Mod<MOD>(ans.numerator()) / ans.denominator() << endl;
}

