    for(int a = 0; a < N; a++) {
        ll sum = a + N-1;
        ll now = combination(sum, a) * (a + N) % mod;
        //cerr << now << endl;
        now *= beki(Awin, a);
        now %= mod;
        now *= beki(Bwin, N - 1);
        now %= mod;
        now *= Bwin % mod;
        now %= mod;
        //cerr << a << " " << now << " " << (double)now / mod << endl;
        ans += now;
        ans %= mod;
    }
    cerr << beki(inv[2], 4) << endl;
    for(int a = 0; a < N; a++) {
        ll sum = a + N-1;
        ll now = combination(sum, a) * (a + N) % mod;
        now *= beki(Bwin, a);
        now %= mod;
        now *= beki(Awin, N - 1);
        now %= mod;
        now *= Awin % mod;
        ans += now;
        ans %= mod;
    }
    cout << ans * factor % mod << endl;
    return 0;
}

