void solve(long long N, long long A, long long B, long long C)
{
  mint p = mint(100) / (100 - C);
  mint q = mint(A) / (100 - C);
  mint r = mint(B) / (100 - C);
  // a_N,N -> a_0,i
  mint ans = 0;
  for (int i = 1; i <= N; i++)
  {
    lli x = 1;
    lli y = i;
    lli dx = N - x;
    lli dy = N - y;
    lli dist = dx + dy;
    ans += q * binom(dist, dx) * q.pow(dx) * r.pow(dy) * mint(p) * (dist + 1);
  }
  for (int i = 1; i <= N; i++)
  {
    lli x = i;
    lli y = 1;
    lli dx = N - x;
    lli dy = N - y;
    lli dist = dx + dy;
    ans += r * binom(dist, dx) * q.pow(dx) * r.pow(dy) * mint(p) * (dist + 1);
  }
  cout << ans << endl;
}

