vector<ll> getp(ll n) {

	vector<ll> res;
	ll a = 2;
	if (n % 2 == 0) {
		res.push_back(2);
		while (n % 2 == 0)n /= 2;
	}

	for (ll i = 3; i * i <= n; i += 2)
	{
		if (n % i == 0) {
			res.push_back(i);
			while (n % i == 0)n /= i;
		}
	}
	if (n != 1) res.push_back(n);
	return res;
}
vector<ll> getDivisors(ll n) {

	vector<ll> res;
	ll a = 2;
	res.push_back(1);
	for (ll i = 2; i * i <= n; i++)
	{

		if (n % i == 0) {
			res.push_back(i);
			if(n / i != i)
				res.push_back(n / i);
		}
	}
	return res;
}

void solv() {

	ll a, b, c;
	cin >> n >> a >> b >> c;

	ll res = 0;

	// X(M)=com(m-1,n-1)*((a/100)^n*(b/100)^(m-n)+(a/100)^(m-n)*(b/100)^n)
	// Y(M)=M(100/(100-c))
	ll yi = 100 * inv[100 - c];
	yi %= INF;
	a = a * inv[100 - c]; a %= INF;
	b = b * inv[100 - c]; b %= INF;
	ll ya[100010], yb[100010];
	memset(ya, 0, sizeof(ya));
	ya[0] = 1;
	memset(yb,0, sizeof(yb));
	yb[0] = 1;
	for (size_t i = 1; i <= n; i++)
	{
		ya[i] = (a * ya[i - 1]) % INF;
		yb[i] = (b * yb[i - 1]) % INF;
	}

	for (ll m = n; m < 2 * n; m++)
	{
		ll v = COM(m - 1, n - 1);
		v *= m; v %= INF;
		v *= (((ya[n] * yb[m - n]) % INF + (ya[m - n] * yb[n]) % INF)) % INF;
		v %= INF;
		res += v;
		res %= INF;
	}

	cout << (res* yi) % INF << endl;
}

