        ihun[i] = (ihun[i - 1] * tmp) % mod;
        fac[i] = (i * fac[i - 1]) % mod;
    }
    invfac[N - 1] = po(fac[N-1] , mod - 2);
    for(int i = N - 2 ; i >= 0 ; --i){
        invfac[i] = (invfac[i + 1] * (i + 1)) % mod ;
    }
}

int ncr(int n , int r){
    if(r > n) return 0; 
    int res = (fac[n] * invfac[r]) % mod ;
    res = (res * invfac[n - r]) % mod ;
