		FORE(total,need,2*need-1) {
			//printf("rep=%d, total=%d: %d*%d*%d*%d\n",rep,total,choose(total-1,need-1),Apw[need],Bpw[total-need],dp[total]);
			int cur=(ll)choose(total-1,need-1)*Apw[need]%MOD*Bpw[total-need]%MOD*dp[total]%MOD;
			ret=(ret+cur)%MOD;
		}
		swap(a,b);
	}
	return ret;
}

void run() {
	scanf("%d%d%d%d",&need,&a,&b,&c);
	printf("%d\n",solve());
}

int main() {
	run();
	return 0;
}

