/*
 * 引き分けが存在しない場合(C = 0)を考える.
 * 高橋くんが勝つには青木くんがk回(0 <= k <= N - 1)勝利, 高橋くんがN-1回勝利
 * した状態で高橋くんが勝てば良い. 勝負が行われる回数の期待値は
 * sum(k from 0 to N - 1) (k + N) * comb(N - 1 + k, k) * (A/100)**(N-1) * (B/100)**k
 * 引き分けが存在する場合を考える.
 * 1回勝負が着くまでの期待値は 100/(100 - C) と書ける.
 * よって上としたの式の積が答え
 * 高橋くんの勝つ確率は A/(A+B), 青木くんが勝つ確率は B/(A+B) とみなす
 *
 * (100)/(100-C) * sum(k from 0 to N - 1) (K + N) * comb(N-1+k,k)
 *   * (A/(A+B)) ** (N-1) * (B/(A+B)) ** k
 */

int powmod(int a, int p, int mod) {
    int ans = 1;
    int mul = a;

    for (; p > 0; p >>= 1, mul = (mul * mul) % mod) {
        if ((p & 1) == 1) ans = (ans * mul) % mod;
    }

    return ans;
}

class Combination {
public:
    int N;
    int mod;
    vector<int> fact;
    vector<int> revFact;

    Combination(int n, int m) : N(n), mod(m), fact(n+1), revFact(n+1) {
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = fact[i-1] * i;
            fact[i] %= mod;
        }

        // Fermat's little theorem
        revFact[N] = powmod(fact[N], mod - 2, MOD);

        for (int i = N-1; i >= 0; i--) {
            revFact[i] = revFact[i+1] * (i+1);
            revFact[i] %= mod;
        }
    }

    int get(int a, int b) {
        if (a < 0 || b < 0) return 0;
        if (b > a) return 0;
        return (((fact[a] * revFact[b]) % mod) * revFact[a-b]) % mod;
    }
};

signed main() {
    int N, A, B, C;
    cin >> N >> A >> B >> C;

    Combination comb = Combination(2 * N, MOD);

    int aab = powmod((A * powmod(A + B, MOD - 2, MOD)) % MOD, N, MOD);
    int bab = powmod((B * powmod(A + B, MOD - 2, MOD)) % MOD, N, MOD);
    int ret = 0;

    for (int k = 0; k < N; k++) {
        int tmp = (aab * powmod((B * powmod(A + B, MOD-2, MOD)) % MOD, k, MOD)) % MOD;
        tmp += (bab * powmod((A * powmod(A + B, MOD-2, MOD)) % MOD, k, MOD)) % MOD;
        tmp %= MOD;
        tmp *= (k + N);
        tmp %= MOD;
        tmp *= comb.get(N-1+k, k);
        tmp %= MOD;

        ret += tmp;
        ret %= MOD;
    }

    ret = (ret * 100) % MOD;
    ret = (ret * powmod(100-C, MOD-2, MOD)) % MOD;

    cout << ret << endl;
    return 0;
}

