constexpr ll MOD = 1000000007ll;


ll myPow(ll x, ll n, ll m) {
	if (n == 0)
		return 1;
	if (n % 2 == 0)
		return myPow(x * x % m, n / 2, m);
	else
		return x * myPow(x, n - 1, m) % m;
}

vec<ll, 1> pari_memo(1000001, -1);

ll parin(ll n)
{
	if (n <= 1) {
		pari_memo[n] = 1;
		return 1;
	}

	if (pari_memo[n] != -1) return pari_memo[n];
	pari_memo[n] = (parin(n - 1) * n) % MOD;
	return pari_memo[n];
}

ll Comb(ll n, ll k)
{
	ll ans = 0;
	ans = parin(n);
	ans = ans * myPow(parin(k), MOD - 2, MOD) % MOD;
	ans = ans * myPow(parin(n - k), MOD - 2, MOD) % MOD;
	return ans;
	return 0;
}



