	}
	ll cur=1;
	for(ll i=0;i<n;i++){
		ll val=a_abn*cnt%MOD;
		val=val*cur%MOD;
		val=val*(n+i)%MOD;
		val=val*mod_comb(n+i-1,i,MOD)%MOD;
		ans+=val;
		ans%=MOD;
		cur=cur*b_ab%MOD;
