long long fexp(long long x, long long e = MOD - 2) {
	long long ans = 1;
	for(; e > 0; e /= 2) {
		if(e & 1) ans = ans * x % MOD;
		x = x * x % MOD;
	}
	return ans;
}

long long fat[ms], ifat[ms];

long long comb(int n, int a) {
	if(a < 0 || a > n) return 0;
	else return fat[n] * ifat[a] % MOD * ifat[n-a] % MOD;
}

int main() {
