	b = b * fexp(100 - c) % MOD;
	long long ans = 0;
	fat[0] = ifat[0] = 1;
	for(int i = 1; i < ms; i++) {
		fat[i] = fat[i-1] * i % MOD;
		ifat[i] = fexp(fat[i]);
