int inv_mod(int a, int m)
{
    int b, x, u, q, abs_m, tmp;

    abs_m = (m < 0) ? -m : m;
    b = m;
    x = 1;
    u = 0;
    while (b > 0)
    {
        q = a / b;
        tmp = u;
        u = x - q * u;
        x = tmp;
        tmp = b;
        b = a - q * b;
        a = tmp;
    }

    return (x < 0) ? abs_m + x : x;
}

