    private long calc(int N, int A, int B, int C) {
        long a = DIV(A, A + B);
        long b = DIV(B, A + B);
        long c = DIV(100, 100 - C);
        long AP = POW(a, N - 1);

        long curB = 1;
        long curC = 1;
        long curD = 1;
        long res = 0;
        for (int i = 0; i <= N - 1; i++) {
            long s = MULT(c, MULT(a, MULT(AP, MULT(curB, curC))));
            res = ADD(res, MULT(i + N, DIV(s, curD)));
            curB = MULT(curB, b);
            curC = MULT(curC, N + i);
            curD = MULT(curD, i + 1);
        }
        return res;
    }

    private double calc2(int N, int A, int B, int C) {
        double a = (double) A / (A + B);
        double b = (double) B / (A + B);
        double c = 100.0 / (100.0 - C);
        double AP = Math.pow(a, N - 1);

        double curB = 1;
        double curC = 1;
        double curD = 1;
        double res = 0;
        for (int i = 0; i <= N - 1; i++) {
            double s = c * curC * a * AP * curB;
            res += ((i + N) * s) / curD;
            curB *= b;
            curC *= (N + i);
            curD *= (i + 1);
        }
        return res;
    }

    /* MOD_CALCULATION */
    static int MOD = 1_000_000_007;
    static long ADD(long a, long b) {
        return (a + b) % MOD;
    }

    static long SUB(long a, long b) {
        return (a - b + MOD) % MOD;
    }

    static long MULT(long a, long b) {
        return ((a % MOD) * (b % MOD)) % MOD;
    }

    static long POW(long a, long x) {
        long res = 1;
        for ( ; x > 0; x >>= 1) {
            if (x % 2 == 1) res = MULT(res, a);
            a = MULT(a, a);
        }

        return res;
    }

    static long DIV(long a, long b) {
        return MULT(a, POW(b, MOD - 2));
    }
