      x %= mod;

      long y = C(k - 1, k - n, mod, fif);
      y *= pow(b, n, mod);
      y %= mod;
      y *= pow(a, k - n, mod);
      y %= mod;

      ret += x * k % mod;
      ret %= mod;
      ret += y * k % mod;
      ret %= mod;
    }

