        static int Solve(int N, Modular A, Modular B, Modular C)
        {
            Modular ans = 0;
            var a = A / (A + B);
            var b = B / (A + B);
            var c = C / 100;
            var alpha = Modular.Pow(a, N);
            var beta = Modular.Pow(b, N);
            for (int i = 0; i < N; ++i)
            {
                ans += (alpha * Modular.Pow(b, i) + beta * Modular.Pow(a, i)) * Modular.Ncr(N + i - 1, N - 1) * (N + i);
            }
            return (int)(ans / (1 - c));
        }

