          	long b0 = B * 100 * Mpow(A+B,mod-2,mod) % mod * Mpow(100,mod-2,mod) % mod;
          	long d1 = Mpow(a0,N,mod) % mod * Mpow(b0,i+1-N,mod) % mod;
          	long d2 = Mpow(a0,i+1-N,mod) % mod * Mpow(b0,N,mod) % mod;
          	S = (S + (i+1) * c1 % mod * (d1 + d2) % mod) % mod;
