            for (int i = 1; i < 250000; i++)
            {
                MH[i] = MH[i - 1] * H;
                MH[i] %= MOD;
                MA[i] = MA[i - 1] * A;
                MA[i] %= MOD;
                MB[i] = MB[i - 1] * B;
                MB[i] %= MOD;
