            ret %= MOD;
            ret *= FermatCombination.Div(100 - C, MOD);
            ret %= MOD;
            Console.WriteLine(ret);

        }

        public long Calc()
        {
            long ret = 0;
            for (int M = N; M <= 2 * N - 1; M++)
            {
                long r = comb.Combination(M - 1, N - 1);
                r *= MA[N];
                r %= MOD;
                r *= MB[M - N];
                r %= MOD;
                r *= MH[2 * N - M];
                r %= MOD;
                r *= M;
                r %= MOD;
                ret += r;
            }

            for (int M = N; M <= 2 * N - 1; M++)
            {
                long r = comb.Combination(M - 1, N - 1);
                r *= MB[N];
                r %= MOD;
                r *= MA[M - N];
                r %= MOD;
                r *= MH[2 * N - M];
                r %= MOD;
                r *= M;
                r %= MOD;
                ret += r;
            }

            return ret;
        }

    }

    // libs ----------
    // フェルマーの定理、逆元を使う場合
    class FermatCombination
    {
        public long[] Factrial; // 階乗
        public long[] Inverse; // 逆元
        public long MOD = 1000000007;

        public FermatCombination(int n)
        {

            Factrial = new long[n + 1];
            Inverse = new long[n + 1];
            Factrial[0] = 1;
            Inverse[0] = 1;

            for (int i = 1; i <= n; i++)
            {
                Factrial[i] = (Factrial[i - 1] * i) % MOD;
            }

            for (int i = 1; i <= n; i++)
            {
                // フェルマーの小定理で逆元を求める
                Inverse[i] = Power(Factrial[i], (int)MOD - 2, MOD) % MOD;
            }
        }

        public long Permutation(int n, int k)
        {
            return Factrial[n] * Inverse[n - k] % MOD;
        }

        public long Combination(int n, int k)
        {
            return Factrial[n] * Inverse[k] % MOD * Inverse[n - k] % MOD;
        }

        public static long Power(long x, long n, long M)
        {
            long tmp = 1;

            if (n > 0)
            {
                tmp = Power(x, n / 2, M);
                if (n % 2 == 0) tmp = (tmp * tmp) % M;
                else tmp = (((tmp * tmp) % M) * x) % M;
            }

            return tmp;
        }

        public static long Div(long x, long M)
        {
            return Power(x, (int)M - 2, M) % M;
        }
    }

