    {
        long t = x, ret = 1;
        while (n > 0)
        {
            if ((n & 1) != 0)
            {
                ret = (t * ret) % mod;
            }
            t = t * t % mod;
            n >>= 1;
        }
        return ret;
    }
    public void Run()
    {
