    auto winB = Mint(B) / Mint(A + B);
    auto num = Mint(A + B + C) / Mint(A + B);
    auto ans = Mint(0);

    auto F = new Mint[](3*N);
    F[0] = F[1] = Mint(1);
    foreach (i; 2..3*N) F[i] = F[i-1] * Mint(i);

