    }

    foreach (i; 0..N) {
        auto a = winA ^^ N;
        auto b = winB ^^ i;
        auto c = comb(N-1+i, i);
        ans += a * b * c * num * Mint(N + i);
    }

    foreach (i; 0..N) {
        auto a = winA ^^ i;
        auto b = winB ^^ N;
