#[derive(Clone, Debug)]
pub struct MemorizedFactorial {
    n: usize,
    fact: Vec<Modi64>,
    inv_fact: Vec<Modi64>,
}
impl MemorizedFactorial {
    pub fn new(max_n: usize) -> MemorizedFactorial {
        let mut fact = vec![1.into(); max_n + 1];
        let mut inv_fact = vec![1.into(); max_n + 1];
        for i in 1..(max_n + 1) {
            fact[i] = fact[i - 1] * (i as i64).into();
            inv_fact[i] = inv_fact[i - 1] / (i as i64).into();
        }
        MemorizedFactorial {
            n: max_n + 1,
            fact: fact,
            inv_fact: inv_fact,
        }
    }
    pub fn combination(&self, n: usize, r: usize) -> Modi64 {
        if r <= n {
            self.fact[n] * self.inv_fact[r] * self.inv_fact[n - r]
        } else {
            0.into()
        }
    }
    pub fn permutation(&self, n: usize, r: usize) -> Modi64 {
        if r <= n {
            self.fact[n] * self.inv_fact[n - r]
        } else {
            0.into()
        }
    }
    pub fn homogeneous_product(&self, n: usize, r: usize) -> Modi64 {
        if n != 0 && r != 0 {
            self.combination(n + r - 1, r)
        } else {
            1.into()
        }
    }
}
fn main() {
    input! { n, a: i64, b: i64, _c: i64 };
    let fact = MemorizedFactorial::new(n * 2);
    let mut ans = Modi64(0);
    let mut aa = vec![Modi64(1); n + 1];
    let mut bb = vec![Modi64(1); n + 1];
    let a = Modi64(a);
    let b = Modi64(b);
    for i in 0..n {
        aa[i + 1] = aa[i] * (a / (a + b));
        bb[i + 1] = bb[i] * (b / (a + b));
    }
    for i in n..2 * n {
        ans +=
            aa[n] * bb[i - n] * fact.combination(i - 1, n - 1) * Modi64((100 * i) as i64) / (a + b);
        ans +=
            aa[i - n] * bb[n] * fact.combination(i - 1, n - 1) * Modi64((100 * i) as i64) / (a + b);
    }
    println!("{}", ans);
}

