    let comb = Combination::new(2 * n, MOD);
    let mut ans = ModInt(0);
    for i in n..(2 * n) {
        let pa = comb.get(i, n - 1) * a.pow(n) * b.pow(i - n);
        let pb = comb.get(i, n - 1) * b.pow(n) * a.pow(i - n);
