        }
        self.buf.pop()
    }
}

const MOD: i64 = 1000000007;

thread_local! {
    static FACT_MEMO: RefCell<[i64; 200000]> = RefCell::new([0; 200000]);
}

fn fact(x: i64) -> i64 {
    FACT_MEMO.with(|rc| {
        let ux = x as usize;
        {
            let memo = rc.borrow();
            if memo[ux] > 0 {
                return memo[ux];
            }
        }
        let y = if x > 0 { x * fact(x - 1) % MOD } else { 1 };
        rc.borrow_mut()[ux] = y;
        y
    })
}
fn pow(a: i64, b: i64) -> i64 {
    if b > 0 {
        let y = pow(a * a % MOD, b >> 1);
        if b & 1 > 0 { a * y % MOD } else { y }
    } else {
        1
    }
}
fn inv(x: i64) -> i64 {
    pow(x, MOD - 2)
}
fn conb(a: i64, b: i64) -> i64 {
    fact(a) * inv(fact(b)) % MOD * inv(fact(a - b)) % MOD
}

fn f(n: i64, a: i64, b: i64, c: i64) -> i64 {
    let mut y = 0;
    let pa = pow(a * inv(a + b) % MOD, n);
    let ec = 100 * inv(100 - c) % MOD;
    for wb in 0..n {
        let pb = pow(b * inv(a + b) % MOD, wb);
        y += (n + wb) * ec % MOD * pa % MOD * pb % MOD * conb(n - 1 + wb, wb) % MOD;
        y %= MOD;
    } 
    y
}

