    for wb in 0..n {
        let pb = pow(b * inv(a + b) % MOD, wb);
        y += (n + wb) * ec % MOD * pa % MOD * pb % MOD * conb(n - 1 + wb, wb) % MOD;
        y %= MOD;
    } 
    y
}

