mod comb {
    use super::mint::Mint;

    use std::ops::{
        Add, AddAssign, BitXor, BitXorAssign, Div, DivAssign, Mul, MulAssign, Sub, SubAssign,
    };

    pub struct CombMod<T> {
        fact: Vec<T>,
        inv_fact: Vec<T>,
    }

    impl<T> CombMod<T>
    where
        T: Mul<Output = T> + Div<Output = T> + Clone + From<i32>,
    {
        pub fn new(n: usize) -> Self {
            let mut fact = vec![0.into(); n + 1];
            let mut inv_fact = vec![0.into(); n + 1];

            let one: T = 1.into();
            fact[0] = one.clone();
            // for i in 1..=n {
            for i in 1..(n + 1) {
                fact[i] = fact[i - 1].clone() * (i as i32).into();
            }
            inv_fact[n] = one.clone() / fact[n].clone();
            for i in (0..n).rev() {
                inv_fact[i] = inv_fact[i + 1].clone() * ((i + 1) as i32).into();
            }

            CombMod {
                fact: fact,
                inv_fact: inv_fact,
            }
        }

        pub fn get_comb(&self, n: usize, r: usize) -> T {
            self.fact[n].clone() * self.inv_fact[n - r].clone() * self.inv_fact[r].clone()
        }
    }
}

fn main() {
    input! {
        n: usize,
        a: i32,
        b: i32,
        c: i32,
    }

    let a = mrat::Mrat::new(a, 100);
    let b = mrat::Mrat::new(b, 100);
    let c = mrat::Mrat::new(c, 100);

    let (a, b) = (a / (a + b), b / (a + b));

    let comb_mod: comb::CombMod<mrat::Mrat> = comb::CombMod::new(2 * n);
    let mut p: mrat::Mrat = 0.into();
    for i in 0..n {
        let v = (a ^ n) * (b ^ i) + (b ^ n) * (a ^ i);
        let v = comb_mod.get_comb(n - 1 + i, n - 1) * v;
        // let u: mrat::Mrat = (n + i).into();
        p = p * (a + b) + v * mrat::Mrat::from(n + i);
    }
    p /= mrat::Mrat::from(1) - c;
    println!("{}", p);
}

