    let mut b_ab = b * Combination::inv(a + b) % MOD;
    let mut apow = vec![1; n+1];
    let mut bpow = vec![1; n+1];
    for i in 1..n+1 {
        apow[i] = apow[i-1] * a_ab % MOD;
        bpow[i] = bpow[i-1] * b_ab % MOD;
    }

    let mut draw_inv = 100 * Combination::inv(100 - c) % MOD;
    for i in 0..n {
        let game = n + i;
        let awin = comb.comb(game-1, n-1) * apow[n] % MOD * bpow[i] % MOD;
        let bwin = comb.comb(game-1, n-1) * apow[i] % MOD * bpow[n] % MOD;
        total += (game as i64) * (awin + bwin) % MOD;
        total %= MOD;
    }

    println!("{}", total * draw_inv % MOD);
}

