    impl BitXorAssign<i32> for Mint {
        fn bitxor_assign(&mut self, other: i32) {
            *self ^= Mint::from(other);
        }
    }

    impl From<i32> for Mint {
        fn from(mut item: i32) -> Self {
            while item >= MOD {
                item -= MOD
            }
            while item < 0 {
                item += MOD
            }
            Mint { val: item }
        }
    }

    impl fmt::Display for Mint {
        fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
            write!(f, "{}", self.val)
        }
    }
}

