        Add, AddAssign, BitXor, BitXorAssign, Div, DivAssign, Mul, MulAssign, Sub, SubAssign,
    };

    use super::mint::Mint;
    pub const MOD: i32 = 1_000_000_007;

    // numerator / denominator
    #[derive(Clone, Copy)]
    pub struct Mrat {
        numerator: Mint,
        denominator: Mint,
    }

    impl Mrat {
        pub fn new(numerator: i32, denominator: i32) -> Self {
            Mrat {
                numerator: numerator.into(),
                denominator: denominator.into(),
            }
        }
    }

    impl Add for Mrat {
        type Output = Self;
        fn add(self, other: Self) -> Self {
            let mut v = self;
            v += other;
            v
        }
    }

    impl AddAssign for Mrat {
        fn add_assign(&mut self, other: Self) {
            self.numerator =
                self.numerator * other.denominator + self.denominator * other.numerator;
            self.denominator *= other.denominator;
        }
    }

    impl Sub for Mrat {
        type Output = Self;
        fn sub(self, other: Self) -> Self {
            let mut v = self;
            v -= other;
            v
        }
    }

    impl SubAssign for Mrat {
        fn sub_assign(&mut self, other: Self) {
            self.numerator =
                self.numerator * other.denominator - self.denominator * other.numerator;
            self.denominator *= other.denominator;
        }
    }

    impl Mul for Mrat {
        type Output = Self;
        fn mul(self, other: Self) -> Self {
            let mut v = self;
            v *= other;
            v
        }
    }

    impl MulAssign for Mrat {
        fn mul_assign(&mut self, other: Self) {
            self.numerator *= other.numerator;
            self.denominator *= other.denominator;
        }
    }

    impl Div for Mrat {
        type Output = Self;
        fn div(self, other: Self) -> Self {
            let mut v = self;
            v /= other;
            v
        }
    }

    impl DivAssign for Mrat {
        fn div_assign(&mut self, other: Self) {
            self.numerator *= other.denominator;
            self.denominator *= other.numerator;
        }
    }

    // i32
    impl Add<i32> for Mrat {
        type Output = Self;
        fn add(self, other: i32) -> Self {
            self + Mrat::from(other)
        }
    }

    impl AddAssign<i32> for Mrat {
        fn add_assign(&mut self, other: i32) {
            *self += Mrat::from(other);
        }
    }

    impl Sub<i32> for Mrat {
        type Output = Self;
        fn sub(self, other: i32) -> Self {
            self - Mrat::from(other)
        }
    }

    impl SubAssign<i32> for Mrat {
        fn sub_assign(&mut self, other: i32) {
            *self -= Mrat::from(other);
        }
    }

    impl Mul<i32> for Mrat {
        type Output = Self;
        fn mul(self, other: i32) -> Self {
            self * Mrat::from(other)
        }
    }

    impl MulAssign<i32> for Mrat {
        fn mul_assign(&mut self, other: i32) {
            *self *= Mrat::from(other);
        }
    }

    impl Div<i32> for Mrat {
        type Output = Self;
        fn div(self, other: i32) -> Self {
            self / Mrat::from(other)
        }
    }

    impl DivAssign<i32> for Mrat {
        fn div_assign(&mut self, other: i32) {
            *self /= Mrat::from(other);
        }
    }

    impl BitXor<i32> for Mrat {
        type Output = Self;
        fn bitxor(mut self, other: i32) -> Self {
            self ^= other;
            self
        }
    }

    impl BitXorAssign<i32> for Mrat {
        fn bitxor_assign(&mut self, other: i32) {
            self.numerator ^= other;
            self.denominator ^= other;
        }
    }

    impl From<i32> for Mrat {
