mod comb {
    use super::mint::Mint;

    use std::ops::{
        Add, AddAssign, BitXor, BitXorAssign, Div, DivAssign, Mul, MulAssign, Sub, SubAssign,
    };

    pub struct CombMod<T> {
        fact: Vec<T>,
        inv_fact: Vec<T>,
    }

    impl<T> CombMod<T>
    where
        T: Mul<Output = T> + Div<Output = T> + Clone + From<i32>,
    {
        pub fn new(n: usize) -> Self {
            let mut fact = vec![0.into(); n + 1];
            let mut inv_fact = vec![0.into(); n + 1];

            let one: T = 1.into();
            fact[0] = one.clone();
            // for i in 1..=n {
            for i in 1..(n + 1) {
                fact[i] = fact[i - 1].clone() * (i as i32).into();
            }
            inv_fact[n] = one.clone() / fact[n].clone();
            for i in (0..n).rev() {
                inv_fact[i] = inv_fact[i + 1].clone() * ((i + 1) as i32).into();
            }

            CombMod {
                fact: fact,
                inv_fact: inv_fact,
            }
        }

        pub fn get_comb(&self, n: usize, r: usize) -> T {
            self.fact[n].clone() * self.inv_fact[n - r].clone() * self.inv_fact[r].clone()
        }
    }
}

