use algonium::math::Comb;
use algonium::math::{Mint107, Mod107};

fn powm(x: Mint107, y: u64) -> Mint107 {
    if y == 0 {
        1.into()
    } else if y == 1 {
        x
    } else if y % 2 == 1 {
        x * powm(x, y - 1)
    } else {
        powm(x * x, y / 2)
    }
}

fn run() {
    input! {
        n: usize,
        a: usize,
        b: usize,
        c: usize,
    }
    let pa: Mint107 = Mint107::from(a) / 100;
    let pb: Mint107 = Mint107::from(b) / 100;

    let comb: Comb<Mod107> = Comb::new(1_000_000);

    let e = Mint107::from(1) / (pa + pb);
    let wa = pa / (pa + pb);
    let wb = pb / (pa + pb);

    let mut answer = Mint107::from(0);
    for d in n..(2 * n) {
        let d = d as u64;
        let n = n as u64;
        let win_a = comb.comb(d - 1, n - 1) * powm(wa, n - 1) * powm(wb, d - 1 - (n - 1)) * wa;
        let win_b = comb.comb(d - 1, n - 1) * powm(wb, n - 1) * powm(wa, d - 1 - (n - 1)) * wb;
        answer += e * d * win_a;
        answer += e * d * win_b;
    }
    println!("{}", answer);
}

//{{{ template
fn main() {
    let _ = ::std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap();
}

pub trait SetMinMax {
    fn set_min(&mut self, v: Self) -> bool;
    fn set_max(&mut self, v: Self) -> bool;
}

impl<T> SetMinMax for T
where
    T: PartialOrd,
{
    fn set_min(&mut self, v: T) -> bool {
        *self > v && {
            *self = v;
            true
        }
    }
    fn set_max(&mut self, v: T) -> bool {
        *self < v && {
            *self = v;
            true
        }
    }
}

#[derive(PartialEq, Eq, Debug, Copy, Clone, Default, Hash)]
pub struct Reverse<T>(pub T);

impl<T: PartialOrd> PartialOrd for Reverse<T> {
    #[inline]
    fn partial_cmp(&self, other: &Reverse<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }

    #[inline]
    fn lt(&self, other: &Self) -> bool {
        other.0 < self.0
    }
    #[inline]
    fn le(&self, other: &Self) -> bool {
        other.0 <= self.0
    }
    #[inline]
    fn ge(&self, other: &Self) -> bool {
        other.0 >= self.0
    }
    #[inline]
    fn gt(&self, other: &Self) -> bool {
        other.0 > self.0
    }
}

impl<T: Ord> Ord for Reverse<T> {
    #[inline]
    fn cmp(&self, other: &Reverse<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

