// Depends on ModInt.rs
fn fact_init(w: usize) -> (Vec<ModInt>, Vec<ModInt>) {
    let mut fac = vec![ModInt::new(1); w];
    let mut invfac = vec![0.into(); w];
    for i in 1 .. w {
        fac[i] = fac[i - 1] * i as i64;
    }
    invfac[w - 1] = fac[w - 1].inv();
    for i in (0 .. w - 1).rev() {
        invfac[i] = invfac[i + 1] * (i as i64 + 1);
    }
    (fac, invfac)
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input!(n: usize, a: i64, b: i64, _c: i64);
    let (fac, invfac) = fact_init(2 * n + 1);
    let l = ModInt::new(100) * ModInt::new(a + b).inv();
    let a = ModInt::new(a) * ModInt::new(100).inv() * l;
    let b = ModInt::new(b) * ModInt::new(100).inv() * l;
    let mut tot = ModInt::new(0);
    for i in 0..n {
        let p = a.pow(n as i64 - 1) * b.pow(i as i64);
        let p = p * fac[n - 1 + i] * invfac[i] * invfac[n - 1];
        tot += p * a * (n + i) as i64;
    }
    for i in 0..n {
        let p = b.pow(n as i64 - 1) * a.pow(i as i64);
        let p = p * fac[n - 1 + i] * invfac[i] * invfac[n - 1];
        tot += p * b * (n + i) as i64;
    }
    puts!("{}\n", tot * l);

}

